with nuevas(numero,viejo,sec) as (values
(193,'cba2b603170cf1ed66b4d46a6b1d6444',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Òtúrá establece el orden y el sentido de los días de la semana. Pide planear las acciones según los días favorables. También cuenta cómo el sacrificio de una persona fue sustituido por el de un animal."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Necesita planear mejor lo que hace.", "Busca la aprobación de otros antes de actuar.", "Quiere escoger el momento adecuado para una tarea importante (relato de Ọ̀rúnmìlà y los días)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Conocer los días buenos para cada cosa: casarse, mudarse, empezar un negocio.", "Hijos para quien no los tenía.", "Salvarse de una conspiración."]}, {"titulo": "Ibi y advertencias", "puntos": ["Hacer las cosas en el día equivocado.", "Conspiraciones contra un hijo."]}, {"titulo": "Enseñanza principal", "texto": "Un sueño no tiene testigos. Ni siquiera a Ọ̀rúnmìlà se le dio el dominio del sol, pero sí el saber de los días. Se ofrece un animal, nunca la cabeza de un ser humano."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà y la luz del día. Ọ̀rúnmìlà fue a pedirle a Olódùmarè la luz del día para tener poder sobre el sol. Le pidieron dieciséis caracoles, dieciséis gallinas y dinero, y ofreció. Olódùmarè le dijo que no podía darle el control del sol, pero que le daría a conocer los nombres de los días y lo que conviene hacer en cada uno. Òrìṣà ńlá escogió el primer día, Ọ̀rúnmìlà el segundo, Ògún el tercero y Ṣàngó el cuarto: son los cuatro días de la semana de los Òrìṣà, y por eso los mercados de muchos pueblos son cada cuatro días. Además están los siete días: Àìkú, el día de la inmortalidad; Ajé, el día de la riqueza; Ìṣẹ́gun, el día de la victoria; Ọjọ́rú, el día de abrir la puerta y salir; Ọjọ́bọ̀, el día en que el sol retoma su curso; Ẹtì, el día del apuro y la pelea; y Àbámẹ́ta, el día de los tres deseos. Ọ̀rúnmìlà no los creó para adorar a ningún Òrìṣà, sino para saber cuándo casarse, celebrar cumpleaños, empezar un negocio o mudarse. Veintiocho días hacen cuatro semanas de Òrìṣà y un mes.", "Arera, Ọṣù y Ojúdò. Arera, hijo del rey de Ifẹ̀, lloraba porque no tenía hijos, y Ọṣù, hija del rey de Ọ̀yọ́, también. A él le marcaron un carnero y a ella una oveja, y les dijeron que criaran a esos animales pequeños hasta que crecieran. Los dos se encontraron, se unieron y Ọṣù quedó embarazada; Arera pidió que el niño se llamara Ojúdò. Con el tiempo hubo una conspiración: la gente de Ifẹ̀ quería comprar a Ojúdò para que el Ọọ̀ni lo sacrificara. Cuando lo amarraron al suelo, Ojúdò lloró porque lo habían traído cautivo a su propia ciudad, y pidió que le dieran ocho nueces de kola para echarlas: si caían cuatro boca arriba y cuatro boca abajo, debían cantar. Cayeron así, y cantaron: llega Ojúdò, el hijo de Arera; den gracias conmigo porque la kola salió buena; tomen un animal como ofrenda, no tomen la cabeza de un hijo. Desde entonces se ofrece una chiva a Ifá."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para conocer los días: dieciséis caracoles, dieciséis gallinas y dinero.", "Para tener hijos: un carnero (el hombre) o una oveja (la mujer), criados hasta que crezcan y entonces ofrecidos.", "Una chiva a Ifá en lugar de cualquier sacrificio humano."]}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè, dueño del sol. Òrìṣà ńlá, Ọ̀rúnmìlà, Ògún y Ṣàngó, dueños de los cuatro días. Ajé, la riqueza. El Ọọ̀ni de Ifẹ̀."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Obì (ocho nueces de kola), caracoles, gallinas, carnero, oveja, chiva."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 193.1 (yorùbá): Alakonẹri awo Alárá, / Eniyàn koṣe wónránwọ̀nrán / kio tọrọ esẹ̀ ẹnikeji rẹ / ṣe wọ̀nránwọ̀nrán: / a daa fún Ọ̀rúnmìlà / nhọ tọọ Qjọ̀ (Oorun) lọwọ Olódùmarè, / ki apa òun baa lẹka qjọ̀. / Wọ̀n niki Ọ̀rúnmìlà rú: / İgbin mẹrindilógún, adiyẹ merindilógún, / ati egbàá merindilógún owó. / Ọ̀rúnmìlà gbọ̀ ó rú. / Olódùmarè ni: / \"òun ko ma niile fi qjọ̀ fun un, / ṣùgbọ̀n òun yoo jẹki o maa mọ oruką / gbogbo àwọn qjọ̀ ati àwọn ohun / ti o dára lati maaṣe ninu wọn li Ayé\".", "/ OTRUPON OTURA", "REZO: OTRUPON TAURO IRE NIFA PORI IFA NI KAFEREFUN OBATALA ATI SHANGO.", "REZO: IRENIFA PORI IFANI KAFEREFUN OBATALA Y SHANGO.", "REZO: DURE DURE NINCHE QUINI NIMU ONI ADIFAFUN OLE ASO OLLOLLU ILLA OWO OLO AWO ERA LEBO AGUOTA IKU CAPAPA PELLE OPA UNASOCUN ELEBE UNSOCUN ICU ADIFAFUN LLEPA AKUKO LEBO AMARORA INTORI ARU IBODICA KALE KALE ODARE FUN NITA APARO ADIFAFUN ELEGUE ARA AKUKO LEBO.", "REZO: IFA INTORI IKU AIKORDIE FUNFUN ADIE FUNFUN ADIE MEYI FUNFUN ORI EFUN NERBRIN ASHO FUNFUN (8 VARAS) EKU EYA EPO OBI MENI OWO MELLO.", "REZO: IREMIFA FUERI IRE ARICU OSHANLA Y SHANGO ORDAFUN OLOFIN.", "REZO: OBALAYE NI AYU ODARA ISHE AMO INTORI OFO KAFEREFUN SHANGO ATIE ELEGBARA."]}]$q$::jsonb),
(194,'b5446dbf0865b9f8eb5f6dea935d9973',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Ìrẹtẹ̀ pide ofrenda para prevenir enfermedades y vencer a los enemigos. El consultante necesita estrategia y planes para triunfar; viene una guerra o un enfrentamiento."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le preocupa la salud de un niño; conviene llevarlo al médico (relato de Iyá Adepon).", "Se prepara para un conflicto real.", "La terquedad le impide atender avisos importantes (relato del Ọwá de Ìlẹ̀ṣà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Hijos protegidos de enfermedades de la piel.", "Vencer en la guerra o en el pleito."]}, {"titulo": "Ibi y advertencias", "puntos": ["Enfermedades graves en los hijos.", "Guerra que llega sin preparación.", "Negarse a ofrendar por orgullo."]}, {"titulo": "Enseñanza principal", "texto": "La guerra se gana antes de empezar, con estrategia y ofrenda. Quien rechaza el consejo la pierde."}, {"titulo": "Relatos reunidos", "puntos": ["La madre de Adépọ̀n, la papaya. A la madre de Adépọ̀n le pidieron cuatro aves negras (dos gallos y dos gallinas), dinero y medicina de Ifá para que sus hijos no sufrieran de lepra. Oyó, pero no ofreció. La madre de Adépọ̀n es el nombre que se le da a la papaya. Ante manchas en la piel que no se curan o pierden sensibilidad, conviene ir al médico.", "El Ọwá de Ilẹ́ṣà y la guerra. Al Ọwá de Ilẹ́ṣà le avisaron: ¡allá viene la guerra! Le pidieron la cabeza de un carnero, medicina de Ifá y dinero para derrotar a sus enemigos. Oyó y se negó. Cuando el consultante sí ofrece, se pone la cabeza del carnero sobre su Ifá con el rezo: con la cabeza del carnero se gana la guerra."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la salud de los hijos: cuatro aves negras (dos gallos y dos gallinas), dinero y medicina de Ifá.", "Para la guerra: la cabeza de un carnero, medicina de Ifá y dinero; la cabeza se pone sobre el Ifá del consultante."]}, {"titulo": "Relaciones espirituales", "texto": "El Ọwá de Ilẹ́ṣà. Ifá da la victoria a quien prepara la guerra."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Papaya, aves negras, cabeza de carnero."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 194.1 (yorùbá): Òtúrúpọ̀n-Rẹte: / a difá fún lyá Adepon, / Wọ̀n niki lyá Adepon wa rúbọ / ki àwọn qmọ rè ma baa ri'bi àrùn Etẹ̀. / Ebọ: Adiyẹ dúdü mérin takotabo, / egbètalélógbọ̀n owó ati ewé Ifá. / Ó gbọ̀ ko rubọ. / lyá Adepon oruko ti aipe Ibẹpẹ.", "Verso 194.2 (yorùbá): Òtúrúpọ̀n-Rẹte: / a difá fún Qwa lleṣa. / Wọ̀n ni: / \"Qwá lleṣa, Ogún ma de\" / Wọ̀n niki o wa rúbọ / kiobaa le ségun àwọn ọ̀tá rè. / Ẹbọ: Agbo (ori-aiṣe), / ewé lfa ati egbaá mokanla owó. / Qwá gbọ̀ ko rúbọ.", "REZO: OTRUPON BIRETE IFA AYALU SHISHE SHE ADAFUN AYALU PUETE MORUBO OMO SHESHE SHE NI OLO BABALAWO ADIFA BABALAWO OLOFIN YELO PUELO ODAFUN OZAIN MORUBO, OWUNKO SHELO, AKUKO LEBO.", "REZO: EÑA META MOSHOTA OKAN PUPA OBINI OYO ABO LEBO ADIFAFUN OLUO UMBATINLO NISHE ABO LEBO EYELE LEBO.", "REZO: AYA TU SHESHE AYALU PATE ONI BABALAWO ADIFAYOKO. MAFEREFUN OBATALA OSHOSI Y ESHU.", "REZO: IFA AYALU SHESHESHE ARDAFUN AYALU KUETE MORUBO OMO SHESHESHE NI OLO BABALAWO ORDIFA OLOFIN YALU KUELE ORDAFUN OZAIN MORUBO SUNKO SHELE EKIKO LEBO EGUIÑOLA."]}]$q$::jsonb),
(195,'0a62fc4e2de419d4a7bcccc39f4b3d3a',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Ọ̀ṣẹ́ habla de ofrendar para tener una vida agradable. El consultante necesita relajarse, sentir placer y alegría como los niños. Los padres deben ganar primero para que los hijos coman."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Necesita descansar y recuperar la alegría (relato de Ọ̀rúnmìlà y la vida más dulce).", "Tiene niños a su cargo que atender con responsabilidad.", "La familia teme que falte lo necesario tras el nacimiento de un hijo (relato del árbol Jẹwẹrẹ)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Una vida dulce y placentera.", "Madre e hijo sin necesidades."]}, {"titulo": "Ibi y advertencias", "puntos": ["Amargura y tensión constantes.", "Necesidad y carencia para la madre y el niño."]}, {"titulo": "Enseñanza principal", "texto": "El mundo no es tan dulce como para vivir en él para siempre; solo los niños dicen que es agradable. Los hijos comen la comida de los niños, pero primero los padres tienen que ganarla."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà y la dulzura del mundo. Adivinaron para Ọ̀rúnmìlà y para toda la gente, y le pidieron a él una paloma, una gallina de Guinea, miel y dinero para que el mundo fuera dulce para los seres humanos. Ọ̀rúnmìlà preguntó cómo iba la gente a conocer el placer del mundo si ellos mismos no ofrecían. Le respondieron que los hijos comen la comida de los niños, pero que primero los padres tienen que ganarla para darles. Ọ̀rúnmìlà ofreció. Después les pidieron a todos los seres humanos que ofrecieran por su bien; solo algunos lo hicieron, y esos tienen una vida dulce.", "Jẹ̀wẹ̀rẹ̀, el árbol de la pimienta. Jẹ̀wẹ̀rẹ̀, el árbol que da la pimienta, tuvo un hijo nuevo. Le dijeron que madre e hijo pasarían necesidades si no ofrecían seis palomas, seis gallinas, dinero y medicina de Ifá. Oyeron, pero no ofrecieron."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para una vida dulce: una paloma, una gallina de Guinea, miel y dinero.", "Para madre e hijo: seis palomas, seis gallinas, dinero y medicina de Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà ofrece primero por la humanidad."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Miel, gallina de Guinea, árbol de la pimienta."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 195.1 (yorùbá): Ayé ko dùn to ibiti aigbe titi, / Ọmodé li o nwipe ayé dára: / a daa fún Ọ̀rúnmìlà, / a bu fún (àwọn) èniyàn. / Wọ̀n niki Ọ̀rúnmìlà wa rúbọ / ki ayé le maa dùn fún (àwọn) èniyàn. / Ebọ: Ẹyẹlé, eye-ẹtu (awo), oyin, / egbàá mọ̀kànlélógún owó. / Ọ̀rúnmìlà I: / biwọn ko ba tikalarawon ṣe / ohun ara wọ̀n, / Wọ̀n ha le mọ adùn li ayé bayi? / Wọ̀n ni: / omọ aṣe k'ọmọ i jẹ, / Baba omo niikọẹ ṣe fún omọ jẹ. / Ọ̀rúnmìlà gbọ̀ ó rú. / A niki awon èniyàn wa ṣe ẹbo / ti o kan wọn, / wọn nwa diẹdiẹ. / Eniti o ba ṣebo ayé rè a dùn!", "Verso 195.2 (yorùbá): Òtúrúpọ̀n-Ṣé: / a difá fün Igi-Jẹwẹrẹ. / Igi-Jẹwẹrẹ bimo titun s'owọ, / wọ̀n ni: / omotitun ati iyá rè, / biabape ki ojú ma pòn wọ̀n / ati omo ati iyá ki wọ̀n rúbọ: / Eyẹlé méfà, adiyẹ mẹfà, / egbaa méfà owó ati ewé Ifá. / Igi-Jẹwẹrẹ oruko ti aipe ata (igonran). / Ó gbọ̀ ko rúbọ.", "REZO: OTRUPON SHE IFA OLA RUDALE AWO OBA NITEPA ILEKE OLA NITEPA OSHEDE ODAFUN BOGBO ARUMALE TINLO OKU AKASA EYELE, ADIE, ESCALERA LEBO.", "REZO: ORAN DIDARE ERANTIRA ELEQUE OBAN TIREPA OBAN TIREPA OCHODO IDE ADIFAFUN BOBO ORUMILA OCU ACARO LEBO ELERA EYELE ADIE COBO BABA MOBO CHECHE ODOÑO ADIFAFUN TETE ARE EURE IFA NI OBEYU AKUKO EYELE LEBO.SHANGO YALORDE IFA ONIRE.", "REZO: OTRUPON SHE IFA OLA RUDADE OWO OBA NITEPA ILE QUE OLA NITEPA OCHO DE ORDAFUN LORBO ORUMALE TINLO OCU AKASA EYELE ADIE BABA ESCALERA EBBO. MORDO ACHECHE ORDOÑO ACUE URE OBIRICA LOMBARU MAZORCA TU LERI OMO. KAFEREFUN OBANLA OBALOPAN OSHUN.", "REZO: OTRUPON SHE OBE NI DELE AWO OMO FO OTRUPON SHE ABASHE OMO LALA NI SHANGO OTRUPON SHE IYA FAREO OMO LELE OYA ONIYA.", "REZO: OBAN DIDARE OBAN TIRA ELEGUE OBAN TIREPA OSHIDE IDE ADIFAFUN ORUNMILA EKU AGOGO LEBO ELEGBA FALESILE ADIECOBO BABA NOBITISHE ODOÑO ADIFA ARE BURE IFANI ILU SHANGO YALORDE IFA ONIRE."]}]$q$::jsonb),
(196,'efe3eeb07f5b4968d168b8e25a8c08fd',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Òfún habla de compartir parte de la buena fortuna: la vida del consultante se ha llenado de bienes, dinero y afecto. Quien tiene mucho y da a los necesitados nunca pasará carencias. Anuncia la visita de una mujer con un bebé en la espalda, que debe entrar con buen pie."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Disfruta de recursos o de tranquilidad.", "Se pregunta cómo ayudar a alguien que lo necesita (relato del árbol Osan).", "Una visita va a traer cambios a la casa (relato de la mujer con el bebé a la espalda)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Abundancia económica y emocional.", "Nunca tener carencias.", "Una visita que trae buena fortuna a la casa."]}, {"titulo": "Ibi y advertencias", "puntos": ["Guardar todo para sí.", "Que una visita entre con mal pie."]}, {"titulo": "Enseñanza principal", "texto": "El que tiene mucho debe dar algo a los que necesitan, y será bueno para siempre. Como el naranjo, que da fruta a todos."}, {"titulo": "Relatos reunidos", "puntos": ["El naranjo. Al naranjo (ọsàn) le aconsejaron que diera de comer y de beber a los demás, y que si ofrecía nunca tendría carencias. Le marcaron un paquete de sal, una cesta de camarones, tela blanca y dinero. Ofreció, y se dijo: el que tiene mucho debe dar algo a los necesitados; así nunca le faltará.", "La visitante con el bebé. A un terrateniente le dijeron que pronto recibiría la visita de una mujer que cargaba un bebé en la espalda, y que debía ofrecer dos palomas y dinero para que ella entrara a su casa con buen pie. Ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para no tener carencias: un paquete de sal, una cesta de camarones, tela blanca y dinero; y compartir con los necesitados.", "Para la visita: dos palomas y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "La generosidad sostiene la fortuna."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Naranjo (Citrus), sal, camarones, tela blanca."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 196.1 (yorùbá): Òtúrúpọ̀n-Fún: / a dífá fún igi-Qsàn, / Wọ̀n niki igi-Qsàn / maa fún wọn jẹ, / kiomaa fún wọn mu, / Igi-Qsan komaa yee ni biobarúbo. / Wọ̀n niki ó rú: / ogọ-iyç, agbọ̀n-ede, aṣo-funfun / ati egbàá mẹsan owó. / Ó gbọ̀ ó rú. / Òtúrúpọ̀n-Fún (wọ̀n) ni: / \"Niti o ba ni pupo / kiofi diẹ fün ẹniti koini, ti nwa kiri, / To abariwon, / iwọ ko maa yee ni\".", "Verso 196.2 (yorùbá): Òtúrúpọ̀n-Fún: / a difá fun baálé ilé, / Wọ̀n ni: / \"àlejò kan maa fuu, / abiyamo olọ̀molehin ni\" / Ki baalé rúbọ / kio lebaa fi esè rere tẹ ilé. / Ṣbọ: Eyẹlé Méjì ati egbejielógún owó. / Ó gbọ̀ ó rú.", "REZO: OTRUPON BALOFUN BABA BATE BABA FETO LODAFUN INLE. LODAFUN OLONU ADIFAFUN OBATALA, ATI OYA. ORUNMILA LORUGBO.", "REZO: TIO CANLE ERECAN ORUN ADIFAFUN OBATALA UMBATI IKU UMPA LLICA EBOMI ERU CAMASI LLILLU ACO FUNFUN ASUNACU LABO EUCHE ACHE OBATALA ULE CHOLO DURO ADAFUN ERE ADIE LEBO ETU ASHO TININI LARA EYELE EBO LEBO. KAFEREFUN ELEDA Y OBATALA.", "REZO: IFA OSU BURU OFO ELLO OTA OBINLE ARACORDIE SI GUONI ORDA ADIE ASHO ETU INTORI ANRU.", "SUYERE: AYANAKU KUSHE ASHE TIMINI BARA.", "REZO: OGGUN ADIFAFUN OBE LOKADA YOBE LO BEMBE INA SHANGO, INA IRIN LAYEUN OBE AÑARI BOGBO NIWASHE OLOFIN OBE GURUYONU ENI LODAFUN OLOFIN.", "REZO: MAFEREFUN ALAFIA, ODDUDUWA, EGGUN.", "REZO: BATO BABA PETO ÑODAFUN ADIFAFUN INLE LODA OLONU ADIFAFUN OBATALA.", "+++"]}]$q$::jsonb),
(197,'1dc5cd3100667c9f9f6437950505d10e',$q$[{"titulo": "Idea central", "texto": "Òtúrá Ogbè habla de la pérdida de confianza en uno mismo después de sufrir pérdidas. Si la consultante está embarazada debe ofrendar para que el hijo nazca sano. Promete que quien parece haberse quedado quieta mirando pasar la vida puede llegar a ser grande."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente inseguro después de una pérdida (relato del maíz Agbàdo).", "Hay un embarazo que le preocupa y conviene llevarlo con control médico.", "Espera una oportunidad y siente que su vida está detenida (relato de Olókun-Ṣonde, que llega a reina de las aguas)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Recuperar la confianza.", "Llegar a ser grande después de una vida que parecía sin sentido.", "Un parto sano."]}, {"titulo": "Ibi y advertencias", "puntos": ["Que otros se coman lo que uno produce.", "Desánimo por las pérdidas."]}, {"titulo": "Enseñanza principal", "texto": "La paciencia no es quedarse sin hacer nada: quien espera y ofrenda llega a reinar sobre las aguas."}, {"titulo": "Relatos reunidos", "puntos": ["El maíz y su producto. Cuando el maíz llegó al mundo por primera vez, le pidieron una ropa nueva y un chivo para que la gente no se comiera lo que producía. Se negó a ofrecer, y desde entonces la gente se come el maíz.", "Olókun Ṣọ̀ndé, reina de las aguas. Olókun Ṣọ̀ndé estaba sentada con paciencia mirando pasar su vida, que parecía no tener sentido. Le dijeron que se volvería grande si ofrecía dieciséis tinajas de agua, dos carneras y dinero. Escuchó y ofreció, y se volvió reina de todas las aguas que corren."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para proteger lo que se produce: una ropa nueva y un chivo.", "Para engrandecerse: dieciséis tinajas de agua (àmù), dos carneras y dinero.", "Para el embarazo: la ofrenda que marque Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Olókun, reina de las aguas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Maíz, tinajas de agua, ropa nueva."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 197.1 (yorùbá): Penrenmiyenmi, / Penrẹnmiyenmi. / Ọràn mi d'ete, / Ọràn mi d'ero: / a dífá f'Àgbàdo, / maa t'ode ọ̀run rọs'Aye. / Wọ̀n niki ó wa rúbọ / ki àwọn ọmo aráyé / ma baa maa fi qmp rẹ jẹ. / Aṣo odün kan ati obúko ni ẹbọ. / Ko rúbọ.", "Verso 197.2 (yorùbá): Alukerese-f'irakororin: / li o dífá f'Olókun-Ṣonde, / o gọ o nwo ni. / Wọ̀n niki ó rúbọ / nigbi ayé rẹ wa ni ṣenpẹnnẹ. / Wọ̀n ni: \"a di nlá\" / Ẹbọ: Àmü mẹrindilógún, / àgutàn Méjì ati ẹgbàá mẹrindilógún owó. / Ó gbọ̀ ó rú. / O di Ọba-Onibu-omi.", "/ OTURA EJIOGBE", "REZO: OTURA NIKO LIKO IKOREWA LIKO IKOBIE KOSI ADIFAFUN DADURO ABO ATI OTI ELEBO.", "REZO: OTURA NIKO ORIKO LOWO ABANSHE AYE AWO KOTANSHE EÑI REWE A FEFELORUN ORISHAOKO AYE OWE ADOBALE MOFORIBALE YIKETUN, MOFORIBALE YEKOSI ASHE. OLORUN KOKOIBERE ODOGAN AFEFE ETU AFEFE LORUN ORISHAOKO.", "SUYERE: ORISHAOKO, DIDE BABA KAREE KARE LAWA.", "REZO: OTURA NIKO OTURA NIKO OTUANI IKO ONIKO OTUA NICO CUPON OMO ORUNMILA KAFEREFUN ESHU.", "REZO: OTURA NIKO ONIPO ONICO IKU ILLA ONICO OFO ONIKO OWO ONICUO OMO ONICO ARICU BABAGUA IRE UMBO.", "REZO: ARICOGUOSO BENSE OMO ORUMILA QUE TECHE ADIFAFUN FADA ABO ILU LORUBO ONARIRI ADIFAFUN OLUCUNI IDE QUERE AFIFORA IGUI LANCUI BAILACHE INLEGUA EGUE LONI ADIFAFUN APARO BATERILLO CHOCO MATIA ADIE MENI LECHINICO OMI ATILICO OMO LLI LLELLE GUINICHOSO AKUKO CHUCA EGUE ERU AKUKO EYELE LECHUMI.", "REZO: OTURA ONICO IFA ALELELLEOMO EDI ACCAUN PERO OMO ESU ILLONI DORDE OMOEDU HERIGUOFO ECUN DALLO Y LOGUA ORDABARA HABAN MIREOGUN NIRE HIPORE OBA EGUE URE MARUN COLOGUO OFO SOE SOGA COMURA AGUERURE MARUN A UN EGUE O FE BAPA AUN OMO METE TENIOBAPA ORDO LLOTA HICORIA OLOTO COCO ERA TOCO COCO SINO AGUAN OGUELE HIBO ELLE ELULLU LLE OSO NIDEQUI OLLI COGUGU ALLA OLLADE SE LLU ONA OPE EYELE OPUE ACOSUN PARE OPE ILLENI DORDO ORDO IRI GUOGUO OCUNDALLO LEGUA.", "REZO: OTURA NIKO OMIKO GUE OBEBELONA NIKU IRE OFO FEFESHO OMO ONIKO AWO OMO ODUDUWA DADA ABAYENI IBAGUA LA YERE IKU OTURA NIKO ONIKO ABENI YEKU ODUDUWA OLOKUN ABEYENI MOZAZARAZAIN BAYENI ONI BABARA NIYEGGUN EBBO.", "REZO: OTURA NIKO OBESAYE ANO AFETACHE OBARA NI LORUN KEKERE OBA OBAYIRE OMO, OTURA NIKO BEYENI EGGUN OBA LODENI SHANGO OBANI EGGUN ONI BARABA NIREGGUN IBASHE OTURA NIKO ORIKOLOWAO ORIKOLOMO EGGUN OBANIYOWA AWO ORUN EBANIRE YEKUN OLOFIN BI AYE IFA ASHE ORIKOLOWA ORIKO MAYENI AWO DADA IFA ASHE OTA OBA INLE LANIRE AWO IFA ODUDUWA.", "REZO: ADIFAFUN IKU ALASHONA OUMBO WA NI ELEGBA ISHONSHON MOGUAYEMI OBA LELE IROKO, OBA LELE ORUNMILA ORE LAGUA, OBA IKU YONYERE AMAI YEKUN BELELE IYA LAYE LOKUA ARIKU ENI ORUNMILA OUN SODE OTURA NIKO UMBO ATEFA NI EGGUN, ABORAN IKU, ABORAN OLOFIN YEGUE INLE, OBA IKU ONIKA ODOBO SOKUN SOKUN IROKO, SOKUN SOKUN GBOGBO IYA KALALU ELEBO IRU ELEBO MOYONI IKU ORUNMILA AKUAYE AKUALOSINA IYA LAYE OBA IKU.", "SUYERE: “ OTURA NIKO OTUA DOLOGUE ASHO IKU YANAYAN ASHE IKU AYE ASHE IKU OLORUN”.", "REZO: BABA OTURA NIKO ADIFAFUN SHANGO OLADABA ESHIN OFOYUDE OMO BURUKUYULE OKUNI ARUGBO OMO KANKURU OMO ODARA ELEGBA ELADAFA ORUBO LODAFUN ORUNMILA.", "REZO: BABA OTURA NIKO ORIKO EGGUN MOWA ASHIRI MAYE ALOSIN AMUBA LALE ALUTA MOWAYE EYO MOWAYE MALU MOWAYE OLOGBO MOWAYE AIYE MOWAYE KENEUN MOWAYE EKUN MOWAYE ESHINSHIN OLONI IYA TOBI OMOKEKERE ADAMALAPA LODAFUN IYA KAFEREFUN OZAIN.", "REZO: BABA OTURA NIKO RIKO RIKO RIKOSHE RIKO RIKO EGGUN ORINOWA ADIFAFUN ODUDUWA ORIBAWA YESA INLE IRE AYE OKUNI ERU OMO ODUDUWA OMO SAJONI AWO OMO LASHE IFA AWAGBEMI ABE IFA SAJONI SOKUN LADE NI IFA SHONSHON EBORI LEKUN ODUDUWA BAWA AWO ODARA SAJONI IFA IMOLE ODDUN SHANGO ABI ODARA IMPORI AWO OTURA NIKO RIKOSHE PARADO ORUGBO OKUNI OPA BIEÑU INSHE AISHELEKUN AWO SAJONI ODARA UNTEFA UNSODE BABATOBI EGGUN AKUKO ODARA EBBO UNANADE BABARI IFA LEDE ARUN AYARA ORUN AYARA ODDUN ATARA OZAIN AWO SAJONI ODARA BEYEBE IFA ODUDUWA LODAFUN ORUNMILA KAFEREFUN SHANGO.", "REZO: OTURA NIKO OYESADE AWO OFENTANSHE OBARANILOKUN KARERE OBA. OBAYIRE OMO OTURA NIKO BOYEMI EGGUN OBA LODO NI SHANGO OBA NI EGGUN ONI BARABANIREGUN IBASHE OTURA NIKO ORIKO LOGUA ORIKO OMO EGGUN ANANI LAWA AWO ORUN OBANIYE EGGUN OLOFIN BI AYE IFA ASHE ORIKO LOWAO ORIKO MAYENI AWO DADA IFA IRE ASHEGUNOTA OBA INLE LARENE AKUKO IFA ODUDUWA."]}]$q$::jsonb),
(198,'5a3664991145ee102bd863d93e259b8c',$q$[{"titulo": "Idea central", "texto": "Òtúrá Ọ̀yẹ̀kú advierte contra entrar en una relación que deslumbra a primera vista pero que al final trae dolor y pérdidas. Pide pensar bien antes de comprometerse en pareja, sociedad o negocio por muy atractivo que parezca."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le atrae una relación, una sociedad o un negocio que parece prometedor (relato de Otú y Oyẹ).", "La atracción del momento no le deja ver las consecuencias.", "Busca algo que dure sin apresurarse."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Saber distinguir a tiempo lo que conviene.", "Protección contra una seducción peligrosa."]}, {"titulo": "Ibi y advertencias", "puntos": ["Una pareja o socio que encanta y luego arruina.", "Creer que la ofrenda hecha hace tiempo sirve para todo.", "Ofrendar solo cuando el daño ya está hecho."]}, {"titulo": "Enseñanza principal", "texto": "Lo que más deslumbra no siempre conviene. Cada situación nueva pide su propia ofrenda; la de ayer no cubre el peligro de hoy."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀tú el barquero y la bella Ọyẹ. Ọ̀tú trabajaba como barquero. Su adivino le anunció que una mujer muy bella subiría a su bote junto con otros pasajeros, que él querría casarse con ella y que ella aceptaría si se lo proponía; se llamaba Ọyẹ. Le pidió ofrecer cuanto antes abundante aceite de palma, dinero y medicina de Ifá para que Èṣù no lo empujara a hablarle a esa mujer, porque ella podía causarle la muerte. Ọ̀tú respondió que hacía tiempo ya había ofrendado por eso y que Ifá lo había aceptado. No ofreció hasta que se dio cuenta de que la mujer le traía problemas."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Abundante aceite de palma, dinero y medicina de Ifá, cuanto antes.", "Medicina: hojas de ojúùsájú y de ẹ̀ṣọ trituradas en agua y mezcladas con jabón para bañarse."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù puede empujar a la tentación si no recibe su parte."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aceite de palma, ojúùsájú (Petiveria alliacea), ẹ̀ṣọ (Elytraria marginata), jabón."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 198.1 (yorùbá): F'orilaku awo Òtú, / Otú olokọ oju-omi. / Wọn ni: / \"Obirin Kan nbowa pelu àwọn ero / wa wọ inu qkọ rẹ. / Obirin naa dára pupo. / Yoo wu ọ pe kio fiṣe aya. / Biobaa sọrọ i yoo gba. / Qyẹ ni wọn npe Obirin naa\" / Ki o yara rúbo. / Ki Eṣú ma ti ọ lọ baa sọrọ. / Ki iwọ ma ba kú. / Ebọ: Perẹ epo Méjì tabi epo pupo, / egbàá méjilá owó ati ewé Ifá. / Ôtú gb'ẹbọ e rú. / I: \"ebọ ti òun ti nrú latijó a da\". / Oun koleṣe ki oun mafẹ arẹwa Obirin.", "REZO: OTURA YEKU MALU AWONIKA ADIFAFUN ONIKA AKUKO LEBO. AGUIBOABURI KEKE OGO ADIFAFUN AKI UNBATINLO LOWO VALA YELEGGUNLOBO AGUTAN, EYELE, ETU LEBO.", "REZO: MALU AGUONICA ADIFAFUN ONICA AKUKO LEBO AGUIBO ABARICOCO OGO ADIFAFUN AQUI UMBATINLO LOGUO BALA ALLELEGAN LEBO OGUNTAN EYELE ETU LEBO. IFA OYAGUO LLAGUO AFIÑARI LA OWO. OPALLERE COGOLLO DE HIOCO.", "REZO: ADIFAFUN ABITAYOLOROKUN KOKONU ABITA, EGGUN LAYIRE NIABITA MOGUA ADE OKUNI NUNURU ABITA AWOLODE BELELE EGGUN BUBURU LORDAFUN ESHU.", "REZO: OTURA YEKU MOLU AGRONIKA, ADIFAFUN ONIKO OKE, EÑAZA ODIDI ABA OPE BORO INDOKO ORUN SHONSHOLO ATOSA AKIYA, OKUTEKAN EBONI AKUKO IGUIBO ABARI FOGORO, ADIFAFUN TOSENO UMBATILO LOWEYE EYELE KAN ABETE APITIN."]}]$q$::jsonb),
(199,'a2845fa91dbe8920c8bb9115ab174037',$q$[{"titulo": "Idea central", "texto": "Òtúrá Ìwòrì pide no actuar con impaciencia, porque todas las cosas buenas ya vienen en camino. El consultante no debe aceptar la primera oferta. Es un año de prosperidad para quien ofrenda."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene una oferta y lo presionan para aceptarla ya (relato de Akinsuyi y la sopa demasiado caliente).", "Un proyecto empieza a dar resultados (relato de los bienes en casa y en la granja).", "Busca colaborar o servir a otros mientras llega algo mejor."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Buena suerte en la casa y en el campo.", "Un año de prosperidad.", "Pareja que llega sin costo."]}, {"titulo": "Ibi y advertencias", "puntos": ["La prisa que quema.", "Aceptar lo primero que se ofrece."]}, {"titulo": "Enseñanza principal", "texto": "No se sorbe la sopa caliente por hambre: el que lo hace se quema la boca. Ifá, cuando reúne todo lo bueno, prepara la comida de la fortuna."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà y la comida de la fortuna. La buena suerte en la casa y en el campo pertenece al que maneja la azada, al hijo que come de todo y al hijo que tendrá mujer sin pagar por ella. Así adivinaron para Ọ̀rúnmìlà, y le dijeron que Ifá, cuando reúne todo lo bueno, prepara la comida de la fortuna. Le pidieron una carnera, una paloma y dinero, y ofreció.", "Akínṣúyì y la sopa caliente. No se sorbe la sopa caliente por hambre, porque se quema la boca. Así adivinaron para Akínṣúyì, y le dijeron que ese sería un año de prosperidad si ofrecía una chiva, una gallina, pescado, una rata y dinero. Escuchó y ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la fortuna: una carnera, una paloma y dinero.", "Para el año próspero: una chiva, una gallina, pescado, una rata y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá cocina la comida de la fortuna para sus hijos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Pescado, rata, azada."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 199.1 (yorùbá): Ifa-ilé, / Ifa oko niti Aruką / Ọmọ maa jẹ ohun gbogbo / Ọmọ maa n'obirin ofẹ: / a difá fOrúnmilà / Wọ̀n ni: / Ifá maa fi ohun rere gbogbo se Ifa jẹ. / Ẹbọ: Agutàn, eyelé ati egbàáwa owó. / Ó gbọ̀ ó ru.", "Verso 199.2 (yorùbá): K'amafi'pónjú iyàn la obẹ gbigbona, / Bi a ba fi ipónjú iyàn la obẹ gbigbona / a maa jo'ni lẹnu. / a difá f'Akinsuyi. / Wọ̀n ni: / \"Odún ọrọ̀ de, ki ó rú\": / Ewúré, adiyẹ, eku, eja / ati egbàásan owó. / Ó gbọ̀ ó rú.", "REZO: OTURA POMPEYO ADIFAFUN IYA MO AYE YEMAYA ASESU OFO ORISHA IMOLE ORUBO BABA OLOKUN YIMIDEREGBO EGGUN OLONA OKUN MAYEWA LELE OFO LERI OFO ELEDA, KAREREFUN OLOKUN, LORDAFUN ORUNMILA.", "REZO: ADIFAFUN IYA MOEYA YEMAYA ASESU OFO ORISHA IMOLE ORUBO BABA OLOKUN YEMI DEREGBE EGGUN OLONA OKUN MAYEWE LELE OFO LEI OFO ELEDA KEREFUN OLOKUN, LORDAFUN ORUNMILA.", "REZO: ADIFAFUN OTURA AWO ASESU ABAYA AYO NIRE OYU YEWE AYABA AWO ALAYOTA OKUNI ELEGBA AWO AGBA BOGBO NOWA OKUN OLOJUN OMO TERIBAWA BI ALE ELEGBA BALE AFI OMO AYO FUNAYO OTURAWO MUN AYODUN MOKI OTA ADELENIFA MOKI OKUE AWO ALAYO OTA ERE LARI OMO AYIOSHE KANIWAYE LERI AKANI BAWA AYO IRU AYO ADELE BAWA LODAFUN YEWA IFA NI KAFEREFUN ORUNMILA."]}]$q$::jsonb),
(200,'81b0325e2d4b92d10cdbbbc73d7166da',$q$[{"titulo": "Idea central", "texto": "Òtúrá Ìdí habla de un hijo que heredará la corona de su padre y de una pareja donde uno de los dos domina y controla al otro. Pide ofrenda para la vida larga del heredero y para que la relación no sea de miedo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Puede tocarle asumir una responsabilidad de la familia o el lugar de su padre (relato de Orí-Awo).", "En una relación hay control o miedo (relato de Adi e Iyalẹta).", "Debe revisar lo que espera de una herencia y de su independencia."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Heredar la posición del padre.", "Vida larga."]}, {"titulo": "Ibi y advertencias", "puntos": ["Vivir temblando ante la mirada de la pareja.", "Una relación con un compañero muy controlador."]}, {"titulo": "Enseñanza principal", "texto": "El aceite de palma cuajado de la madrugada se derrite en cuanto sube el calor del mediodía: el carácter blando cede ante el dominante. La pareja necesita equilibrio."}, {"titulo": "Relatos reunidos", "puntos": ["Orí Awo y la corona de su padre. Ariba de fondo rojo adivinó para Orí Awo, descendiente del pueblo de Omùkọ́ Ẹ̀gì, y le dijo que llevaría la corona de su padre, pero que debía ofrecer una carnera para tener vida larga.", "Àdì e Ìyálẹ́ta. El Amanecer adivinó para Àdì cuando iba a ser esposo de Ìyálẹ́ta, y le dijo que siempre temblaría ante la mirada de su esposa. Le pidieron tres gallos y dinero, y se negó. Àdì es el aceite de palma cuajado de la madrugada, e Ìyálẹ́ta es la hora que va de media mañana al mediodía, cuando el calor lo derrite: uno pasivo y otro dominante."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la vida larga del heredero: una carnera.", "Para la pareja: tres gallos y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "La línea del padre y su corona."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aceite de palma, carnera, gallos."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 200.1 (yorùbá): Ariba abidiyoo, / a dífá f'Ori-Awo / tiiṣe omọ wọn lode Omuko-ẹgi. / Wọ̀n ni: / A fi ori ẹ de Ade baba rè / nitorinaa kiofi Agùtàn ṣ'ebọ emigigun.", "Verso 200.2 (yorùbá): Ijimjikutu / li o dífá f’Adi[338], / Adi nlọ ṣe pkọ lyáleta 339. / Wọ̀n ni: / Igba tioba rii aya rẹ̀ yoo maa ja. / Akukọ adiyẹ mẹta / ati-egbetaelọ̀gbọ̀n owò li ẹbọ. / Ko ma rúbo o.", "REZO: OTURA DI ADIFAFUN ELEGBARA ABEYALINI INLE OMODE OZAIN ABEYEBE AWO IYA NI OSHUN MOWANI ELEGBARA UNBOWASIVE AWO IFA MOYARE OZAIN AYAPA LEBO.", "REZO: ONIBO NIPONA ANIRI NIROMA ICHE OCHERI ADIFAFUN CUBERI TINCHOMA OLORDUMARE TUSA DE MAIZ AKUKO EKU LEBO.", "REZO: IFA OTUNDI HALLODEDUN NAINI OCRUN ADAFUN OEBE UMBATI LE LULLECHA ONI CORUBO AIKORDIE YARAKO MEMBE ORUBO ONI APE RE NIA LOCOCHE ARBAN OLUN ALA. KAFEREFUN OBATALA Y SHANGO.", "REZO: OTURA DI ADIFAFUN ELEGBARA ABEYALINI INLE OMODE OZAIN ABEYEBE AWO IY NI OSHUN MOWANI ELEGBARA UNBOWASIYE AWO IFA MOYARE OZAIN AYAPA LEBO. BAWO OMO OZAIN ESHU TIPELU EYENI MERIN EMITINO NI LOWONI ILE DIDE ILAYA NINAKU BAB NI ASHE LODAFUN OZAIN.", "REZO: NO WA BAWO OMO OZAIN ASHU TI PELU EYENI MERIN EMITIMO NI LOWONI ILE DIDE ILAYA NINAKU BABA MI ISHE EBBO KUELU A ORUKO NI SHANGO MOFE AKUKO MEYI ABEBO MEYI SI ORUNMILA ALA FIE ORI EWE NI OGUEDE OKAN EYANLA SI NA IBEYI MAYESI SI ORI EYA BABA ATI KERAN.", "SUYERES: “EMISO OBALUBE ALADOSO MONIJERE MEYE”."]}]$q$::jsonb),
(201,'1dd39b8004b2e4b5be39f3222ec0eed2',$q$[{"titulo": "Idea central", "texto": "Òtúrá Ìrosùn dice que la honestidad es el único camino a la paz espiritual y a la armonía. Las sociedades de negocios del consultante están a menudo en peligro. Pide devolver lo que no es propio, ofrendar para vivir hasta viejo y para que una enfermedad del vientre no lo alcance, y cuidar los embarazos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Una sociedad está en riesgo por bienes en disputa.", "Está pensando usar algo que no es suyo y conviene devolverlo antes de que crezca el problema (relato de Onikoyi).", "La pareja busca tranquilidad después de un pleito (relato de Olú-Iwo y su esposa)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Paz mental para él y su pareja.", "Llegar a viejo, como los grandes árboles.", "Que el embarazo llegue a término.", "Disfrutar el fruto del propio trabajo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Quedarse con lo ajeno y provocar una guerra.", "Una enfermedad del vientre.", "Que otro goce el fruto del propio trabajo.", "Quedar confinado en un lugar, con bastón en la mano.", "Que todo lo que se emprende quede trabado.", "Perderse en un viaje y no volver."]}, {"titulo": "Enseñanza principal", "texto": "Lo ajeno se devuelve. Los árboles grandes que ofrendaron llegan a viejos; los pequeños que no lo hicieron se pudren por dentro."}, {"titulo": "Relatos reunidos", "puntos": ["Oníkòyí y la propiedad ajena. Oníkòyí iba a quedarse con la propiedad de otro y usarla como suya. Le advirtieron que esa conducta se volvería guerra y alboroto, y le pidieron diez caracoles y dinero, además de devolver todo lo que no le pertenecía.", "Olú Iwó y el descanso. Òtúrá descansó, Ìrosùn descansó: así adivinaron para Olú Iwó, y le dijeron que él y su esposa tendrían descanso y paz. Le pidieron una paloma y dinero. Escuchó y ofreció.", "Los árboles del monte. Òtúrá rojo brillante, Ìrosùn rojo brillante: así adivinaron para todas las clases de árboles del campo, y a cada uno le pidieron seis gallos, seis agujas y dinero. El àràbà, el ìrókò, el apá y todos los árboles muy grandes del bosque ofrecieron; los árboles pequeños y delgados del campo y del monte no lo hicieron. Por eso los grandes llegan a viejos, y los pequeños mueren antes: si pasan de dos años, algo se les mete dentro, les abre un hueco y se mueren. Ifá pide ofrendar contra una enfermedad del vientre para llegar a viejo; ante dolores de estómago persistentes conviene ir al médico.", "El tinte y la lejía. Òtúrá rojo brillante, Ìrosùn rojo brillante adivinó para el tinte índigo y para la lejía que se le prepara. A la lejía le dijeron que quedaría embarazada, pero que ofrendara para que el embarazo no se le escurriera; no lo hizo, algo la pinchó en la cintura, empezó a gotear y goteó hasta perderlo todo. Desde entonces repite: si hubiera sabido, habría ofrecido. Al tinte le pidieron ofrendar para que otro no gozara el fruto de su trabajo y para no verse atado a un solo lugar con un bastón en la mano; tampoco ofreció. Por eso la tela que tiñe la viste otro, la gente dice: miren el trabajo del tinte, el tinte es el marido de la tela; lo revuelven con un palo y le dejan el palo apoyado en el cuello. Una mujer embarazada que recibe este Odù debe ofrendar y llevar control médico.", "Los que quedaron trabados. Muy despacio adivinó para los que estaban en un callejón sin salida, y les pidió ofrendar para que todo lo que emprendieran no se trabara. No ofrecieron: buscaron dinero y se trabó, buscaron hijos y se trabó, buscaron esposa y se trabó.", "Yewa en el bosque de rafia. El barro no hace flotar un bote: así adivinaron para Yewa cuando iba al bosque de rafia, y le pidieron ofrendar para no perderse y poder volver a casa. Oyó, pero no ofreció. Llegó al bosque, desapareció y nunca volvió. Sus compañeras, las esposas menores y sus hijos salieron a buscarla cantando: buscamos a Yewa y no la encontramos, por eso no dormimos ni descansamos. Ese es el canto que se canta hasta hoy en tierra yorùbá cuando alguien muere, en la parte del funeral llamada buscar al difunto. Quien va a viajar debe ofrecer cuatro palomas y dinero antes de salir para poder regresar."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para devolver lo ajeno: diez caracoles y dinero.", "Para la paz: una paloma y dinero.", "Para la vejez y el vientre: seis gallos, seis agujas y dinero.", "Para el embarazo y el fruto del trabajo: la ofrenda que marque Ifá.", "Antes de viajar: cuatro palomas y dinero, sin rebajar."]}, {"titulo": "Relaciones espirituales", "texto": "Yewa, madre que se perdió en el bosque de rafia. Los grandes árboles: àràbà, ìrókò y apá."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Àràbà (ceiba), ìrókò, apá, índigo, lejía de ceniza, rafia, agujas, gallos, caracoles."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 201.1 (yorùbá): Gbasidigbara: / a difá f'Onikoyi. / A ni Onikoyi gba / ohun-olohun toju / Onikoyi ni oun a f'ohun-olohun / naaṣe ti ara oun. / Wọ̀n ni: / \"Iwà yi a d'ogun, / a di ariwo\" / Nitorinaa ki ó rú: / İgbin mẹ̀wà / ati egberindilógún owó. / Kia fi ohun f'olohun.", "Verso 201.2 (yorùbá): Òtúrá simi, / Irosù simi: / a difá f'Olú-Iwo / Wọ̀n ni: / Olú-lwo a simi. / Aya rẹ̀ a simi. / Eyelé / ati ẹgbaa méjilélógún owó / li ebọ. / Ó gbó ó rú.", "REZO: OTURA ROSO MUN ADAWA DIROSUN IYERAWO ODEYASI MALALUSHERO BIWO ESE BURIKU OLORUN OYU RI WON.", "REZO: MARIWO OPEBELE TULLABA ADIFAFUN ONITI PICIETU OLLU ICHERI ACUO AUCO LEBO TETEREGUN OFICHE BIOMA OSU ADIFAFUN ANANI REGUN EYELE MEYI ETU MEYI ORI EYELE ADIE LEBO.", "REZO: OTURA BAIROSUN ILU UMBO ERU AKUKO IGUI EFUN KOKO OSUN BURU ONILU OTOKU, INSODE AWO, KEFEREFUN OSUN, LODAFUN ORUNMILA.", "REZO: OTURA ROSO, OTURA OBANI ORUN ORIGUA OLOFIN, OLIVA ONIRE ORUN AWO OLIVA ONIROSO AWA LEWA INLE IROSO GUEDE IFA OLOFIN YO ORUN WALERI OMO OLIVA YERU ODERA YOKO YOKUNI OSUN INLE OLIVA ODDUN.", "REZO: ADIFAFUN AWO ORORUN, BI ONI TIROLA, KIRIBE NI INU, AWO ABURE IROSUN TUNIALARA, ADIFAFUN ORUN BI ONI LOYU, MODE IFA OTURAMUN SHANGO OYU ONA OBANIMUN, OTURA SUN OYA LENU, INLE DIDE OBI TIWAYU BI IFA KOBASHE BABA BIBAÑU UNYOUN, BI ASHE AWO BI AGBA, LODAFUN ORUNMILA KAFEREFUN IYANZAN.", "REZO: OTURA ROSO BIROSO AMANA EGGUN EBONIRA IFA AWO LLORUN GUERE NI LAYE INA INLE ABEYEKUN INA AGUALESE NARI YEKUN INLE MOFE NARI MA OBE AGUALOBELE TIFA MORUBO AYEURI FUN AWO IBA LOUN AGUETE NI AMI INLE AGUETE NI OMI NARI INA MAFUN OFO.", "REZO: MALU META TIKONI IKU OLORUN OBA LELE OLOFIN ESHIN SHIN FUN FUN AKALA AYO OYU OTEMI MOKARURU OBINI AGBERE PASHARA OMODUDUA IKAN AMON DI OBA OTURA ROSO MUN NILE IDEBUSHERO AKEOKU OSIBALOGUN LORA OBINI ENA ILA ODUDUWA OPE NI APOTE ERI GORISHA BIOKU BIKU LAYE AKALA AKA OMOLERUN AGBA ORISHA IMOLE KAFEREFUN ODUDUWA.", "SUYERE: “BIOKU BAKULAYE AKALA OMOLORUN EGGUN META ORI ODUDUWA IDE KOSHERO OKE ABEYI EGGUN OBINI ABEYI EGGUN KUNI.”", "REZO: ADIFAFUN YEWA OKUE AGBANIFA OBA ILEKE MARIWO, OKUE BELE OTUN IYA OBA ADIFAFUN ENI KUOLETUN ERI EGGUN OTA NIBOSHE OYU ISHERI EGGUN INTORI IGUIBI OMA YEWA ADIFAFUN BARABANIREGUN, OTURA IROSO YEWA ALE EYA OLU OLOBOSHE OSUN AYE ODDUN KALA, OKULA AGBA DUDU, OMI LEGGUN OSUN ODOGUN, SONI ABEREGGUN YEWA OMITOGUN LODAFUN ORUNMILA."]}]$q$::jsonb),
(202,'d00dfd9ff6bedcffc1c03ea881b4d4f0',$q$[{"titulo": "Idea central", "texto": "Òtúrá Ọ̀wọ́nrín habla de la muerte como parte necesaria del orden del mundo y de que el ser humano tome conciencia de lo físico y de lo espiritual. El consultante no está siendo lo bastante atento ni cariñoso con sus hijos. Pide ofrenda para vida larga y para ver la buena fortuna."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está pasando por un duelo (reflexión sobre el viaje entre la tierra y el cielo).", "Le da miedo decidir y está aplazando un cambio.", "Ha tenido poco tiempo para sus hijos."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Vida larga sobre la tierra.", "Ver las bendiciones y la buena fortuna.", "Reencontrarse con los que se fueron."]}, {"titulo": "Ibi y advertencias", "puntos": ["Llorar a los muertos sin entender el orden del mundo.", "Descuidar a los hijos.", "Vivir solo para uno mismo y olvidar al pobre."]}, {"titulo": "Enseñanza principal", "texto": "El que nos manda a venir es el que nos llama de regreso. Si un hijo no conoce a su padre, el mundo no anda bien. Por nuestras voces nos reconocemos en la oscuridad."}, {"titulo": "Relatos reunidos", "puntos": ["El llanto por la muerte. El Omnisciente conoce a los que atentan contra otros; los del campo conocen a los de la ciudad; los viajeros de la tierra y del cielo nos volveremos a encontrar; las termitas no se dispersan sin volver a reunirse. Así adivinaron para los seres humanos cuando lloraban por la muerte. La gente de la tierra regresa al lugar de donde vino: ¿por qué tanto llanto, tanta aflicción, por qué subir y bajar, por qué ayunar? El que nos manda a venir es el que nos llama para volver a casa. Lo que a nosotros nos agrada en la tierra no siempre le agrada a Olódùmarè: la gente se asienta para hacer maldad y eso Él no lo acepta. Si un hijo no conoce a su padre, el mundo no anda bien, y es la muerte la que lleva al hijo a conocer el cielo. Si no existiera Èṣù, ¿quién se acordaría del pobre, si cada uno busca su comida y su bebida? Háblame y te hablo: por nuestras voces nos reconocemos en la oscuridad. Les pidieron cuatro palomas blancas, cuatro carneras y dinero, y ofrecieron para tener vida larga y ver la buena fortuna."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Cuatro palomas blancas, cuatro carneras y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Olódùmarè llama a los suyos de regreso. Èṣù recuerda al pobre."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Palomas blancas, carneras."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 202.1 (yorùbá): Karikaṣikataaa-Imorimo-nmowọn! / Ara oko nm'ara ilé / Erò ayé at'èrò orun ao tun'ra wa ri. / Etutu kiituka kio ma gbarajo: / A dífá f'awa èniyàn / tiimaa sokun okú. / Ibi omo aráyé ti wa ni wọn npada si. / Ewo niti ẹkun, èwo ni ti ibanujẹ?, / Ewo niti igbaraṣanlẹ, / èwo niti aijẹun? / Ẹniti o ran ni wa li o tun / npe'ni pada ki a bowale. / Eyiti nwu wa ninu ayé / ko wu Edumare. / Ọmo-aráyé maa joko'ayé / ki wọn maase ibi, / Edumare ko fẹ, / Edumare ko gba. / Njẹ, bi mo ba wipe lọ, Ẹ maa lọ: / Bi mo ba wipe bọ, Emaa bọọ. / Ọmọ ko lẹ gbaimo baba k'ayé gun. / Ikú liomu ọmọ wa mọ ọ̀run. / Tani nro ti Edùmarè, Bikositi Eṣú / tani jẹ ro ti akẹbojẹ? / Onikaluku nró ti ara wọn: / Wọ̀n nwa jüjẹ-mimu. / Eemo Ökünkùn. / Ọmọ ko mọ Baba! / Fọ si mi, kini fọ si Q, / ohun lafi nmọ ara eni / ninu Ökùnkùn! / Ọmọ kole gbaimo Baba k'ayé gun. / Ebọ: Eyẹlé funfun mẹrin, / Agùtàn mẹrin, eegbàárin owó. / Wọ̀n gbọ̀ wọ̀n rú: / nitoripe kiwọn le maa pẹ ninu ayé / ati pe kiwon le maa ri ire.", "REZO: OTURA JUANI AWOLE AWOSHOLOLO AWO OLELE AWO OLELE AWO ALAKENTU OÑI OMAYE ADIFAFUN OLOFIN YALORDE, ESHU, ESHU BI.", "REZO: OTUARA ALAKENTU IFA ORUMILA SHANGO ADIFAFUN YALORDE Y ESHU.", "REZO: OTURA NIBARATI OBATALA OSHANLA ORIABA ERIBE GUENI ELEWO OBORI AÑARI ETUDE OSI OLONI GUENESI OLONI FOMARISHE OBATALA FEKUN OTURA JUANI BI JUANI BI JUNI OLONA OBATALA NI ORI ASHO FUN FUN OBI ORI OU EFUN BAGUN INLE ARISHALALA IFA KAFEREFUN OBATALA IFA KAFEREFUN ORI OLOFIN.", "REZO: OTURA NI OJUANI ALAKENTU AWO ORI ASHEBI AYE ASHE NI ORI BAKERI OBATALA ARILAYEO AFEFE ORI LORUN ASAKALEKE ORINIFA ORI BAWA ORITUTU AWO OMIMO ORINI OJUANI ELESE BAWO ONIWASHE MOBA ONIWASHE MOBA OWO OSHAORINI LAYE IFA SIWAYU OTA BONI ORI OSHE IRE NI KOFIBORI KOFIBOFIDAN ADIFAFUN OU ELEGO KAFEREFUN ORUNMILA."]}]$q$::jsonb),
(203,'2686c0f0fa3b5280a31f94425d00c327',$q$[{"titulo": "Idea central", "texto": "Òtúrá Ọ̀bàrà habla de no romper los tabúes ni tocar lo que está protegido. Las opiniones del consultante serán cuestionadas. Advierte de un difunto que no ha recibido sepultura digna y que puede arrastrar a otros a la muerte; pide enterrarlo bien. Dos hermanos de una misma madre deben ofrendar juntos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le cuestionan sus opiniones.", "Corre un rumor o una acusación que hay que verificar.", "Debe aclarar qué tiene prohibido antes de actuar (relato de Ọlobẹde Ipetu, que rechaza la indicación)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que un hijo llegue a rey.", "Hermanos unidos con sus asuntos en orden.", "Que se detengan las muertes en cadena."]}, {"titulo": "Ibi y advertencias", "puntos": ["Tocar lo que lleva amuleto de protección (àálẹ̀).", "Hablar de más y prometer con la propia cabeza.", "Un muerto sin sepultura.", "Quedarse sin voz."]}, {"titulo": "Enseñanza principal", "texto": "La boca grande mata a su dueño. A los muertos se les entierra con dignidad. No se toca lo ajeno que está marcado."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlọ́bẹ̀dẹ́ Ìpètu y la calavera. A Ọlọ́bẹ̀dẹ́ Ìpètu le pidieron un chivo y el cuchillo con que iba al campo. Se negó y se fue a su finca. Al volver, quiso recoger unos huevos del gallinero y una calavera seca le habló: no me toques, ¿no me ves? Asustado, corrió a contárselo al rey y le dijo que mandara a alguien con él, y que si no encontraban lo que decía, lo mataran. El rey mandó a dos hombres; Ọlọ́bẹ̀dẹ́ hizo lo mismo que la primera vez, pero la calavera no habló, y lo ejecutaron allí mismo como él había prometido. Cuando los hombres iban a regresar, la calavera dijo: muchas gracias. Ellos fueron a contarlo, el rey mandó a otros con ellos, la calavera volvió a callar y también los ejecutaron. Así murió mucha gente, hasta que contaron el caso a Ọ̀rúnmìlà. Él les pidió una chiva, una gallina, dinero y medicina de Ifá con hojas de wọ̀rọ̀; ofrecieron, y les dijo que sacaran la calavera y la enterraran como a cualquier persona, en su ataúd y con sus ritos. También advirtió a todo el pueblo que nadie tocara nada que no le perteneciera si estaba marcado con àálẹ̀.", "La calavera de la madre del rey. Ifá dijo que una mujer de la que nadie creía que podía tener hijos daría a luz un varón que sería rey, pero que debía ofrendar para vivir y verlo. La Tierra, que así se llamaba la mujer, no ofreció; murió en su campo y allí la enterraron cuando su hijo aún era niño. El monte creció y nadie supo más dónde estaba la tumba. El hijo creció y lo hicieron rey. Un campesino abrió una finca en ese lugar y, haciendo montones para el ñame, le dio con la azada en la cabeza; la calavera gritó: ¡ah!, ¿me cortaste la cabeza con la azada? El campesino corrió a contárselo al rey y pidió que si la calavera no hablaba le cortaran la cabeza. Fueron los Ògbóni, la calavera calló y lo mataron; al darse la vuelta, la calavera dijo: ¡ah!, ¿mataron a alguien? Los Ògbóni lo contaron y fueron los Ògúngbẹ́ con ellos; la calavera calló, mataron a los Ògbóni, y otra vez habló. Entonces el rey llamó a los sacerdotes Ọ̀tú. Antes de salir consultaron, y les pidieron una oveja, tela blanca, tamarindo negro, vino de palma y buñuelos de frijol. Al llegar, cortaron la cabeza de la oveja y derramaron la sangre sobre la calavera, le echaron vino de palma y le desmenuzaron los buñuelos. Cuando terminó de comer, dijo que era la Tierra y pidió que la llevaran a casa. La envolvieron en la tela blanca y la llevaron: así supieron que era la madre del rey. Ifá pide enterrar bien al muerto que no tiene sepultura para que no arrastre a muchos tras él. Desde entonces, cada día de Ferekete, los sacerdotes Ọ̀tú, los que apaciguan, cantan: madre de la Tierra, vete a casa, busca tu destino.", "Los dos hermanos. Òtúrá así, Ọ̀bàrà así: así adivinaron para dos hijos de una misma madre, y les pidieron cuatro palomas y dinero para que sus asuntos llegaran a buen fin. Unos ofrecieron y otros no. De los que ofrecieron se dice: ¿no ven qué en orden están sus cosas? De los que no, se dice que no valen nada.", "Ọ̀sanyìn y su vocecita. No se tiene la verdad en el vientre y la maldad en el estómago por nada: así adivinaron para Ọ̀sanyìn, dios de la medicina, y le pidieron tres gallos y dinero para que nada le quitara la voz. Ofreció solo un gallo. Desde entonces su voz no llega lejos y habla con una voz finita. Este Odù pide ofrecer completo para no perder la voz."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra la desgracia: un chivo y el cuchillo de trabajo.", "Para detener las muertes: una chiva, una gallina, dinero y medicina de Ifá con hojas de wọ̀rọ̀; enterrar al muerto con sus ritos.", "Para apaciguar al difunto: una oveja, tela blanca, tamarindo negro, vino de palma y buñuelos de frijol (àkàrà).", "Para los hermanos: cuatro palomas y dinero.", "Para la voz: tres gallos y dinero, completos."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà detiene la catástrofe. Ọ̀sanyìn, dios de la medicina. Los Ògbóni, los Ògúngbẹ́, los Ẹ̀mẹ̀wà y los sacerdotes Ọ̀tú. Los difuntos piden sepultura. Tabú: tocar lo marcado con àálẹ̀."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Wọ̀rọ̀, tamarindo negro (Dialium guineense), vino de palma, buñuelos de frijol, tela blanca, oveja."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 203.1 (yorùbá): Paarakoda: / a dífá fún Ọlobẹde Ipetu, / wọ̀n nikiorú Obúko kan / ati obẹ tiowa li qwọ rè / kiotoolos'oko. / O kọ ko rú kiotoolos'oko.", "REZO: OTURA RARA OTURA MUNI IYA WOLONI IFA LEWA LEWA SHILEKUN ARIKU BABAWA.", "REZO: IFA OSU MOBORAMORUBO BABA MIBA OLLA OTUCA OMIBOGUE NIN COMI ADIFAFUN OTUCA TINCHOMO OLA LLELLE INCAN LO OMIGUA MEGUA ENO MIELO LAFERCHIN TANI ECUNI OCO AKUKO EYA OYURE EBEFA OWO. ALLI GA ATA AWO ARISCO ADAFUN OLOGUO UN BATIN CHOMA ACOBIRE ADIE MERI LEBO AKUKO EYELE LEBO.", "REZO: OTURA BARA BARA NI ESHU, ADIFAFUN OBATALA TINSHESE OSOKO OSHUN.", "REZO: OMONI SHANGO BABA KUELE MOSAYORE, OLUO POPO, SHANGO AYIYI KAN OBARA KOSO, AYIYI SERE OTURA BARA, SHANGO OBA BININ, OMO TINA, OLUO POPO, OLUO POPO OBA ILE YEREKUN, LELE YUTON ARON, OMOYERE OMOTIYE, ERU YUTON ARAN, SHANGO ABARAYIRE BARA LODE IFA, AYIYOKUN, OTURA BARA SHANGO OBA ILE OBAYIRE MOTOSHE AWE OZAIN, MAYIRE OGDELE ODUDUWA.", "REZO: OTURA MUNI MUNIBAYE LELE INTORI AYARA OSHA GUALALA ELEGBA SHINISILIPO BABA BABAGUA OTO NI OSHA ELEGBA ALARBONI BOQUE NILOYE YAYAONA NI SHANGO YAYAKUN IBU LOSA IBU BIGUA ILEKUN EYELE IFA KAFEREFUN ELEGBA SHANGO OBATALA YANZA IYALORDE IYAGUELONI IFA OLGUA LOGUA IKELUN ARIKU BABAGUA.", "REZO: IDISHE BINU BIRE EGGUN ORI ONI AWONISHE EWE EWE MORULO OLUKE IRESE ADIFAFUN OTURA BARA IRESE ORAKORO ODI AGBA ADIFAFUN AIYE ORUGBO ORUN KORO EURE OKAN ELEBO ASHO ARA LEBO IGBOWERE OBINI KAN OZAIN ONITI OTUNLE BOGBO ELEBI OMO OKOSHE AYE LERI OBALUN SHEKI ORI BIGBE BONSHORO OBA OBASI LOPE AGUTAN OKAN LEBO ASHO FUN FUN LEBO IWIN LEBO AWO OFODE IBE ENIFA IFANI AKUSIN EKUN EKANNA IFA IAYARA OLOSUN OKUN ENI ODARA KIOKUN AGBA MASHE OKUTA ENIFA.", "REZO: OTURA ONI OZAIN OBARA NI OMA OKINI FIFO NINU AWO KAWE NI KOSIKU ADIFAFUN OZAIN AWO KINI ORUBO KI OJUN KONIKI OMO OJUN MOLENU ADIE META LEBO. AKUKO META LEBO OTI KANA LEBO, EBETA OWO LOWO ENIBE TUTO. OZAIN KOTIDOKE MOTI OSI MOTIOJUN OZAIN KOTIDE OKE MOTI OTUN OTUN OJUN OFINITI OFINITU OBASHINEGGUN IFA ONIKI LAKEYIO ENIFA ORUBO KIOJUN KANKI OMA BAGBANI OJUN KI OMAÑA INU SHEPE, BOGBO NINSHEWO OJUN AFUFI OJUN OZAIN BAÑI ILE.", "REZO: OTURA NI BARA BOFUN BAGURA INA OBATALA LOLEYO UNLOLE OFOLEITOSHE INLE WAYE ADIFAFUN ORUNMILA EFUN LASHENI OBATALA ILE LAYE NI OSHA OBATALA KAFEREFUN OBATALA."]}]$q$::jsonb),
(204,'b18b2c3ec5eabf8f2cf0794fbb69a00d',$q$[{"titulo": "Idea central", "texto": "Òtúrá Ọ̀kànràn pide evitar peleas y disputas causadas por mala conducta o malos procedimientos. La boca suelta del consultante le ha costado pérdidas. Promete ganar en los pleitos y casarse con la persona deseada aunque otro la reclame."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Habla sin pensar y puede abrir un pleito.", "Hay un compromiso anterior que debe aclararse antes de un matrimonio o un trato (relato de Òtú y la hija de Ọlófin).", "Un litigio se puede evitar con hechos y diálogo (relato de Alafura)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ganar en un caso judicial.", "Que nadie le discuta su carácter ni su trabajo.", "Casarse con quien desea."]}, {"titulo": "Ibi y advertencias", "puntos": ["Hablar de más y perder por eso.", "Pleitos por un compromiso anterior."]}, {"titulo": "Enseñanza principal", "texto": "Los animales del monte no discuten con el leopardo, ni los pájaros con el halcón. Nadie mata al perro por ladrar ni al carnero por balar."}, {"titulo": "Relatos reunidos", "puntos": ["Alafura y el barrio tranquilo. Òtúrá Ọ̀kànràn, el barrio está tranquilo: así adivinaron para Alafura. Los animales del monte nunca discuten con el leopardo; los pájaros del monte nunca discuten con el halcón; la gente no discutirá conmigo por mi carácter ni por mi trabajo. Nadie mata a un perro por su ladrido ni a un carnero por su balido: que nadie entre en pleitos conmigo.", "Ọ̀tú y la hija de Ọlọ́fin. Ọ̀tú quería casarse con Ọ̀kànràn, hija de Ọlọ́fin. Todos decían que habría pleito con el hombre al que ella estaba prometida, porque ese hombre ya había invertido mucho en ella. Oriji, adivino de las bendiciones, aseguró en cambio que Ọ̀tú se casaría con Ọ̀kànràn si ofrecía ocho caracoles, una paloma, dinero y medicina de Ifá. Él escuchó y ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para los pleitos: marcar Òtúrá Ọ̀kànràn en iyẹ̀ ìròsùn, rezar el verso, mezclarlo con aceite de palma y lamerlo.", "Para el matrimonio: ocho caracoles, una paloma, dinero y medicina de Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Ọlọ́fin y su hija Ọ̀kànràn."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Iyẹ̀ ìròsùn, aceite de palma, caracoles."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 204.1 (yorùbá): ÒtúráKọ̀nràn ilú tutu mẹmẹ; / wọ̀n sa'gédé fún Alafura. / Non ni / Eranko igbó kiib'ẹkùn ro'jẹ, / Ẹyẹ oko kiiba aṣa ro'jo. / Awọn omo aráyé / ko maa bami ro'jo iwà mi. / Wọ̀n ko maa bami ro'jo iṣé mi. / Wọn kiitorii gbigbo pa ajá, / wọ̀n kiitorii kikan pa'gbo. / Awọn omọ aráyé komaa bami ro'jo / ati bẹẹbẹẹ.", "Verso 204.2 (yorùbá): Oriji awo Ire: / a difá fún Otú, / Òtú maamu Ọ̀kànràn ṣe aya, / Ọ̀kànràn qmọ Ọlọ̀fin. / Awọn omo aráyé nwipe a di ejó / nitori eniti a fi Ọ̀kànràn fún / ti na'wo pupo leelori. / oriji awo Ire l: / \"Òtú a ra Ọ̀kànràn ki Otú sa ṣẹbọ\". / Ẹbọ: İgbin méjo, eyelé, / egbèjo owó ati ewé Ifá. / Ó gbọ̀ ó rú.", "REZO: OTURA TIKU IKU AWO MONANA ABOLULOYE BIRA BORU IKU AWELE.", "REZO: OTUA ALACHO FIDEE OCANA GUANACA OWO ONI OTRUA CANA ARARA CAGUO BIRI ABEBOARDIE LEBO ROPA DE PINTAS DE ETU $8.40 MELO CHANCE MOFE ETU TUNCHOGUO OLUBO MOLOCHECHE ODO ACATAN CHAGUO BIRI MUCOCO MUODO MOLAN LODA FECHI TINCHAGUO UMBO TIOBALLE EWE EKU MELLO EYA MELLO EKU EURE LEBO.", "REZO: IFA OTUA TICUN INCHE OLOGUO EURE OU OROBE ORI OTURA TICUN ORULE CU URE ROBO ILE ONI OTURA TICO MOLO ILE OLUGUO ORE LECU OPERI OLLULLE ONI TANI ONI AMINI OLUO QUI LOGUA ONI IFA MORILO NIGUI LORI OTURA TIKU ONA TOGUA MABA EQUIVO ADIE LEBO AKOFA ME ASHO ORI ONI OWO LA MELLE TONTU ELLE. KAFEREFUN YANZA, MAFEREFUN OTURA TICUN.", "REZO: IYA IYANLA LODE ENI AWO ORUN LAYE LEYERUN EBBO KASHIORO EBBO KASHERU EBBO IYA INYANLA ENI BABALAWO KASHIORO OLODUMARE EBBO LAGUENI EBBO IFA KASHIORO.", "SUYERE: “IKU NILOKUN BALONI LOKUN ILOJUN IFA.”", "SUYERE DEL OPARALDO: “IKU LAYERE, IKU IFA IKU LAYE, IFA OTURA TIKU LAYE IKU IKU NILOKUN BALONI LOKUN ILOJUN IFA.”", "REZO: BABA OTURA TIKU LASHE FIFI KAWO OMATURA KOMA BARA ADIFAFUN IFE OYU INLE ILUFA BIRI BIRI ADIE LEBO CARETA ABITI 3 AKUKO 3 AKOFA.", "REZO: OTURA TIKU LERI IKU AWO MOÑAÑA ABELULOYE BIRA BORU IKU AWELE.", "SUYERE: MAÑAÑA IWA INLE BELELE MAÑAÑA IWA INLE BELELE INTORI ONA OBA IKU LAROYE.", "SUYERE DEL OPARALDO: IKU LALEE KUYEYE IKU ADIE PARADO OMARA YEYE EGGUN MALOLO BAYELE EGGUN IKU LALEE"]}]$q$::jsonb),
(205,'fda2983a0153ae43ffd48726aaa3776c',$q$[{"titulo": "Idea central", "texto": "Òtúrá Ògúndá pide quitar las energías negativas del consultante con una limpieza. Le han hecho mucho mal, lo maldicen y lo insultan, pero no han podido dañarlo. Promete arreglar sus caminos para una vida próspera."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente agobiado por insultos o enemistades.", "Algo que hizo antes le quitó apoyo de la gente.", "Busca renovarse espiritualmente y cambiar conductas concretas."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Limpieza de lo negativo.", "Que maldiciones, insultos y hechizos no le afecten.", "Caminos arreglados y vida próspera."]}, {"titulo": "Ibi y advertencias", "puntos": ["Maldiciones, insultos y malos deseos.", "Hechizos de atracción y encantamientos."]}, {"titulo": "Enseñanza principal", "texto": "No hay que temer a quien maldice: sus brazos no alcanzan a rodear a quien tiene la cabeza lavada por Ifá."}, {"titulo": "Relatos reunidos", "puntos": ["La cabeza lavada. Me hicieron mucho mal, pero no me dañaron; sus brazos no pueden rodearme. Me maldicen, me insultan y me desean el mal, pero Òtúrá Ògúndá dice que no les tema. Prometió arreglar mis caminos para que tenga una buena vida y una vida próspera. Òtúrá Ògúndá es quien me lava la cabeza para que no me afecten los insultos, ni las maldiciones, ni los encantamientos, ni los hechizos de atracción."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Medicina de limpieza: quemar muchas hojas de ojúùsájú, algunas de ifen y de ẹ̀ṣọ hasta hacerlas polvo, mezclarlo con jabón negro en una calabaza nueva, espolvorear iyẹ̀ ìròsùn, marcar el Odù, rezar el verso y usarlo para bañarse."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá lava la cabeza del consultante. Ògún en el nombre del Odù."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ojúùsájú (Petiveria alliacea), ifen, ẹ̀ṣọ (Elytraria marginata), jabón negro, iyẹ̀ ìròsùn, calabaza nueva."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 205.1 (yorùbá): Wọn-ṣemiṣemi-emi-ko-bajẹ, / Apa-won-ko-katemi, / wọ̀n ns'epe, / wọn ng'égun (ng gégun), / wọ̀n nfẹ bi si mi. / Òtúrá-Egúntán I ki'mi ma bèrú, / I ki'mi maṣ'ojo, / 1 òun a bami tún temi ṣe, / I ayé temi a dára. / Òtúrá-Egúntán liowẹ ori temi fún mi. / Ki gégun ma mu mi, / ki epe ma mu mi, / ki ẽdí ma mu mi, / ki ẹfún ma mu mi.", "REZO: OTURA AIRA IRE AYE TIMBELAYE IRE ILE OZAIN OTURA AIRA OGUNDA IRE OGGUN ALAWEDE INLE MOPUN OGUNYE OGUNYE OGUNYE MOWA IYE OGGUN ONIRE ORUNMILA OBARABANIREGUN IRE META EBBO ASHOGUN OTA LESE OGGUN.", "REZO: BAGUMBE MABA GUALOCO. ADIFAFUN BA AGO BOBO KOMACHE SU MUA ADIFAFUN AGUTAN LEBO.", "REZO: IFA OTURA IRA BOBA CHIRI LORDO FOLO GUN COLOCO RUBO ABO EYELE ADIE LOFO RUBO OLOKUN OFOLLU OSO PA OLOKUN OLOMO OBINI DELLEMI LOLLE.", "REZO: BABA ARALORDA OLLARDE OLO SISGO OPARDE BABA CHIRUMBO ADIE EYELE MI LOBO UNLO SIGUALLU QUISI OLO NIBEBEFE MOFE GUA CALO UNDE TIOLOCUN ARDELLEMI OLAME.", "OTURA IRE AYEKU ALAFI LA PIDE INSHE OZAIN.", "REZO: OTURA IRA ADIFAFUN ODOONISANISHE IGUATO ENI IMOLE, ORUN EDEMOTE AWONA KAFEREFUN ELEGBA,LODAFUN ORUNMILA ORUNLO.", "REZO: OTURA NIRA, OTURA AGORDE MASUEYE EGGUN OMONIYARE ONI BABA NIREGGUN ORONITA.", "REZO: BABA CHIRI AWO LODA LOLORUN OLOKO ONIBO EBBO EYE AKUKO, ADIE LOGBO ORUBO OSILA MERIN OLORUN OLEYO OLORUN OLOMO OBIN ADIFAFUN ADEYEMI LOYE OGGUN BABA ARAKO OPADIE BABA CHIRILIUABO UNTASI WAYO OBERIN OLEMI BABARE AWO WAKA LOONDE INLE TIO LORUN ADIFAFUN ADEYEMI AWO ALAMI ADAN A OKUN LODAFUN OZAIN.", "SUYERE: “ OGGUN AKUKO OLOKOKO KONIBO WEWOELE.”"]}]$q$::jsonb),
(206,'1689be638a1deef1105796e41a5858fe',$q$[{"titulo": "Idea central", "texto": "Òtúrá Ọ̀sá habla del castigo de quien se niega a ofrendar y de la recompensa de quien cumple. El mal genio, la irritabilidad y la arrogancia del consultante le traen problemas. Promete serenidad y cuerpo fresco, y protege del que compra y se va sin pagar."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está irritable y eso provoca discusiones (relato de Olókun y la frescura del cuerpo).", "Alguien le compra a crédito y no le paga (relato del pato comerciante Pepeye).", "Necesita responder con calma a un problema."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Calma, valor y cuerpo fresco.", "Que no le roben el dinero en el comercio."]}, {"titulo": "Ibi y advertencias", "puntos": ["Mal genio y arrogancia.", "Clientes que compran y huyen sin pagar.", "Reírse del consejo."]}, {"titulo": "Enseñanza principal", "texto": "Mi pecho no resopla ni palpita: el que ofrenda está tranquilo. El que se ríe del consejo se queda riendo solo, como el pato."}, {"titulo": "Relatos reunidos", "puntos": ["Olókun y el cuerpo fresco. Mi pecho no resopla, mi pecho no palpita, mi cuerpo está muy fresco: así adivinaron para Olókun, para que su cuerpo estuviera siempre fresco. Le pidieron una calabaza de aceite de palma, una de manteca de karité, una de aceite de almendra de palma, un caracol, una oveja, una paloma, un carnero, una piedra de rayo, dinero y medicina de Ifá. Escuchó y ofreció.", "El pato y los que no pagan. Compra y huye, compra y huye, el malo se escapa con mi dinero: así adivinaron para el pato, y le dijeron que gente mala vendría a comprarle mercancía y se iría sin pagar. Le pidieron dinero, una paloma y medicina de Ifá para no perder su dinero. Se negó y se rió del asunto: ¡ja, ja, ja! Esa es la costumbre del pato hasta hoy. Si hubiera ofrecido, le habrían preparado la medicina y no habría entrado al grupo de los que no ofrendaron."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la calma: aceite de palma, manteca de karité, aceite de almendra de palma, caracol, oveja, paloma, carnero, piedra de rayo, dinero y medicina de Ifá.", "Para el comercio: dinero, una paloma y medicina de Ifá con hojas de èèsin y de palma de aceite."]}, {"titulo": "Relaciones espirituales", "texto": "Olókun, dueña del mar."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Manteca de karité (òrí), aceite de almendra de palma (àdín), aceite de palma, èèsin (Urera mannii), palma de aceite (Elaeis guineensis), piedra de rayo."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 206.1 (yorùbá): Àyà mi ko fo, / Àyà mi ko ja, / Ara tuu mi nẹnẹ: / a daa fun Olokun, / wọ̀n niki Olókun wa rúbo, / ara a tuu. / Ebọ: Igbá-epo, igbá-adin, igbá-òrí, igbin, / àgutàn, eyẹlé, agbo, ẹdùn-ààrá, / ẹgbàá méjilélógún owó ati ewé lfa. / Ó gbọ̀ ó rú.", "Verso 206.2 (yorùbá): Arasá-Arasá / eniburúkú gbe'mi lowo lọ: / a daa fún Pepẹyẹ. / Wọ̀n ni: / \"àwọn ẹni burükú / mbowa baa ra qjà / ẹdùn-ààrá: piedra de rayo. / wọn maa salo laisànwó*; / wọ̀n niki o rubo / ki owó rè ma le ha s'ọna. / Ebọ: Ẹgbàá mẹsàn owó, eyẹlé ati ewé Ifá / Ó gbọ̀ ko rúbọ. / Wọ̀n ni: / Oràn di, Ha! Ha! Ha! / Bẹẹ ni Pepẹyẹ nṣe titi o fi di oni-oloni / ti a nri wọn yen. / Ibaṣepe wọn rúbo nijelo, / se a baṣe ewé Ifá fúnwọ̀n / nitorinaa ki a maṣe je Agbẹbomarú.", "REZO: OTURA SA IMPOYAMPO GUEGUERE NIFA IMPOYAMPO OYE ADDE OMO LAMPE SHANGO, LAMPE OLORUN, OTURA SA OWO EPO OKOYORI.", "REZO: IGUN OMOLARE ACHA OMOLARE AGUDI OMOLARE IGUN LLEGUN EBO HACHA LLOGUN OPE AGUODI LOMORI ELLE. DELE COCO. ADIFAFUN AGUODI CUCURUCU CURU TIBITIRI AGUODI LLELE CURU LLELE AGUODI LLELE EKU ONI EGUMA QUE ACUO AWO. OTUSA IFA ADURE AWO ARA ARAMU ADIFAFUN ORUNMILA CORUBO ABEBOADIE MEYI ADIFAFUN OLOYUBE AKUKO ILU LEBO LUBA ARUCO OCHIA TOMU ALLE LORDE OLOYUBE.", "REZO: NAMURU NAMURU, NAMURU, BI, RO, KOKO, WAKO, KOWA, BIWAKE, LEDEY, ADIFAFUN OBATALA.", "REZO: ADIFAFUN INDORO MILOKUN OMO BIERUN OBE KOTOKOTO LOFOKO INLO ONIKA EGBA INLE OSHUN KOTOKOTO ILU SAOLO OROLO NI EGGUN. IÑA BABA ADORO OTURA SA, ONEFA KOTOKOTO INLE OMO BIRIO ASORO LADO Y EGGUN, OFOLAYO, LODAFUN OBATALA, MAFEREFUN ORUNMILA Y OSHUN.", "REZO: ADIFAFUN ODEMATA OSHOMIKERE ODE TOMASELE OZAIN ELEYO OTOFA ODE BURUKU, ODE GARIYO MOKUE LONI ODE MATA AKAMBO ARONI OKAN NANI EIYE ODELA BOROKU OTA BORENO, OTA BOREYA, OTA BOROPO, OTA BOREMA, AMATA BOROWAO EYI SORO IYABE AYAMBEKO OTA MODE ODENIAWO OTURA SA OMO OTA ODE MATA AÑA OLOYU IWARA OTA BORI SUKU ALABOSAN OLUWO ATE LODAFUN OZAIN.", "REZO: OTURA SA IMPOYAMBO WERE ENIFA IMPUYAMPO ADIFAFUN OGUE LADE ADELE OBA EGUNGUN JORO JORO OFO ALAGBARA OKUNKUN IBOLE EGUNGUN BELEBELE IFA ONILU BOGBO EIYE OBA OGUE LADE OTURA SA AWO IMPUYAMPO NASI JUADA AWON OLODI AUN OSIÑAÑA OLUFA EGUNGUN OBA OLANLA SINOKURU EGGUN, LODAFUN ORUNMILA, KAFEREFUN EGUNGUN OBA.", "REZO: OTURA SA BERENI AWO OMO KISIEKO OBANILE AGANGANI AWO", "OMO IFA INLE YEREGUN OMBALA OSHA NI EGGUN ODONULOYE YENYEWAO OTURA SA IFA OMO ALARI OBANI YELEKUN EGGUN EMIFA OLOFIN OWORINA ORISHAOKO OWORUNA ORILOKE ODIORUN ORUN LOLAEBEWA NI IFA."]}]$q$::jsonb),
(207,'e57a7a1531f9de6ac6be440d5c19283e',$q$[{"titulo": "Idea central", "texto": "Òtúrá Ìká habla de dispersar y alejar a los enemigos para asegurar la prosperidad. El consultante necesita una limpieza espiritual. Anuncia que el año de prosperidad ya llega para quien estaba rodeado de adversidad."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente amenazado o envidiado y busca limpieza o protección.", "Teme que lo relacionen con un robo, sufrir uno o enfrentar falsos testimonios (relato de Adeyibo).", "Ha pasado pobreza o adversidades y espera un cambio en su economía (relato de Ilé-sanmi)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que se desvanezcan brujos, hechiceros y enemigos.", "El año de prosperidad que llega.", "Sentirse libre y contento como el elefante en la calle."]}, {"titulo": "Ibi y advertencias", "puntos": ["Ladrones y acusaciones falsas.", "Pobreza y adversidad."]}, {"titulo": "Enseñanza principal", "texto": "Òtúrá está contando dinero. Cuando el elefante va por la calle y el búfalo por la pradera, van libres: así va quien ha alejado a sus enemigos."}, {"titulo": "Relatos reunidos", "puntos": ["Contra la muerte y la enfermedad. Asaregege es el nombre de la muerte y Abiringbẹrẹ el de la enfermedad. Si el elefante va por la calle se siente libre; si el búfalo va por la pradera se siente contento. Òtúrá Ìká, ayúdame a desvanecer la acción de los brujos y de las brujas, de los hechiceros y de los enemigos.", "Adéyíbọ̀ y el ladrón. A Adéyíbọ̀ le pidieron cuatro caracoles, una paloma, dinero y medicina de Ifá para que no viera sobre él el mal de un ladrón ni que lo acusaran en falso. Oyó y se negó.", "Ilésanmí y el dinero que se cuenta. Ọ̀rúnmìlà dijo: Òtúrá Ìká. Le preguntaron qué estaba contando Òtúrá, y respondió: Òtúrá está contando dinero. Así adivinaron para Ilésanmí cuando estaba rodeado de pobreza, y le dijeron que su año de prosperidad estaba llegando. Le pidieron cuatro palomas y dinero. Escuchó y ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Medicina contra los enemigos: hojas de ẹ̀là (orquídea) e iyèrè machacadas, cocidas como sopa en una olla de barro con pescado aro; ya fría, se le añade iyẹ̀ ìròsùn rezado con el verso; antes de tomarla se pone la olla en el suelo y se derrama aceite de palma alrededor.", "Contra el ladrón: cuatro caracoles, una paloma, dinero y medicina de Ifá.", "Para la prosperidad: cuatro palomas y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà anuncia la riqueza."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ẹ̀là (orquídea, Calyptrochilum christyanum), iyèrè (Piper guineense), pescado aro, iyẹ̀ ìròsùn, aceite de palma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 207.1 (yorùbá): Asaregege li aipe Ikú, / Abiringbẹrẹ li oruko ti àip'àrùn. / Bi erin ba ja popo a maa túráká, / bi efọ̀n ba ja'bata a maa túrákátáráká. / Otúrákátúráká! / Ki o bami túmọ oṣó, / ki o bami túmọ Ajẹ̀, / ki o bami túmọ odi, / ki o bami túmọ ọ̀tá.", "Verso 207.2 (yorùbá): Òtúrá-Ká: / a difa fún Adeyibo. / Wọ̀n niki Adeyibo wa rubo / klama baa ri'bi ole nka'ni. / (bọ: Igbin mérin, eyẹlé, / egbaá méjo owó ati ewé Ifá. / Ở gbọ̀ ó rú.", "Verso 207.3 (yorùbá): Ọ̀rúnmìlà I: Òtúrá-Ká, / Emi I: Òtúrá-Ká, / Wọ̀n ni: Kinni Òtúrá nkaa? / Ọ̀rúnmìlà I: owó ni Òtúrá nká: / a dífá fún llé-sanmi / mbẹ laarin iponjú. / Wọ̀n nì: Qdún orọ de. / Wọ̀n niki o rúbọ: / eyẹlé mẹrin ati egberindilógún owó. / Ó gbọ̀ ó rú.", "REZO: OTURA KAN, ADIFAFUN OBANILE KOADE MOWE EÑI WERE BOGBO MABINUUNBO WA ORUNMILA LOFOBANI ESHU MAFUN OTURA KA ADIE LEBO.", "REZO: MACHERIADO MALUFO LUMALO AWO ADIFAFUN ONICA EBAN AGUADO EYELE KAFEREFUN OBATALA OLOFIN Y OSHUN.", "REZO: OTURA KA IFA MACHERI ARDO MALO FALU AWO ONICA AGUA AKUKO EYELE MENI BORO ONDECU ICHE LO AGUILLA ORDIDI AGUA OKUTI ABO. LODAFUN ORUNMILA OBA OGGUN LODAFUN ESHU. OTUAKA MOKA MORGUA.", "REZO: ADIFAFUN ALETI AKONI MAWANI INLE OFIKALE MI KOMA ADASILE DELO OKUYA IKO VEYE KADUN IBAKE IBASTA LERI BOGBO OTA MALEYO LODO YALENO ONIYURE ABAYIKOYIKI KOSHE KOMBOSHE MIYE ELALUBA ORI BOGBO KOROMAFUN ORI KA SHOSHO ASHU KORIRA EBANA KAFEREFUN ORUNMILA LODAFUN ESHU AFOTIFO."]}]$q$::jsonb),
(208,'a4bfd5942ffbd6a3e4124a2bee9e9f4e',$q$[{"titulo": "Idea central", "texto": "Òtúrá Òtúrúpọ̀n habla de hacer las ofrendas completas. El consultante puede estar cargando abusos, burlas y maltratos. A quien le sale este Odù en su iniciación debe abstenerse por completo del alcohol. Promete hijos despiertos y que hablan bien."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Carga burlas o malos tratos.", "Cumplió solo una parte de una promesa o de lo que le indicaron (relato de Ọbàtálá).", "Pregunta por pareja e hijos (relato de Olubolade)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Esposa e hijos.", "Hijos despiertos y con voz.", "Vestir de blanco con dignidad."]}, {"titulo": "Ibi y advertencias", "puntos": ["Ofrendar a medias.", "La bebida y la vergüenza que trae.", "Abusos y burlas."]}, {"titulo": "Enseñanza principal", "texto": "El aceite de palma vive en su vasija y la tela blanca aparte, en su envoltura: no se mezclan. Lo que se ofrece a medias protege a medias."}, {"titulo": "Relatos reunidos", "puntos": ["Ọbàtálá y el vino de palma. Ọbàtálá Ọṣẹ̀ẹ̀rẹ̀ Igbó venía del cielo para ser coronado en el mundo. Le pidieron tela blanca envuelta, un caracol y dinero, y le dijeron que nunca bebiera vino de palma. Ofreció solo la mitad. Le indicaron vestir de blanco, que es la ropa de los Òrìṣà, y lo hizo, pero no atendió la advertencia del vino. Se emborrachó y se manchó la ropa blanca con aceite de palma. Al final ofreció el caracol y, por vergüenza, prometió no volver a beber vino nunca.", "Olúbọ̀ládé y los hijos que no son mudos. A Olúbọ̀ládé le dijeron que tendría una esposa que le daría muchos hijos, y le pidieron una gallina y un gallo, dos palomas, dos gallinas de Guinea y dinero para que los niños no fueran mudos ni torpes. Obedeció y ofreció. Los pollitos de la gallina de Guinea no son torpes, y no hay día en que el gallo no cante."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la dignidad: tela blanca envuelta, un caracol y dinero, completos; no beber alcohol.", "Para los hijos: una gallina y un gallo, dos palomas, dos gallinas de Guinea y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ọbàtálá, que viste de blanco y no bebe vino de palma. Tabú: bebidas alcohólicas para quien recibe este Odù en su iniciación."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tela blanca, caracol, aceite de palma, gallinas de Guinea."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 208.1 (yorùbá): Epo kete, / Ala kete: / a difá fún Ọbàtálá Qṣeerẹ̀-Igbó / nti òde Irànjè lọ gunwa lode ayé. / Wọ̀n niki o rú: / Aṣo funfun, igbin ati egbàáwa owó. / Wọ̀n niki o mamamu ẹmu rara o. / Ó gbọ̀ o rúbọ / sùgbọ̀n ko rúbọ pe, / wọ̀n niki o fi aṣo funfun / bo'ra los'ode ayé. / O fi aṣo funfun / bơ'ra ṣùgbọ̀n kofi emu gbeewọ, / O mu emu yo tan, / epo fosii l'aṣo. / O wa rü igbin nikẹhin, / o si ko ẹmu silẹ nitori itiju.", "Verso 208.2 (yorùbá): Òtúrá-Tutu: / a difá fún Olubolade. / Wọ̀n nì: / Olubolade maa n'obirin kan, / obirin naa a bimo pupo fün un. / Wọ̀n ni kiowa rúbọ / ki àwọn omọ naa ma baa tutu ya odi. / Ebọ: Adiyẹ Méjì (takotabo), eyẹlé Méjì, / eyẹ etu Méjì ati ẹgbaá mẹrin owó. / ó gbó ó rú. / Wọ̀n ni: / Ọmo-awo (eyẹ-ẹtu) kii tutu ya odi, / Akuko adiyẹ kiigbaifo hun enu re / bi ojumẹ ba mọ.", "REZO: BABA TURUPE AWO ADO KATOBINA AWO ALAKETO AYA ADIFAFUN FALOFUN, ADIFAFUN A LOMA ABASO ALAWA BOMO ALEDODO AYAKOLO NILE IGBIN KALOLO KOMIKOLO ARO MABOMO LODO AYAKANLENILE.", "REZO: OWO EREBETA ODIFA ADIFAFUN UMBATI LOMBA GUTIN APORO GUTIN CHOBINI OBINI EYELE LEBO EKU ADIE LEBO.", "REZO: OTURA TRUPON AWO OBRECHE BETE ORDIFA ORUNLA UMBATI LOBA EPO ROGUITIN CHOBUNI REBITI EYELE ELERBO EKU ABEBOADIE LEBO.MAFEREFUN OLOKUN Y SHANGO.", "REZO: OTURA TRUPON IFA SHANGO MAFEREFUN OGGUN Y ESHU. IFA OLOCO AIDAFUN OBAÑU LEFICHE INU. IRE NI FA GUERI OBATALA, SHANGO, ORUNMILA, Y OLOFIN."]}]$q$::jsonb),
(209,'42371835884913c06062ad34cd51460d',$q$[{"titulo": "Idea central", "texto": "Òtúrá Ìrẹtẹ̀ habla de reafirmar la espiritualidad y de ofrendar para evitar guerras, complots y malentendidos. A la persona le cuesta la moderación. Pide levantarse temprano, meditar sobre sus actividades y vivir sin derroche, sin deudas y sin alcohol."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Gasta o actúa sin medida (relato de Ọ̀rúnmìlà y la moderación).", "Hay malentendidos en un grupo que pueden crecer (relato de Ewi, rey nuevo de Ado).", "Quiere reafirmar su práctica espiritual."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ánimo para salir adelante por sí mismo.", "Un gobierno o una gestión sin guerras ni conspiraciones.", "No caer en desgracia por saber medirse."]}, {"titulo": "Ibi y advertencias", "puntos": ["La falta de moderación.", "Deudas, derroche y bebida.", "Romper un juramento a los amigos.", "Complots y rebeliones."]}, {"titulo": "Enseñanza principal", "texto": "Quien conoce la moderación nunca cae en desgracia. La conoce el que trabaja, el que no derrocha, el que no roba, el que no debe, el que no bebe y el que nunca rompe un juramento a sus amigos. Entre espinas y cardos, la palma joven crece."}, {"titulo": "Relatos reunidos", "puntos": ["¿Quién conoce la moderación? Òtúrá Ìrẹtẹ̀, anímate de nuevo, vuelve a avanzar por ti mismo. Quien conoce la moderación nunca cae en desgracia. Pregunté quién la conoce, y Ọ̀rúnmìlà respondió: el que trabaja. Pregunté otra vez: el que no derrocha su dinero. Otra vez: el que no roba. Otra vez: el que no tiene deudas. Otra vez: el que no bebe alcohol ni vino de palma, y el que nunca rompe un juramento hecho a sus amigos. Òtúrá Ìrẹtẹ̀ es el que se levanta muy temprano y medita sobre lo que va a hacer. Entre espinas y cardos crece la palma joven y frondosa; Jowóro nunca gasta todo su dinero, Jókójẹ́ nunca será deudor, y si Èèsan tiene mucho dinero, paga sus deudas.", "El Ẹ̀wí de Àdó. Cuando el Ẹ̀wí de Àdó acababa de ser coronado rey, le dijeron que si ofrecía dos gallinas de Guinea y dos o cuatro palomas blancas no habría guerras ni malentendidos durante su reinado. Escuchó y ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Medicina de la moderación: hojas de jowóro, ẹ̀ṣọ y jókójẹ́ molidas con jabón negro, con nueve caracoles colocados uno a uno encima y el Odù marcado en iyẹ̀ ìròsùn, en una calabaza con tapa; para bañarse.", "Para un reinado en paz: dos gallinas de Guinea y dos o cuatro palomas blancas."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà enseña la moderación. El Ẹ̀wí de Àdó."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Jowóro, ẹ̀ṣọ (Elytraria marginata), jókójẹ́ (Cissampelos owariensis), èèsan (palma de aceite), jabón negro, iyẹ̀ ìròsùn."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 209.1 (yorùbá): Òtúrá-Rẹtẹ̀, Tún' rárẹtẹ. / Biabi'ni a tún'rá eni bi, / Òtúrá-Retẹ̀, Amuwọn, Amuwon, / Enimo'Wọ̀n kiitẹ. / Emi I: tani mợ wọn? / Ọ̀rúnmìlà I: ẹniti nṣiṣé. / Emi I: tani mợ wọn? / Ọ̀rúnmìlà I: / eniti kiina'wo owọ̀ rẹ tan. / Emi I: tanimo'wọn? / Ọ̀rúnmìlà I: eniti kojẹ jale. / Emi I: tanimo'wọn? / Ọ̀rúnmìlà I: / eniti kiije'gbeese. / Emi I: tanimg'wọn? / Ọ̀rúnmìlà I: / eniti kiimu oti, / eniti kiimu ẹmu, / ẹniti ko jẹ dalẹ orẹ. / Òtúrá-Rẹtẹ, / Ojikutukutu ba'nu ara rẹ / ṣiro nitoriiṣiṣe! / Ninu ẹgun ninu isọ, / Mariwo-ọ̀pè a yo'risoke, / Jowóro kiina'wo tan, / Jokó-jé kiida'gbese, / Eẹsan kiida'gbese kiomasan, / Amuwọn li Amẹso!", "Verso 209.2 (yorùbá): Òtúrá-Rẹtè: / a dífá fún Ewi l'Ado, / Ọba to jẹ ni titun / wọ̀n ni: / \"bi Ewi ba rúbo, / Ogún ko maa de, / Ọ̀tẹ̀ ko maa tẹ̀ èniyàn ni igba tirẹ\". / Ebọ: Ẹyẹ ẹtu Méjì, / eyẹlé funfun Méjì tabi mẹrin. / Ó gbọ̀ ó rú.", "REZO: OTURA TIYU TIYA LAPE LOBOMINI YEWU KUYORIO ESHU LAROYE ADIFAFUN ESHU LARIO KAFEREFUN ORUNMILA.", "REZO: OYUTAMI TAMI ODEFA BI AIKORDIE LEBO KAFEREFUN OLOFIN U ORISHA.", "REZO: ADIFAFUN OGBINBIN AIYE KEIYEMO BOYATO OSA ONJE EJA TUTO LODAFUN OLOGBARO KAFEREFUN ORUNMILA.", "REZO: AKATI LOMADO KAKI TIELURU ADIFA AKUE TIESHE ILE OLESHA.", "REZO: OTURA TIYU LO DOMINI ELEGBA KOYUREO ESHUN LOKOYO ADIFAFUN ESHUN LARIO, KAFEREFUN ORUNMILA.", "REZO: ADIFAFUN OTURA TIYU LESE UN SOLO ODUN YINLE OJUN ONU IFA UN SOLO ISOKO BOGBO KOLENO AWO NI ORUNMILA UMBO WA ARANI SHONSHON AWO NI OTURA TIYU IYA SI MOMO UNTEFA IGBODUN IFA KAURE MOKU EMO YAWE YANSA EYANYA ARANIQUE BOGBO ORUMALE IGUI GUAMALE NI ODDUN NI LATIYESHERE SHANGO NI OTUA TIYU AWO, OGGUN MAGOBUN ORISHA OGGUN DA OTOKU. KERE LERI AWO, LODAFUN OGGUN, KAFEREFUN ORUNMILA.", "REZO: ADIFAFUN OGUEDAY OMO OBATALA OBI INTORI OBI IKU ORUN INLE OMODE ABUKENKE IÑA FUNLOYE OZAIN WALONA OTA FUN FUN ADE IGONODE LODAFUN OZAIN KAFEREFUN SHANGO.", "REZO: OYUYAMI TAMI ODEFABI AKODIE LEBO KAFEREFU OLOFIN ATI ORISHA IYAMODE SHERE SHERE MEYI OWOWO OPOLOPO OWO OLOFIN AGBORAN LAPE LAPE KUYONIC ADIFAFUN IYAMODE ODEPA LODAFUN EGGUN. REZO: ENI KUN KUN LAKOYO OMOLOKUN AYARAKOTO INLE ORUN EWBADO NI FAN LOKITI IRAWO AYIWO LODAFUN BORONUN KAFEREFUN YEMAYA Y ORUNLA."]}]$q$::jsonb),
(210,'74ffd925697b318c5ce504fd205b968a',$q$[{"titulo": "Idea central", "texto": "Òtúrá Ọ̀ṣẹ́ habla de un peligro cercano en la casa o en los negocios. Los cambios emocionales deben manejarse con cuidado. Promete victoria en la guerra y que el jabón se lleve lejos los problemas de quien ofrenda."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Un pleito amenaza su casa o su trabajo (relato de Otú antes de combatir).", "Quiere conservar algo que logró.", "Un grupo tiene problemas repetidos y necesita organizarse (relato de la gente de Ọ̀yọ́ y el jabón)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Vencer en la batalla.", "Que se acaben las desgracias y contratiempos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Un daño serio que amenaza la casa o el negocio.", "Un asedio por no ofrendar."]}, {"titulo": "Enseñanza principal", "texto": "Lo que se lava con ofrenda se va lejos. El que ofrenda antes de la guerra la gana; el que no, la sufre."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀tú en Àjàṣẹ́. Oyẹrẹ está en lo alto de la palma: así adivinaron para Ọ̀tú cuando iba a pelear en la ciudad de Àjàṣẹ́. Le pidieron dos chivos y dinero para ganar. Escuchó, ofreció y venció al enemigo.", "La gente de Ọ̀yọ́ y el jabón. Ọ̀ṣẹ́ está haciendo mucho daño: así adivinaron para la gente de Ọ̀yọ́. Les pidieron un cesto lleno de èṣùrú, jabón, un carnero, una paloma, una gallina y dinero. Todos ofrecieron, se acabaron las desgracias, Ọ̀ṣẹ́ no los volvió a dañar y el jabón se llevó lejos todos sus problemas.", "Ikúmija y Èyó. Ọ̀ṣẹ́ está haciendo mucho daño: así adivinaron para todos cuando Ikúmija iba a sitiar la ciudad de Èyó. Les pidieron nueve chivos y dinero. No ofrecieron."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la guerra: dos chivos y dinero.", "Contra la desgracia: un cesto de èṣùrú, jabón, un carnero, una paloma, una gallina y dinero.", "Contra el asedio: nueve chivos y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "La gente de Ọ̀yọ́."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Èṣùrú (ñame silvestre), jabón, chivos."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 210.1 (yorùbá): Qyẹrẹ (Oyẹherẹ) orí imo: / li o difá fún Otú. / Òtú nlọ jagun ilú Ajaṣẹ. / Wọ̀n niki o wa rúbọ, / a ṣegun. / Ebọ: Obúką Méjì ati egbejilélógún owó. / Ó gbọ̀ ó rú. / Ó ṣégun.", "Verso 210.2 (yorùbá): Öṣéṣewọn: / lo difá fún wọn n'ilú Eyọ̀ (Ọ̀yọ̀). / A niki wọ̀n rú: / Aperẹ (agbọ̀n) esuru, / Ọ̀ṣẹ́, eran agbo, / eyẹlé, adiyẹ / ati egàáwa owó. / Wọ̀n gbọ̀ wọ̀n rú, / wọ̀n ko ri jamba mọ. / Ọ̀ṣẹ́ ko ṣe wọ̀n mọ, / awẹnu lo ba wọn we oràn ibi nu / ati bẹẹbẹẹ.", "Verso 210.3 (yorùbá): Qṣéṣewọn: / li o difá fún wọn, / Ikúmija ngbogun lọ si òde Eyọ̀. / A niki wọn rú: / Eran Obúko mésàn ati okẹ mésàn owó. / Wọ̀n ko rú.", "REZO: OTURA SHE BABA YEGUE IDA KUDA IRU KURU ISE KUTE OBERE KETA OÑI BABALAWO TO IBAN ESHU. ASHE OLOFIN IDA KUDA IRU KURU ISE KUTE OBERE KETA OÑI BABALAWO. LODAFUN ORUNMILA ISE KUTE OYERE NIFA TO IBAN ESHU.", "SUYERE: OSHE DE OSHE BE ASHE TO. OSHE BE KEBOFI KOMADURA ASHE TO OSHE RE TO IBAN ESHU.", "REZO: BOBAPA ILA AFIACHA ODAFUN EBELLI EYELE LEBO.", "REZO: OTURA SHE OTUASHE ADIFAFUN IRUCURU IRECUTE SITECUTE CUTE MUCHE OBA OGUA ALEYO ALLORINIFA ONI IDAGUNDA IRUGUO GUIÑA ANTEPUS FETEN PONLA OGUE UIÑA ANTEPO AFEFETEN PONLA ODA QUEDATE BABA LODE ELLO ILUGUIN LEBALUO QUEBO CAMACHADA EBO AKUKO EYELE EKU EYA EPO OMERI OWO.", "REZO: IFA IDAGUNDA IROCURU ICHECUCHE AGUA LOTE OBA OLELLO ALLORI OFIFA ONI DAGUADA IRUCURU EWE GUIÑA ANTEPO AFEFE TAMPOLA OGUOA ANTEPO AFEFE TEMPOLA OGUE GUETA AFEFE TEMPOLA ONI DECUNDA TE BABADA LODERO OLLO Y IRICURU TEBALUO LODE ELLO QUE EBBO OMACHADA AIKORDIE EYELE MENI EKU EYA EPO EMENI OWO .MAFEREFUN OBATALA.", "REZO: OTURA SHE AWO ADAKUTA ERUKURU ISHEKUTE INO BABALAWO, LODAFUN ATE GORI BABA YEKE AFEFE TE YOYE ISHEKUTE AWALADO BE IFA AKUAYENE IFA ERUNURU ABERI META ENI BABALAWO KOYESI AWO AFEELTRUN ABEYENI IFA OBANI ASHE BABA YOKE IDAKUDA IRUKURU ISHEKUTE ASHE BERU LABAYE IFA ASHE TOBOGBO YOUN BOYE TOO ABAN ESHU, IFA KAFERE FUN ESHU, ELEGBA IFA WA YENI OBELI LELE OBERI KAKA BOROTITI BABA TOYEYE IYANLA TOBE YOABERENI LAYE IFA AFEFE TO IBAN ESHU.", "REZO: IKA TIKONI PANIIGBO RORO OZAIN TEMPO OYUBO, ONI PAWE WA NI FOKIN IKU ARARIRE NI PODE IKU DERE, SIYE ALAOANDEDE AWO YIRE KAFEREFUN ORUNMILA, IKU GALLINUELA. BI", "IKUY BATELOKUN EBBO MISI OTURA SHE LELEKUN GALLINUELA, AIYE EKUN.", "SUYERE: IKU DENDE DEKU BI IKU BATELEKUN EBO MISI OTURA SHE TELEKUN OZAIN OMO AWO YERE.", "REZO: ASHEDA RODA ALAGBORAN OSHEMINI ELEDA ALAGBORAN SODO INCLE AMEGO AMONAORE AKUNI AJAKA OKU OGBOBI ISIN AWO ENIFA KAFEREFUN ORUNMILA LODAFUN ELEDA."]}]$q$::jsonb),
(211,'4ad079c22bd9ff28efc4c31e8fe79c8d',$q$[{"titulo": "Idea central", "texto": "Òtúrá Òfún anuncia buena fortuna inminente si el consultante evita hacer o aceptar cualquier acto o consejo malvado. Pide no cometer adulterio y no dejarse llevar por opiniones que dividen."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se acerca una propuesta favorable (relato de Olújimi).", "Una infidelidad podría dañar la relación.", "Alguien le aconseja algo que perjudicaría a otros (relato de Ọlófin Iwatuka)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Una gran fortuna que viene de la mano de alguien importante.", "Bendición de la diosa del dinero."]}, {"titulo": "Ibi y advertencias", "puntos": ["Adulterio.", "Aceptar un consejo malvado que desordena la ciudad o la casa."]}, {"titulo": "Enseñanza principal", "texto": "Òtúrá da y Òtúrá compra: lo que se da vuelve. El que escucha al desorganizador termina viendo su casa dispersa."}, {"titulo": "Relatos reunidos", "puntos": ["Olújìmí y la fortuna que llega. Òtúrá da, Òtúrá compra para él: así adivinaron para Olújìmí cuando alguien muy grande venía a traerle buena fortuna de parte de la diosa del dinero. Le pidieron tela blanca, semillas de ìfẹ́rẹ́, dos palomas blancas y dinero para que la fortuna llegara a sus manos. Oyó y ofreció, y el adivino advirtió: no se comete adulterio.", "Ọlọ́fin Ìwàtúká y el mal consejo. El Desorganizador y el Arrojador adivinaron para Ọlọ́fin Ìwàtúká, y le pidieron una chiva, ocho gallinas, aceite de palma, dinero y hierbas de Ifá para que no aceptara un consejo malvado que dispersara la ciudad fuera de su control. Oyó y no ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la fortuna: tela blanca, semillas de ìfẹ́rẹ́, dos palomas blancas y dinero.", "Contra el mal consejo: una chiva, ocho gallinas, aceite de palma, dinero y hierbas de Ifá (kolejo)."]}, {"titulo": "Relaciones espirituales", "texto": "Ajé, la diosa del dinero. Ọlọ́fin."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ìfẹ́rẹ́ (semillas), tela blanca, kolejo, aceite de palma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 211.1 (yorùbá): Òtúrá-Fún, / Òtúrá-Fún: / a difá fún Olújimi, / Eni-ńlá maaṣe'ni l'oore. / Wọ̀n niki o rúbo, / ire Ajé de. / Ẹbọ: Aṣo funfun, ifere, eyẹlé funfun Méjì ati ẹgbèwá owó. / Ó gbọ̀ ó rú. / Wọ̀n ni: / Ko gbodo ṣ'àgbéréo.", "Verso 211.2 (yorùbá): Atuwonka, / Adawonnu: / a daa fún Ọlófin Iwatuka, / Wọ̀n niki Ọlọ̀fin wa rúbo / ki Ọlọ̀fin ma (baa) gba'moran Ìká / ki ilú ma ba tuka mọọ lọwọ. / Ebọ: Ewúré, agbẹbo-adiyẹ méjo, epo / ati egbàá méwa owó pelu ewé Ifá (Kolejo). / Ó gbọ̀ (ko) e rú.", "REZO: OTURA FOKA ADAFASE ADAFATAN EWE ODAFA AKUA ADOFO ORUN ADIFA KOKAN ORI, PRETE KORUGBO AWATE BORI ASHESI ORUGBO ESHASI MEJE.", "REZO: MOBO MOBO ADIFAFUN COCO OCHIN TERE COLLA LODO OLLO ELLE LEBO.ODAFUN OGGUN QUEREQUERE CHEQUEREGUGA OFI META.LODAFA LLECO ORUMILA LODAFA ORILLE LORUBO AKUKO OTA SIETE TRAMPAS Y UNA FLECHA. MAFEREFUN YEMAYA OBATALA OSHUN Y OGGUN.", "REZO: OTURA ADAKOY BELEFUN AWO AYARU OKUI LORUN BAKIWA ORUN OMO RARAO OLOKUN ONI NILOKUN OBANILORUN MOSREA ADAKOY BEBEWAO, ORUNMILA ONI BARA BENILORUN ORITAJE ORITOSA IYA YEYEKUN BOGBO AWO OSARAO ADAKOY.", "REZO: ADAKOY EPO OBAYENI OGUN OBAYENI IKU LOBABOÑI EYE EYE ERAN OGGUN MEGUA AGADA UERY IKU OYABA NI ORUNMILA BARABALEYE IBIFA YOAGO OBARELENI OLOFIN ORUMILA LORUBO OGGUN OGALAYERENI EBO BABA OLOFIN KULE OGGUN BABANIFE ORUMILA ORUBO OGGUN IYA MI KONI KOYA LAFISILE IRE TIO TIO TINKE LARI EITE ORU IYA MI OSHOROUNGA.", "REZO: MORERE AWO TOBAYE LELE INLE OBA YEKELE AWO AWO OFOÑAÑA IYELE MODABA INLE FEFEKUN MOLALA MAYERI OBA ARON INTORI OBA OFO INTORI OBO ANUFA INTORI BAYABI AWO OBA OFO MAYABELELE KAURE IFA INTORI BAYEBI AWO OFO MOYABELELE INTORI MAWADABA MAYENI AWO ARON IFA KAFEREFUN YANZA IFA KAFEREFUN ESHU, AWO INTORI ARON INTORI OFO.", "REZO: OTURA ADAKOY LIBEYE BABA OLUOPOPO AYEBE EKU LERI IYA GUADA FEYEFE IFA NANA RUALAYE ERU LOKUN GUAGUA OBA IFA ONA IRE INTORI ARON INTORI OFO OBA BONENI SHEPE", "OMARILE OMO FELEYE EYE AGUA LAREO ILE FORUNLEKUN YERE OMI TIRE AGUA LO OSHANLA OBI ERE LOKUA OMO IYA SHEPE OLUOPOPO.", "REZO: MOBO MABARA ADIFAFUN OBATALA ASHITINRO ODE EYI ELEBIN TORISHE ELEGBA ADIFAFUN SOKU REKO KIKOYA ERO NANI ELEGBA.", "REZO: ADIFAFUN OGGUN MEFO GUN ADIFAFUN EL GBA NAWO IRA AÑARI ADACOY ADIFAFUN KEKE ESHITUN LESE OYIYI AYA MEYI BAWAO LARIN EL OBI TORI INSHE NOBO NONA IRA AWO ÑAÑA ADIFAFUN SAKUBOKO AWO KIKEYA ORE OÑANI WERE BEKU KEKU ABI ELEGBA NONANI YAMBA BELELE EGGUN BADADA INSHE EYI KEKE IKU OMO OTURA ADACOY.", "+++"]}]$q$::jsonb),
(212,'7ce281289e9770953be66ea843d0fc68',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Ogbè habla de prosperidad, felicidad y satisfacción en la pareja; es probable una relación nueva o que la actual se intensifique. Promete grandeza a quien ofrece completo, y pide a la esposa apoyar a su marido y cuidar lo que se guarda para la ofrenda."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Busca mejorar su economía o su relación (relato de Olókun).", "Desea hijos o una relación más intensa.", "Necesita seguir siendo humilde mientras le llegan bienes."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Riqueza e hijos en abundancia.", "Extenderse por todas partes, como el océano.", "Una relación nueva o más intensa.", "Llevar al mundo algo valioso que todos vienen a buscar."]}, {"titulo": "Ibi y advertencias", "puntos": ["Que la pareja gaste a escondidas lo reservado para la ofrenda.", "Llegar a la vida con las manos vacías por no ofrendar."]}, {"titulo": "Enseñanza principal", "texto": "Lo que se junta para Ifá no se toca. El que llega con algo verdadero en su bolsa es al que todos acuden cuando el problema se anuda."}, {"titulo": "Relatos reunidos", "puntos": ["Olókun, la laguna y el pantano. Àtègbè, sacerdote de Olókun, adivinó para Olókun cuando el agua del océano no alcanzaba ni para lavarse la cara; adivinó también para Olóṣà, la laguna, cuando su agua no alcanzaba para lavarse los pies; y Òrìgí adivinó para Atan, el pantano, cuando su agua no valía nada. Los tres preguntaron si llegarían a ser grandes y se extenderían por la tierra. A los tres les pidieron ofrecer ratas èmó por cientos, en una fecha fija. Olókun empezó a juntar sus ratas y su esposa las ahumaba con cuidado para que no se echaran a perder; lo mismo hizo la esposa de Olóṣà. Pero la esposa de Atan, cuando no tenía carne para la sopa, tomaba una rata de las que él guardaba y la echaba en la sopa de òrúnlá. Atan sospechó de lo sabrosa que estaba la sopa, y ella decía que sabía como siempre. El día de la ofrenda, Olókun sacó todas las suyas, Olóṣà también, y cuando Atan le pidió las suyas a su esposa, ella respondió: son las que eché en la sopa de òrúnlá que siempre comemos. Atan no tuvo ni una para ofrecer. Por eso Olókun se extiende por el mundo entero, la laguna lo sigue, y el pantano se quedó atrás, con agua que no corre.", "Los tres viajeros y la doncella en la bolsa. Alápété, Onílàbà y Alápò Àgbìrà venían juntos del cielo a la tierra, y a los tres les pidieron ofrendar para llevar algo valioso consigo. Alápété y Onílàbà se negaron; solo Alápò Àgbìrà ofreció. En la puerta entre el cielo y la tierra los revisaron: en la bolsa de Alápété no había nada; en la de Onílàbà, nada; en la de Alápò Àgbìrà apareció una doncella. Dijeron: este es el único que podrá sostener el mundo. Ya en la tierra, cuando hay que emprender algo importante o un problema se anuda, todos van a consultar a Alápò Àgbìrà, que es otro nombre de Ifá, y la vida próspera vive con él hasta hoy.", "Olókun, el rico. Àtègbè adivinó para Olókun y le pidió una carnera y dinero, diciéndole que sería muy rico y tendría muchos hijos. Ofreció, se hizo muy rico y fue señor de muchos hijos.", "Akísà y la miel. Ìrè ntègbè adivinó para Akísà, que iba a darle miel a su Ifá. Le pidieron miel, àádùn y nuez de kola. Ofreció, y Ifá también le dio miel a él."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la grandeza: ratas èmó en cantidad, guardadas y ahumadas, ofrecidas en la fecha marcada.", "Para llevar algo valioso: la ofrenda que marque Ifá.", "Para riqueza e hijos: una carnera y dinero.", "Para la dulzura: miel, àádùn (maíz tostado molido con miel y aceite de palma) y nuez de kola."]}, {"titulo": "Relaciones espirituales", "texto": "Olókun, dueña del océano; Olóṣà, de la laguna. Ifá como Alápò Àgbìrà, el que lleva lo valioso."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ratas èmó, miel, àádùn, obì (kola), òrúnlá (quimbombó seco)."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 212.1 (yorùbá): Atègbè, Atègbè awo Olókun / li o difá f'Olókun. / Agùtàn ati egbàá mésan owó li ẹbo, / wọ̀n ni: \"a di alájé, a di olomo\". / Ô gbọ̀ ó rú. / O di Alajé, / O di Ọlomọ ati bẹẹbẹẹ.", "Verso 212.2 (yorùbá): Irẹ̀-ntègbè awo Akísa: / li o dífá f'Akísa, / nigbi oun maa fún Ifá rẹ l'oyin. / Wọ̀n niki o rú: / oyin, aadun ati obi. / Ó gbọ̀ ó rú. / Ifá fún oun naa l'oyin bẹẹ.", "REZO: IRETE ENTEBE BOLE ABIRI KOLO OMOLUBO ABATA ATI KOTOPO OMOLUBO OWARA YANIYE OMOLUBO META LABA PARI ATI META LABA MERIN LODAFUN IGBAÑI. LODAFUN LANIYE.", "SUYERE : “ EYENI UN WEMILESE IGUERE IGUERE ALAARA LONA ONAWA MIRIN AWO AWOMIRIN OMOWO MIRIN A IKU”.", "REZO PARA PREPARAR EL INSHE: BABA ORAGUN MAFUN OBATALA BABINU EBERE IRETE LEYE BEFA IRETE UNTELU BEMORE OFUN YENE YENE YENE OKUORO EBORA OBATALA ORIBE IRETE UNTELU EBORA OMA YEKUN OJUANI SHOBE EBORA ORI BAYE OJUANI SHOBE MEYI EBORA BARA LELE IFA OTRUPON ADAWEÑO EBORA MOYARE IRETE UNTELU BEMORE NEYI OKUO IRETE KUTALE WAN WAN LORI EFA EBORA OGGUNDA MEYIS BORUBOKUNA ARA ORUN LAYE EBORA OTUAKUN NI LORUN OTRUPON KAMOYA WE WEFUN MAYE KO OJUANI POKON MAYARE BEBE OKUN LOYE OBATALA OBA IRETE UNTELU IFA KAFEREFUN SHANGO OREGUN EBORA FUMI IRETE UNTELU BAWARA OMO OGO OKA YENI YENI IRETE UNTELU EBBO.", "REZO PARA EBBO: BABA FOBAE OKA KUELE ORUMELE BABA IFA BABAKUELE IRAWO BABA KUELE INLE OWERE OBA NI ORUN BELE BELELE IFA IRETE UNTELU MOFORIBALE OSHANLA BIRINI WA OBA NIREO ODIPUE OBA ORUMALE EYE NIREO OBATALA MOFORIBALE ODUFUE OLORUN.", "REZO: OPA BOMBO NISI OYU ELENI NI YAKO ADIFAFUN ASHO FUN FUN ODEIYA TIN LOSI WAEA TONLE FI ARAYE WALE EYELE, ADO, EWEFA LEBO. IRETE UNTELU MAFEREFUN OLOFIN.", "REZO: IRETE UNTELU IFA OPOLONGO BIKU, OPOLONGO BI ARUN, OPOLONGO BI ARAYE, OPOLONGO BI EYO UMBO OPOLONGO BABA NISHE OMO NIYE ONIYE OUN BABALAWO ADIFAFUN SHAPAT", "TINSHOMO, SHAPAT ORUBO IN IYA NEYI ONI OLOFIN AYE NIALARA, AIKORDIE OKAN, ABEBOADIE MEYI, EYELE MEYI, EKO MEYI ELEBO. OLOFIN AL NI SHAPAT LORUBO NI ORUGBO RI MI OUN IYO MEYI ONI OLOFIN OYONO ILERE.", "REZO: EYINI UN WEMILESEIWERE ELUBORAN LENA ENAWE MIRIN OWO EWE MIRIN OMO EWE MIRIN ARIKU.", "REZO: MOLE AGUIRI SELE OMOLUBO ABITARI KOLOPO OMOLUBO AGURA YENIYO OMOLUBO META LABA PARI META LABA MARI LODAFUN IGBAÑI LODAFUN YANYA OBO LEARE.", "REZO ARARA: ASUMU KIKE NADI ASIWU. ASINU KIKE NADI ASUMU. VODU ÑAKO MA MEZO. ASIDA KASA MASA MASU.", "SUYERE: ONI AWA AGBA LAYO ENSHEGBO TETE MORIN TETE MOÑA. ONI AWA IYORUN LAYO ENSHE ODAN TETE MORIN TETE MOÑA. AWA KEKEE LAYO INSHE OYO AYAKA TETE MORIN TETE MOÑA.", "SUYERE: EYENI OUN WEMILE ESE IWERE IWERE ALUARAN LONA ONA WEMILE ONA AWO MIRIN OMO WO MIRIN OMO MIRIN IKU.", "REZO: IPI APEKI TETE KOMATE IBEMI TETE ADIFAFUN ORUNMILA. IDEGERE GERE NITO OSUN IDEGERE GERE NITO OSAH IBA GIPA NITO OSHA SEKE SHEKE NITO ORAGUN IDEGERE GERE NITO OSUN.", "REZO: IBI APEKE TETE KOMATE IBENI TETE ADIFAFUN ORUNMILA IDEWESE WERE NITO OSUN IDEWESE WERE NITO OSHA IBA GIFA NITO OSHA SEKE NITO OGGUN IDEWESE WERE NITO OSUN.", "REZO: ERU OMO ONO NINSHE AUN BABALAWO LODAFUN SHAPATA TINSHOMO OLOFIN LORU ORUGBO.", "REZO: ADIFAFUN ELEGBA ENSO OSHA BENSHE ONSE OSHA ARA EKO BEBE IWA KEBEBE ORO IWOSHE ONIKOYU NARA ADIFAFUN SHAKETA AWO TINSHE OMO ELEGBA NINENA OROBI IWA BOLORUN OLOMU ETA EYE LOKE KARAYE LELE SABADA OBI OSILA PIPO ELEGBARA IRETE BEMORE OBA TEKU ORUN OLORUN ELEGBARA OKAN LELE GUN EWO EYE OBINI META IWA FOGUN OKE ARUN SHAKETA AWO DURO. SI EWEDEMEY ORUN OLORUN KUA IFA NI LORUN IFA LODAFUN ELEGBARA.", "REZO: IPI APEKI TETE KOMATE IRENI TETE ADIFAFUN ORUNMILA IDEGERE GERE NITO OZUN IDGERE GERE NITO OSHA IBA GIPA NITO OSHA SEKE SHEKE NITO OGGUN IDEGERE GERE NITO OZUN.", "REZO: IRETE UNTELU NISHOYU ABENI NI YABO ADIFAFUN BAKERE ASHO FUN FUN ODE IYUTEN LESI WARA TONLO BUYARE WALE EYELE ASHO EWE FA IRETE UNTELU MAFEREFUN OLOFIN."]}]$q$::jsonb),
(213,'61bd97bdb8742268742215ef44a9e571',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Ọ̀yẹ̀kú llama a iniciarse en Ifá y a llevar una conducta moral rigurosa para evitar pérdidas y la muerte propia o de la familia. El consultante ha vivido pensando solo en sí mismo, y eso amenaza su negocio y su familia. Promete victoria en tierras lejanas y riqueza aunque otros lo hayan dado por perdido."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["El egoísmo está dañando un negocio o la relación familiar.", "Teme perder a los suyos al hacerse conocido (relato de Orifusi).", "Necesita revisar si está actuando con honestidad.", "Va a viajar y pregunta si volverá con bienes pese a los adversarios."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Escapar de la muerte repentina, él y su familia.", "Volver con ganancias de un viaje lejano.", "Riqueza aunque otros lo descarten.", "Que los enemigos peleen entre sí."]}, {"titulo": "Ibi y advertencias", "puntos": ["El egoísmo que destruye la casa.", "Matar sin necesidad.", "Gente que lo da por acabado y murmura de lejos."]}, {"titulo": "Enseñanza principal", "texto": "Hacer la ofrenda y luego reducir la bondad no sirve. El que quiere librarse de la muerte no le quita la vida a ningún ser. Doscientas estrellas no hacen una luna, y cuatrocientos veinte sirvientes juntos no igualan a un hijo propio."}, {"titulo": "Relatos reunidos", "puntos": ["Pèrègún y la conducta que aparta a la muerte. Orífúsì, padre de Elu, y Pèrègún buscaban la forma de evitar que la muerte se los llevara por sorpresa a ellos, a sus hijos y a sus esposas, ahora que se estaban volviendo famosos. Muchos adivinos les dijeron que debían ofrecer diez palomas, diez gallinas, dinero y mucho aceite de palma al pie de Èṣù, y además iniciarse en Ifá, porque Ifá enseña la conducta que desvía la muerte del camino. Les advirtieron que de nada sirve ofrecer y luego hacer menos bien: debían llevar las palomas y gallinas a casa, soltarlas sin matarlas y darles de comer cada vez que volvieran, y desde ese día no quitarle la vida a ningún ser, salvo a una serpiente venenosa. Pèrègún escuchó y cumplió, y cantaba: la muerte no vigila mi casa para arruinarla, yo no he hecho ningún mal; a amigos y enemigos les hago bien; cuando vi gente en pleitos me compadecí y los ayudé; la pobreza no vigila mi casa porque nunca he sido haragán; la pérdida no vigila mi casa porque nunca robaré.", "Ọ̀rúnmìlà en tierra lejana. Ọ̀rúnmìlà iba a ejercer su sacerdocio en un lugar muy lejano y preguntó si traería algo de allá. Le dijeron que encontraría enemigos al llegar, y le pidieron ratas y pescado para su Ifá. Cumplió. Al llegar, los enemigos quisieron hacerle la guerra, pero mientras lo planeaban se pelearon entre ellos y terminaron favoreciéndolo. Ọ̀rúnmìlà empacó todas las ganancias de aquel lugar y las trajo a casa.", "Atèéyèlèkú y el ala del pollo. Atèéyèlèkú era alguien a quien la gente ya había dado por perdido en sus pensamientos. Le pidieron un pollo para pasárselo por todo el cuerpo, matarlo y dar la punta del ala a un niño, cocinando el resto para servirlo a la gente. Lo hizo y empezó a tener riqueza, aunque los murmuradores venían de lejos a hablar mal de él. Por eso a la punta del ala del pollo, que se corta, se le llama Arónipín, el opresor."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra la muerte: diez palomas y diez gallinas (que se sueltan en casa y no se matan), dinero y mucho aceite de palma al pie de Èṣù; iniciarse en Ifá.", "Para el viaje: ratas y pescado para Ifá.", "Para la riqueza: un pollo pasado por el cuerpo; la punta del ala para un niño y el resto cocinado para la gente."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù Ọ̀dàrà recibe aceite de palma; no come pimienta ni aceite de almendra de palma (àdín). Ifá enseña la buena conducta. Òpè, a cuyos pies se encuentra la alegría."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aceite de palma, palomas, gallinas, ratas, pescado, pollo."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 213.1 (yorùbá): Orifusi Baba Flu, / 1 oun nwa ibi a ba yẹ̀ ikú si / kio male pa oun, / omo oun ati aya oun, / bi ayé ti nkokiki àwọn yi. / Mujimuwa awo Opakerẹ, / Bonronyin awo Ode-Ido, / Ogorombi awo Ode-Eṣa, / Gbeminiyi awo llujumokẹ, / Kuyinminu awo Ọ̀pẹ̀, / a difá f'Orifusi, / a difá f'Pèrègún / Nigbi wọn nwa ibi àwọn iba yè ikú si. / A ni: / Biẹbawipe ki Ikú ma le pa yin, / ki ẹ rúbọ, / Ki ẹ si wa tẹ Ifá. / Ebọ: Ẹyẹlé mẹwà, adiyẹ mẹwà, / egbàáwa owó, opolopo epo nidi Eṣú. / Ifá yoo maa kọ yin ni iṣe / ati iwa tikijẹki a kú. / Wọn ni biẹba rúbọ / ki ẹ bẹrẹsi rere-iṣe / lati oni lọ ju ti atẹhinwa. / Lasan li ẹ rúbo, / bi ẹ ba din iwàrere kù eo kú. / Ki ẹ ko àwọn eyẹlé / ati adiyẹ lo si ilé yin. / Ki ẹ ko wọn da silẹ. / Ki ẹ maṣe pa wọn. / Ki ẹ maa fún wọn ni ounjẹ / bi wọn ba jẹ wa ilé. / E ko gbodo pa ohunkohun / lati oni lq nitori ẹniti ko fẹki ikú pa oun, / kioma ṣe ikú pa ohunkohun afi oṣika ejò. / Pèrègún gbọ̀ ó rú. / Orin Ifá naa: / Ikú ma sọ'le mi d'ode, / nko ma ṣika. / Arùn ma so'le mi d'ode, / nko ma ṣika. / At'ọ̀tá at'òdi mo ṣe wọn l'oore, / nko ma ṣika. / Ejọ ba wọn l'Ake mo darodaro / mo ṣewon l'oore, / nko ma ṣika. / Ejọ ba wọn l'oko mó darodaro / mo ṣe wọn l'oore, / nko ma ṣika / Ejo ma so'le mi d'ode, / nko ma ṣika. / Mo b'ẹniméji njà mo la wọn, / nko ma ṣika / Oṣì ma sọ'le mi d'ode, / nko jẹ Ṣ'ọlẹ. / Èṣú-Ọ̀dàrà kii j'ata, / Eṣú-Ọ̀dàrà kiij'adin, / Mo f'epo f'Aseni, / nko ma ṣika. / Ofo ma so'le mi d'ode, / nko jẹ jale.", "REZO: ADIFAFUN AEWRE ORUNMILA AKUKO, ELEBO,OWUNKO, OTI, EPO OFA META ELEBO, AGBADO ELEBO.", "REZO: IRETE YEKU OTE IKU OJIBIRIN IWAÑARI ORISHA OTE ADIFAFUN OLONOSHE TIBOGUN LOD AGUERE.", "REZO: IRETE YEKU ABADA BI ABADA. ABADA BI ABADA ADIFAFUN WENWELE SELETISHOMA AYA LORUGBO. KORU OKA ASENU BAB ADIFAFUN OLONOSHE UMNATIN OWO WERE OGU TI BIELE.", "REZO: IRETE YEKU MOTEYEKU OYIBIRE IBAÑARI KOSHETERO ADIFAFUN IBA ERI LATO GBOGBO UNGUE LODE AKEREKE UGUE AWERE LORUBO AFOFADA AYARUFO. ABO LEBO.", "SUYERE: DARABIÑO UNLOYO KORU EBO.", "SUYERE: OLONOSHE BIRERE OLONOSHE BIRERE IRUN LAFI KAYO ODERE IRU.", "REZO: AJUAGAN ASHO PAJEENI IBEYI DJISUDADA OBA JOVIE NILE JORO JORO AJALA A BAKUYEYELEE ORISHA VUDUN KAFEREFUN BOKONO.", "SUYERE: SHATSHA JESU ZOGUEDEBO SOUME DEANGHO BEJOUSE ADAN TOMO DEPOMAFAN SUMUSE AJUANGAN BOKON IWA SAKPSONE.", "REZO: OKAN ABENU BABA ADIFAFUN OLOGOSHE UMBATI NAWO KEREGUTO VELE ADIFAFUN ORUNMILA."]}]$q$::jsonb),
(214,'bbbdeaa594ffcfa01f12a6af807db1dd',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Ìwòrì advierte de complots y habla de practicar Ifá para vivir con prosperidad. La paciencia, más que la ira o la frustración, traerá éxito material. Pide no guardar rencor y ser buen vecino: la fortuna está dentro del propio barrio, y los mismos que fueron enemigos pueden terminar enriqueciéndolo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Nota tensiones o maniobras dentro de un grupo (relato de Ọlófin Iwatuka y la guerra).", "La frustración lo empuja a actuar con enojo.", "Busca respeto y aprendizaje en su práctica espiritual.", "Siente que le falta fortuna y quiere entender por qué."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Respeto y autoridad por Ifá.", "Fortuna dentro de su propio barrio.", "Que los antiguos enemigos lo enriquezcan.", "Ser honrado en una fiesta de las àjẹ́."]}, {"titulo": "Ibi y advertencias", "puntos": ["Guerra e intrigas.", "Rencor con los vecinos.", "Ser atacado en una celebración por los propios anfitriones."]}, {"titulo": "Enseñanza principal", "texto": "Las guerras estropean el mundo y las intrigas arruinan a la gente. Quien obtiene Ifá se vuelve respetable y obtiene autoridad: así como el àgbẹ̀ saca huevos blancos de entre sus plumas oscuras."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà y los vecinos. Ọ̀rúnmìlà lloraba porque no tenía buena fortuna. Llamó a Wọ̀nwọ̀rẹ́, el sacerdote del forastero, que vio Ìrẹtẹ̀ a la derecha e Ìwòrì a la izquierda y le pidió palomas, ratas y pescado para su Ifá. Ofreció y fue amable. Entonces los vecinos que antes ni lo saludaban empezaron a saludarlo y a pedirle que adivinara para ellos; los que necesitaban ratas las traían, los que necesitaban pescado lo traían. Ọ̀rúnmìlà llegó a ser el mayor reconocido del barrio y se hizo muy rico: fueron los mismos que habían sido sus enemigos los que lo enriquecieron.", "Ọ̀rúnmìlà en la fiesta de las àjẹ́. Ọ̀rúnmìlà iba a una celebración con las àjẹ́ y preguntó si no le pasaría nada malo. Le dijeron que lo tratarían bien, pero que ofreciera para que sus anfitriones no se volvieran contra él, porque ellos dicen: no estamos tan bien vestidos como nuestro invitado. Ofreció y fue con la tela que llevó. Lo honraron y lo respetaron. Miró sus caras, duras como de pez, que se volvieron suaves como de caracol. Le pidieron que hablara para calmarlas, y Ọ̀rúnmìlà salió bailando. Cantaba: magos de la casa, perdónenme; àjẹ́ de la casa, perdónenme. Ifá promete que las àjẹ́ no estarán enojadas con esta persona si les da lo que piden.", "Ọlọ́fin Ìwàtúká y la guerra. Las guerras estropean el mundo, las intrigas arruinan a la gente: así adivinaron para Ọlọ́fin Ìwàtúká, y le advirtieron que la guerra era inminente. Para salir victorioso debía ofrecer dieciséis huevos, un carnero, un chivo, un gallo, dinero y medicina de Ifá. Escuchó y no ofreció.", "Ìrẹtẹ̀ inicia a Ìwòrì. Escuché un ruido que resonaba y pregunté qué pasaba: me dijeron que Ìrẹtẹ̀ estaba iniciando a Ìwòrì. Ifá dice que será respetable; Òrìṣà dice que tendrá autoridad. El àṣẹ del àgbẹ̀ le permite sacar huevos blancos de entre sus plumas oscuras, y el del àlùkò, de entre sus plumas rojas. A Ọ̀rúnmìlà le pidieron doscientas pimientas de caimán, nueces de kola y dinero, ofreció, y le aseguraron que en su boca tiene el àṣẹ. Para volverse rico, se dice, hay que practicar Ifá."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la fortuna del barrio: palomas, ratas y pescado para Ifá.", "Para las àjẹ́: lo que ellas pidan, entregado sin rencor.", "Contra la guerra: dieciséis huevos, un carnero, un chivo, un gallo, dinero y medicina de Ifá.", "Para el àṣẹ: doscientas pimientas de caimán, nueces de kola y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Las àjẹ́ (Ìyàmi) y los magos de la casa. Òrìṣà da autoridad. El rey de los Òrìṣà, a cuyos pies se encuentra la fortuna."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Pimienta de caimán (ataare), obì (kola), huevos, ratas, pescado; plumas de àgbẹ̀ y àlùkò."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 214.1 (yorùbá): Ogun-bayéjẹ, / Otẹ-ntẹ-omo-èniyàn-ri: / a daa f'Ọlófin Iwàtuka. / Wọ̀n ni: / Ogun ma de o, Ọlófin! / nitorinaa bi Ọlófin ba wipe / ki òun ṣegun / ki o wa rubọ: / ẹyin-adiyẹ mẹrindilógún, agbo, òbúką, akuko-adiyẹ, / ẹgbàá mokànlá owó ati ewe Ifa. / Ọlotin gbọ̀ ko rúbọ.", "Verso 214.2 (yorùbá): Ẹẹkinni mo ngbọ teregungun / Mo ni kinni nṣe? / Wọ̀n ni Ìrẹtẹ̀ ntẹ Ìwòrì / Fẹkeji mo ngbọ̀ teregungun / Mo ni kinni nṣe? / Wọ̀n ni lrẹtẹ̀ ntẹ lwòri. / Ifá ni Alaba, / Oriṣà ni Aláṣẹ. / Àṣẹ Àgbe li Àgbe fiidúdú / tiifiiye eyin funfun, / Aṣẹ Àlùkò li Àlukò fiipupa / tiifiiye eyin funfun: / a daa f'Ọ̀rúnmìlà Bara Àgbọnnìrègún. / A niki ó rú: / Igba oluya, obi ati egbàáwa owó. / Ó gbó ó rú. / Wọ̀n ni: / Enú rẹ̀ li ao maa gbọ Àṣẹ. / Njẹ Ifá di Alába, O di Aláṣẹ. / Awo ni Gberẹfu iṣe-i-la, Awo.", "REZO: IRETE YERO ORUNMILA LORUBO TO IBAN ESHU. TELEBO IBO KIBO BAB OLORUN, BAB DUPUE TO IBAN ESHU.", "MORUNYO MORUNYA ASHE IYALOSHA. “ “ “ BABALOSHA. “ “ “ OLUWO. “ “ “ OYUGBONA. “ “ “ IY GONGOLAYE LAYERERE. “ “ “ EGUN. “ “ “ IRETE YERO. GUNGUN EYE LEBO EBE AD FELEBO EBO FELEBO.", "SUYERE : TRES EÑI ADIE, UNO CON ERI, UNO CON EFUN, Y UNO CON EPO DELANTE DE ELEGBARA Y PONERSELO ENCIMA. AL OTRO DIA LOS ENTIERRA EN LUGARES DISTINTOS LEJOS DE LA CASA, CON SUMO CUIDADO DE QUE NINGUNO SE ROMPA.", "REZO: IRETE YERO TINYEBO EBO KIBO AKALAMABO ADIFAFUN YERUBE TINSHOMA ORUNMILA ORU LAYEDE ELEGBARA ERU LASHED KARA OLOFIN ADIFAFUN YERUBE ONI SHEBE LERI YOKO AYEBE ESE TENA ERI TIMOBAYE AYEBO NI AYE ILU EYENI SEGUN BAYEPE AYO OSHEBE.", "SUYERE: OYIKI YIKI OTA LO MIO. OYIKI YIKI OTA LO MIO. OYIKI YIKI AGBADO OKUMA. OYIKI YIKI OTA LO MIO.", "CORO: LO CONTESTA TODO. OLORUN MAYE OBOLO WOÑI, OLORUN MAYE OBOLO WOÑI NI OBOLO WOIGBO.", "CORO: OLORUN MAYE OBOLO WOÑI.", "A: mowa ayeo …….. Coro: wara wara laway wara wara. A: moway moway …… Coro: wara wara laway wara wara. A: okere ojana …… Coro: ern ni shoro eran. A: okete o odu oya .. Coro: eran ni shoro eran. A: orofo ababa …… Coro: eiye ni shoro eye. A: werureo werureo abibo werureo yara werure okoy malo. Coro: ( lo mismo ).", "REZO: IRETE WORI EYEBERIYOKO ESE OTONA ERUTI OMA AYOBINI IGUIN KILEBO AKARA MALO ADIFAFUN YERUBE TINSHOMO OLODUMARE KAFEREFUN YALORDE.", "SUYERE: IKUNO Y OMIANUBE VOMI OBULE VOMI IKUBAYO OKUO.", "REZO: IRETE YERO AYEBERIYOKO EGGUN IGUNGUN ODFUN ORUN OLORISHA OMO ODDUA A LODDO TINSHE EGGUN ADAJUN ORUN LAYENIFA ORUN ERU EGGUN IGUIYU OMOBINI ARUN ISUN LERI", "LORDAFUN YOKAN UNYEREBEN ORUNMILA OFUN YERE IWORO TINSHORO AWO LORDAFUN ORUNMILA. REZO: GUNINIKU AWO MAYEKUN EGGUN AGADA ÑAÑIRE IKU OTOKU EYA ORUN EGGUN AKATE MAWA NARI NAFUN BUMBAM FEFEKULE BEYEKUN EGGUN BAMBAM YOGA ANIRI FE WAO BARIBAN MORIBARUN OKU ORUN BAMBAM MORI BORUN AKUO BAMBAM MORIBO RUN OKUO BARIBAN ADIFAFUN AWO BONI LORUN.", "REZO: IRETE YERO OLORUN YERUBE LENIFA ORUN GUA ABEBE ATEMORA AWO OBA IKU EBE OBA OLOFIN SHANGO INLE ADAGUELE AWO DINOLU INLE ADALOGUE AWO OBA IKU IRETE YERO EBE SHANGO AWO OBA IKU.IRETE YERO SEGUERI EYU EYEYI UNSORO OYIYIAWO OBA IKU IRETE YERO ODDUBALE ALA OSHA AGBORAN AWO OBA IKU IRETE YERUBE KAFEREFUN OLOFIN KAFEREFUN ORUNMILA KAFEREFUN SHANGO."]}]$q$::jsonb),
(215,'fed25e38194e34f90175a0890fa18229',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Ìdí habla de la resistencia a cambiar y de la necesidad de hacerlo. Hay una relación que no tiene futuro y conviene pensarla de nuevo. Pide ofrecer a Ọ̀rúnmìlà aunque la familia lo margine, ser generoso cuando llegue la dulzura y no destruirse con la propia boca."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Sigue en una situación que ya no le conviene (relato de Ọlọ, que no quiere levantarse).", "Una relación necesita replantearse.", "Necesita aceptar ayuda para avanzar.", "Su casa lo descuida y aun así sigue con su deber."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Riqueza, pareja e hijos en abundancia.", "Esperanza para los menos favorecidos.", "Siempre tener quien lo cargue y lo ayude."]}, {"titulo": "Ibi y advertencias", "puntos": ["No querer moverse de donde uno está.", "Ser marginado por la propia familia.", "Volverse mezquino cuando las cosas se endulzan.", "Delatarse con la propia boca."]}, {"titulo": "Enseñanza principal", "texto": "La abeja anuncia con su propio zumbido que tiene miel, y luego pica al que se acerca. El que tiene abundancia no debe ser malo con los demás."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà come en el desván. Ọ̀rúnmìlà subía su comida al desván para comer solo, porque quería tener hijos y toda la casa lo había descuidado. No tuvo miedo y siguió ofreciendo a su Ifá. Con el tiempo le llegaron la riqueza, las esposas y tantos hijos que no se podían contar. La familia, al ver esto, se acercó a pedir su parte. Ifá oye desde la ciudad de Adó; Ọ̀rúnmìlà escucha aun bajo tierra.", "La abeja melífera. Olúòhòròbí, que es el nombre de la abeja de miel, preguntó si sus cosas serían dulces. Le pidieron ofrendar y le dijeron que sí, pero que después de endulzarse debía ser generosa y no ser mala con la gente. Ofreció y sus cosas se endulzaron. Pero cuando el panal está lleno y el hombre quiere tomar un poco, ahí mismo la abeja empieza a picarlo; y el hombre ni sabía de su abundancia: es la misma abeja la que la anuncia con su zumbido. Por eso le dicen: Olúòhòròbí, no eres buena; ¿por qué eres tan mala con la gente?", "La piedra de moler. Ọlọ̀, la piedra de moler, no quería levantarse de donde estaba sentada. Le pidieron dos palomas, dinero y medicina con hojas de gbégbé. Escuchó y ofreció, y le aseguraron que nunca le faltaría quien la llevara a cuestas."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la fortuna: ofrendas continuas a Ifá.", "Para la dulzura: la ofrenda marcada, y ser generoso después.", "Para tener quien lo cargue: dos palomas, dinero y medicina con hojas de gbégbé."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà, que escucha desde Adó y bajo tierra."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Gbégbé (Icacina trichantha), miel."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 215.1 (yorùbá): Ijoko-àgbà-biik'ẹni-ma-dide-mọ. / Àgbà-m'opa-l'ọwọ̀: / a difá fỌlọ. / A ni ibiti Ọlẹ joko si koniiwuu / ki o dide mọ. / A niki ó rú. / Eyẹlé Méjì, / egbẹjiélógún owó / ati ewé gbégbé. / Ó gbọ̀ ọ̀ rú. / Wọ̀n ni: / Ọlọ a maa r'eni gbe oun.", "REZO: IRETE UNTEDI AMADIO AWO LERI LODAFUN OLOFIN, LODAFUN ORUNMILA, YEMEYA, OSHUN, OZAIN, ELEGBARA OGGUN, EPEPEYE LEBO.", "REZO: IRETE UNTEDI AMUDI AWO LORDAFUN ORUNMILA LORI OSI.", "REZO: IRETE UNTEDI AMAD NIMU ADIFAFUN AWAN LORI TONSHOLU APARE OSI AMUDI AWO LORI OSA IFA NI MAFEREFUN OLOFIN, YEMAYA, OBATALA, ORUNMILA ATI BOGBO KALENO OSHA.", "REZO: OPAYERU BOFEREFUN LA PIENU ADIFAFUN SHANGO, ORUNMILA, OSHUN, ELEGBA ATI OZAIN.", "REZO: IFA NI KAFEREFUN OLOFIN, YEMAYA, OBATALA,ORUNMILA, ATI BOGBO OSHA KALENO.", "SUYERE: CORU EURU BETE. MARIWO OZAIN MARIWO NEN MARIWO."]}]$q$::jsonb),
(216,'03332fdf8ea39c24051ca9c4f1ec19db',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Ìrosùn habla de dificultades inesperadas que están por llegar. El consultante se siente presionado por causas difíciles de identificar: detractores y envidiosos. Promete tiempo y espacio para hacer el bien, ser agradecido con los maestros y salir libre de las garras del detractor."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente presionado seguido y no sabe bien de dónde viene la presión.", "Un obstáculo inesperado podría afectar un plan (relato de Ọlófin).", "Busca prepararse para asumir una responsabilidad o una autoridad (relato de Ọ̀rúnmìlà y su aprendiz)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Tiempo y espacio para hacer el bien.", "Un discípulo agradecido que recompensa.", "Librarse de los detractores.", "Que nada se eche a perder.", "Quedarse con la casa que se construyó."]}, {"titulo": "Ibi y advertencias", "puntos": ["Un problema imprevisto.", "El detractor (Elénìní) que se traga a los poderosos.", "Ser ingrato con quien le enseñó."]}, {"titulo": "Enseñanza principal", "texto": "Nunca se debe ser malagradecido con el maestro de Ifá. Contra el detractor no sirve la fuerza: sirven la ofrenda, la comida compartida y la palabra suave que lo reconoce como padre."}, {"titulo": "Relatos reunidos", "puntos": ["El hijo de Eléwì Odò. Ọ̀rúnmìlà iba a iniciar en Ifá al hijo de Eléwì Odò y le pidieron ofrendar. Le enseñó el idioma de Ifá; el muchacho aprendió todos los cantos, no se saltaba ningún paso ni mentía, e interpretaba exactamente lo que Ifá decía. Entonces Eléwì Odò juntó cargas de riqueza y se las dio a Ọ̀rúnmìlà, rogándole que las aceptara porque había enseñado a su hijo. Por eso uno nunca debe portarse mal con sus maestros de Ifá.", "Elénìní, el detractor. Ọ̀rúnmìlà, Ṣàngó, Òòṣàálá y Ògún venían del cielo a la tierra, y Elénìní, el detractor, los siguió. Ògún era mago, Ṣànpọ̀nná también, y casi todas las deidades confiaban en su poder; Ọ̀rúnmìlà solo conocía la ofrenda. Le pidieron una chiva, preparar àmàlà, servir bebidas y poner mucho oyóyó en la sopa, no usar pantalón durante siete días y llevar una tela atada a la cintura. Ọ̀rúnmìlà avisó a todos que venía un hombre muy fuerte llamado Elénìní, y todos dijeron que era una amenaza vacía. Elénìní llegó a casa de Ògún; Ògún tomó su arco, sus flechas, su hacha y su machete, y apenas asomó la cabeza, Elénìní abrió la boca y se lo tragó. Fue a casa de Ṣànpọ̀nná y se lo tragó; fue a casa de Ṣàngó, que echaba fuego por los ojos y por la boca, y se lo tragó; fue a casa de Òòṣà y también se lo tragó. Llegó a casa de Ọ̀rúnmìlà, que salió bailando con un rabo de caballo en cada mano, sin pantalón y con la tela en la cintura, y con los tambores cantando: Elénìní es nuestro padre. Elénìní preguntó qué decían, y le contestaron: que tú eres el padre de todos, que no se te desprecia. Le sirvieron comida, bebida y carne, y desde ese día se saca comida para los seres del cielo. Elénìní comió, bebió y quedó satisfecho, y dijo: tú, Ọ̀rúnmìlà, sigue gozando de la vida. Desde su vientre Ògún lo oyó y cantó pidiendo a Ọ̀rúnmìlà que lo rescatara; Elénìní dijo que se lo había tragado por no ofrendar, pero que eran sus compañeros en el gobierno del mundo, y lo vomitó y se lo entregó a Ọ̀rúnmìlà. Lo mismo pasó con Ṣànpọ̀nná, que salió corriendo y no quiso volver a saber de Elénìní; luego con Ṣàngó y con Òòṣà. Así Elénìní vomitó a todas las deidades y se las entregó a Ọ̀rúnmìlà.", "Ọlọ́fin y el problema imprevisto. A Ọlọ́fin le pidieron una paloma blanca, una gallina blanca y dinero para que no le llegara un problema inesperado.", "El leopardo, el chivo y la casa compartida. Así adivinaron para el leopardo cuando iba a tomar tierra para una casa nueva, y le pidieron un saco de cáscaras de maíz y cuatro palomas, llevados a un huerto junto al agua, para que otro no gozara el fruto de su trabajo ni buscara ayuda ajena para vencerlo. El leopardo no ofreció: confiaba en la fuerza de sus brazos. El chivo llegó primero a un terreno y lo limpió. Al otro día el leopardo encontró el terreno limpio, preguntó quién se lo había limpiado y cavó la tierra para el barro. Al otro día el chivo preguntó quién le había cavado su tierra y levantó una capa de pared. Así fueron trabajando sin verse: paredes, vigas, sogas, techo de hojas, cada uno preguntando quién le estaba construyendo su casa. Cuando el chivo fue a mudarse, se encontró con el leopardo, y los dos se reclamaron la casa. Iban a pelear, pero la chiva dijo que vivieran juntos. Un día el chivo vio que el leopardo traía a casa el cuerpo de su padre para comérselo, y al siguiente el de su madre. Fue con un cazador y le prometió una recompensa si mataba un leopardo. El cazador lo mató, y el chivo venía cargando el cuerpo cuando el leopardo lo vio y, asustado, le preguntó cómo lo había matado. El chivo dijo que tenía mal de ojo: todo lo que miraba moría. El leopardo saltó al monte y nunca volvió. Por eso los leopardos viven en el monte y los chivos junto a las casas. Ifá pide que el cazador ofrende para no matar a una persona ese año, y que quien vaya a tomar tierra para casa o finca ofrende para que no le hagan medicina en contra; tampoco hay que tratar como niño a quien tiene un padre fuerte detrás."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para el maestro: la ofrenda marcada al iniciar a otros.", "Contra el detractor: una chiva, àmàlà con sopa con mucho oyóyó, bebidas y carne para compartir; no usar pantalón durante siete días y atarse una tela a la cintura.", "Contra el problema imprevisto: una paloma blanca, una gallina blanca y dinero.", "Para la casa o la finca: un saco de cáscaras de maíz y cuatro palomas, llevados a un huerto junto al agua."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà rescata a Ògún, Ṣànpọ̀nná, Ṣàngó y Òòṣà del vientre de Elénìní. Eléwì Odò."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Àmàlà, oyóyó (hoja de sopa), rabo de caballo (ìrùkẹ̀), tela de cintura, paloma blanca, gallina blanca., cáscaras de maíz."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 216.1 (yorùbá): Ìrẹtẹ̀'Rosù: / a dífá f’Ọlọ́fin / Wọ̀n niki Ọlofin wa rúbo / ki òràn gẹdẹgbẹ ma de. / Eyẹlé funfun, adiyẹ funfun / ati egbejila owó li ebo.", "REZO: IRETE LAZO ADIFAFUN OBA IKU INLE ARERE OGGUN AREBE OBA EGGUN LESE IGI OBA TELE OMO EGUN LODAFUN ORUNMILA, MAFEREFUN EGUNGUN.", "REZO: IRETE ROSO AWO PAPA ORRORU AWO OFA AIRU OPA AITA OFAILLA OFA TONTONI ADIFAFUN APOTON SHE BABA OTURA AKUKO LEBO OFALLERO. ORUNMILA, KAFEREFUN SHANGO, YALORDE Y OMO.", "REZO: IRETE ROSO IFA ARBE KAGUOLLO Y PARA Y SUKO AWO BE ISHUNE LORO ENSHULUSHE IRBIN LODAFUN IBIN NOTE IFA IRE OTO LLIGUE GUO NI ALLA SU OWO GUO LLI KURO IBIN ORUBO AICORE EYELE FUN FUN EKU EYA EN ILE MOGUO. ORUNYERE APO OMI FOLOGU TETEROGUN MORGO OPO NI FOGULERE BA ARBO.", "REZO: OFUN YERE APO OMI FOLOGU TETEREGUN MOGUO EPO NI FOLIKI LELERE BAARBO. ORUNMILA KAFEREFUN SHANGO, YALORDE ATI OMO.", "REZO: TETEREGUN OFIRIBE MESA ADIFAFUN OBARA NIREGUN TINSHOMO AWO OLOFIN.", "SUYERE: OMO OBA TELE OMO OBA TELE OMO OBA TELE."]}]$q$::jsonb),
(217,'6342a6670c8efff61e3c00618794938e',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Ọ̀wọ́nrín pide ofrendar para conservar un puesto de honor y apagar a quienes conspiran. El consultante gana y sus oponentes pierden. Si hay una hija en edad de casarse, conviene darla a un sacerdote de Ifá; y quien pretende a una mujer debe ofrendar para asegurarla frente a otros pretendientes."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme perder un puesto o su buen nombre.", "Un rumor le da miedo de que lo calumnien (relato de Ọ̀rúnmìlà frente a los conspiradores).", "Quiere que un logro dure y busca una vida larga (relato de Temitayo).", "Hay pretendientes y una decisión de matrimonio en la familia (relato de Lépolátà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ganar frente a los oponentes.", "Un nombre que siempre se oye con honor.", "Asegurar a la pareja frente a otros pretendientes.", "Vida larga.", "Que las brujas no se atrevan a pelear."]}, {"titulo": "Ibi y advertencias", "puntos": ["Conspiraciones contra su honor.", "Confiar solo en la magia y no en la ofrenda.", "Peligros en el agua.", "Que lo que se hace en secreto salga a la luz y avergüence."]}, {"titulo": "Enseñanza principal", "texto": "Las medicinas sin ofrenda no mueven al cocodrilo. Todos llevamos nuestros pájaros en la bolsa: mejor descansar que pelear."}, {"titulo": "Relatos reunidos", "puntos": ["Lépolátà y el cocodrilo. Ọ̀rúnmìlà quería casarse con Lépolátà, pero también la querían Ajáágbọ̀n Nímú Oká, Àpànkoko Mòtièlè y Diidikúùdì Tíí Jẹ́ka Lọ́rùn Ẹfọ̀n, que eran curanderos y magos; Ọ̀rúnmìlà, al ver que sus compañeros se la disputaban, se quedó callado. Le habían pedido dos perros y aceite de palma: los sacerdotes tomaron uno y le dijeron que criara el otro. La madre de Lépolátà comerciaba aceite de palma, y la muchacha iba a buscar agua al lago. Un día un cocodrilo enorme salió a tomar aire, con una palmera crecida en el lomo; Lépolátà, sin sospechar, se subió encima, y el cocodrilo se fue nadando al centro del lago. Ella se agarró de la palmera y el cocodrilo no pudo hundirla ni atraparla. Sus padres la buscaron, la vieron en medio del lago y corrieron a llamar a los pretendientes. Cada uno cantó sus encantamientos y tendió sus medicinas, y el cocodrilo no se movió. Entonces Èṣù le dijo a Ọ̀rúnmìlà que atara al perro con una soga larga y lo echara al agua, porque los cocodrilos no dejan pasar un perro que se ahoga. Ọ̀rúnmìlà fue, cantó, y lanzó al perro; el cocodrilo nadó tras él, y Ọ̀rúnmìlà fue jalando la soga hacia la orilla hasta que, cerca de la tierra, Lépolátà saltó y se agarró de él. Así la ganó.", "Ọ̀rúnmìlà en Òtà y las palomas de la bolsa. Ọ̀rúnmìlà iba a ejercer en Òtà, la ciudad donde la guerra de las brujas tenía cautiva a la gente. Le pidieron cuatro palomas: los sacerdotes tomaron dos y le dijeron que escondiera las otras dos en su bolsa; ofreció además dinero a Èṣù. En Òtà vivían Pápákuru, Pàpàkuru y Papakúùrú, brujas que ponían a prueba a todo sacerdote que llegaba. Cuando se sentaron frente a él, las palomas empezaron a decir desde la bolsa: mataré a Pápákuru, mataré a Pàpàkuru, mataré a Papakúùrú. Le preguntaron qué tenía en la bolsa, y Ọ̀rúnmìlà, apretándola, decía como si hablara con espíritus: por favor, no peleen todavía. A la tercera vez las brujas le rogaron: no venimos a pelear contigo; haz lo que quieras, nadie te lo impedirá. Por eso las palomas siguen diciendo lo mismo hasta hoy.", "El nombre de Ọ̀rúnmìlà. Ifá dijo que quien conspira contra Ọ̀rúnmìlà quedará avergonzado y nadie volverá a oír su nombre, pero que el de Ọ̀rúnmìlà siempre se oirá con honor en el mundo. Ofreció una carnera, una gallina de Guinea y dinero.", "Tẹ́mítáyọ̀ y la vida larga. El àgbẹ̀ reparte la fortuna en casa e Ìrẹtẹ̀ la agarra fuerte con las manos: así adivinaron para Tẹ́mítáyọ̀, y le pidieron una carnera, una paloma, hierba peperẹku y dinero para vivir mucho. Ofreció.", "La tortuga y la palmera que baila. Hubo una hambruna en la tierra y en el cielo. La tortuga, que había ofrecido dos palomas y dinero pero se guardó el gallo, buscó un truco para comer: se metió en una palmera hueca al borde del mercado y, cuando llegaba la gente, cantaba: la palmera baila, la palmera se tambalea, la palmera recorre el mercado. La gente, al ver una palmera caminando, huía, y la tortuga salía a recoger las mercancías y la comida. Así cada día de mercado. El rey mandó a Ògún, que al oír el canto huyó al monte; mandó a los cuatrocientos Òrìṣà, y tampoco pudieron. Èṣù se ató doscientas calabacitas de medicina y fue, pero también huyó, y se le cayeron todas menos dos. Entonces mandaron a Ọ̀sanyìn, que se sentó junto al fuego de las vendedoras de buñuelos con un hierro calentándose. Cuando la gente huyó, él se quedó sentado. La tortuga salió, quiso tomar un buñuelo, y Ọ̀sanyìn le apretó el hierro caliente en el cuerpo. La tortuga gritó y prometió que ella y el caracol serían esclavos de Ọ̀sanyìn; él aceptó solo a la tortuga. Desde entonces la tortuga se ofrece a Ọ̀sanyìn. Ifá pide ofrendar para que lo que se hace en secreto no salga a la luz."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la pareja: dos perros (uno para los sacerdotes y otro para criar) y aceite de palma.", "Contra las brujas: cuatro palomas (dos escondidas en la bolsa) y dinero para Èṣù.", "Para el honor: una carnera, una gallina de Guinea y dinero.", "Para vida larga: una carnera, una paloma, peperẹku y dinero.", "Para que lo secreto no salga: dos palomas, dinero y un gallo, completos."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù aconseja a Ọ̀rúnmìlà. Las brujas de Òtà. El cocodrilo del lago. Ọ̀sanyìn, dueño de las hojas, recibe la tortuga como ofrenda; Ògún, Èṣù y los cuatrocientos Òrìṣà no pudieron con su truco."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aceite de palma, peperẹku, palomas, soga larga., tortuga."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 217.1 (yorùbá): Ìrẹtẹ̀-Wọ̀nrín: / a difá fún Ọ̀rúnmìlà. / Wọ̀n ni: / Gbogbo àwọn ti nba Ọ̀rúnmìlà / s'ọ̀tá ti wọn npegan rẹ̀ li oju yoo ti, / a ki yoo gb'oruko wọ̀n (nibi iyi) rara. / Bẹẹni a konii ye gbọ oruką Ọ̀rúnmìlà / t'ounti ọla ninu ayé. / Agutàn, eyẹ etu, egberindilógún owó li ebo. / Ó gbọ̀ ó rú.", "Verso 217.2 (yorùbá): \"Agbe ngbe Ire wa'le, / Ìrẹtẹ̀ ntẹ wọn m'ọwọ\": / a difá fún Temitayo / wọ̀n niki Temitayo wa rúbọ, / ajepẹ aye. / Ẹbọ: Àgùtàn, eyẹlé, pẹpẹrẹku, / ati ẹgbaá méjilélógún owó. / Ó rúbọ.", "REZO: IRETE JUANI ODUIBIRI BIRI FOBO IMBORI. ADIFAFUN ORUNMILA OBARABANIREGUN IRI WAMKA WIN WIN OZAIN YORO YORO.", "REZO: IRETE JUANI IRETE WAN WAN AWO AWO BURE OMAYUYE KIFUN AWA KEUMBO IFA MAGAYI IFA AWO MOLEÑO MOLABO KIFUN AWO KE UMBO AWA DIDE IFA ARIBAWA ONI AWO BOGBO MI NI LODE IFUN MOWE KAWO.", "SUYERE: AWABO AWATO ONIRE LAMIWE AWADO AWATO ONIRE LAMIWE", "REZO: IFA ARIBAWA ONI AWO BOBOMI NILODE IFUN MOWE NAWO.", "REZO: ALADI KOSO INLE KANA ARABO ADIFAFUN ABI AUN AYAPA TIOMARA AWO ONA, OYA TOKU, WONIKI ORUGBO KI AWO IRE MABA MAYELE ELORI EYELE MEYI LEBO AKUKO LEBO AWO IRE EYA ABI AUN ERU EYELE MEYI OMOLORUN OWADA OBONI KAN OMU ARA. OLOSI ETIGUON ARA OYA ASIYA ODE KURO NINU IYO OPE OBERESIKO OZAIN ERU OJUN YIYE BAYI NI AUN MONISHE NI OYO ESHU DA OJUN OTU WALOYA UMBATI OZAIN MOLU OBABARA, INA AKARA BI OSITINA OWO OZAIN NI AUN OKANI OMU ONKONU IGBIN PELU. ATI OYO NANI ATI MAFIN AUN EBBO OZAIN TITI ODI ORIYI EBBO ODARA.", "REZO: IRETE WAN WAN INLE OROMUN OYUZ OZAIN YORO YORO OKU."]}]$q$::jsonb),
(218,'7815e529681d9667a6e75ed567c1e165',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Ọ̀bàrà enseña a dominar las dificultades con las medicinas de Ifá. Hay que cuidarse de estafadores y embaucadores,. La persona viajará y volverá bien aunque otros la den por perdida. Sus cosas se endulzarán."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme una estafa o un engaño.", "Lo presionan para abandonar un ideal.", "Quiere salir de sus problemas sin traicionar sus valores (relato de Ọ̀rúnmìlà Alade).", "Pasa por un cambio y otros creen que ya desapareció (relato del halcón que muda sus plumas)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Volver de un viaje renovado.", "Victoria sobre los enemigos.", "Que las cosas se endulcen.", "Buen carácter y buena fortuna."]}, {"titulo": "Ibi y advertencias", "puntos": ["Estafadores y timadores.", "Gente que desea que no regrese."]}, {"titulo": "Enseñanza principal", "texto": "Nadie está fuera de las reglas del rey, y nadie es más rápido que el tẹ̀tẹ̀. El que se ausenta para cambiar de plumas no se ha perdido: vuelve nuevo."}, {"titulo": "Relatos reunidos", "puntos": ["El halcón que cambió sus plumas. El halcón había usado y usado su ropa, y se fue a cambiarla. Los demás notaron su ausencia y dijeron que se había perdido sin dejar rastro; no sabían que solo había ido a mudar. Había ofrecido antes de irse. Llegó al lugar de la muda, se quitó las plumas del año anterior, las tiró al suelo, tomó plumas nuevas y volvió a casa bailando. El pájaro no se pierde: vuelve a su casa.", "Ọ̀rúnmìlà y la miel. Ọ̀rúnmìlà empezó a hacer cosas que endulzaban el mundo y preguntó si sus cosas serían dulces. Le dijeron que sí, y le pidieron una botella llena de miel y dinero. Ofreció a todos los que debía, sus cosas se endulzaron y cantaba: mi deseo ya llegó.", "Ọ̀rúnmìlà Aládé rodeado de enemigos. A Ọ̀rúnmìlà Aládé, rodeado de enemigos, le aseguraron la victoria si ofrecía un chivo y dinero. Ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para el viaje: la ofrenda marcada.", "Para la dulzura: una botella de miel y dinero.", "Contra los enemigos: un chivo y dinero.", "Medicina de carácter y fortuna: hojas de tẹ̀tẹ̀ àtètèdáyé cocidas en sopa con pescado aro y hojas machacadas de wọ̀rọ̀; ya fría, se le añade iyẹ̀ ìròsùn marcado con el Odù y rezado."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà Aládé, príncipe. Ifá cuida al que viaja."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tẹ̀tẹ̀ àtètèdáyé (Amaranthus viridis), wọ̀rọ̀, iyèrè (Piper guineense), pescado aro, miel."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 218.1 (yorùbá): Kos'ẹniti apa Ọba ko ka, / Kos'ẹniti tẹ̀tẹ̀ ko le tẹ: / a daa fún Ọ̀rúnmìlà Alade / nbẹ laarin ọ̀tá. / Wọ̀n niki o rúbọ a ṣẹ wọn. / Ẹbọ: Obúkọ kan / ati egbẹ̀tàlélọ̀gbọ̀n owó. / Ó gbọ̀ ó rú.", "Verso 218.2 (yorùbá): Aṣejejeṣayé, / Aṣejejeṣayé, / Aṣejejẹsayé, / Warawaramaṣe, / Warawaramaṣe, / Warawaramaṣe, / Ìrẹtẹ̀-Ọ̀bàrà kiomu ire / Uwa ba ewé Ifa.", "REZO: IRETE OBA BIYE TELEWELE WELE AWO ABALODE ADIFAFUN OSHA OGU NINA TINLOSILE KI TI OLO BINU WERE WERE.", "REZO: IRETE OBA BIYE LODAFUN ORUNMILA, YALORDE ATI OBINI. AKUKO, OWUNKO LEBO INTORI IKU, INTORI ARUN AFIE LEBO MAFEREFUN SHANGO, MAFEREFUN OYA.", "REZO: IYENKO ILEMBE OTRA EÑILA OMA ADIFAFUN ASHORUN AKOKO UMBATOLO ROGUN DODO AUKO LEBO IBI AMNERE NIADOYUKO ADIFAFUN AKORIMA BATI FONRO ON ESHERI ADIE LEBO INTORI ARUN INTORI IKU. MAFEREFUN SHANGO, LODAFUN OYA.", "REZO: IFA IRETE LORDA BIYE. LODAFUN ORUNMILA, YALORDE OTI OBINI, IRETE BABA IFA ILENKO ILEMBRE ORA EÑI ORDAFUN AKUKO OWUNKO LEBO EWEFA OSHE (CARPINTERO) ELERE ES CUARTO. IRE AYE ATEGUAGUN AUN LO ORUNMILA FA EYEBA (DELE SANGRE A IFA).", "REZO: IFA IRETE LORBA BIYE LODAFUN ORUNMILA, YALORDE ATI OBINI. MAFEREFUN SHANGO, LODAFUN OYA.", "REZO: YEYE KALULU, YEYE EUERE, KALUKU YEYE, OMOTA OMOTA QUIBIOCO ERU, BAN BOIO, YANYAN IROKO YANYAN."]}]$q$::jsonb),
(219,'e5188f3c55d0cadfa0cf6965e9346ea3',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Ọ̀kànràn pide prudencia ante una conspiración de colegas o gente del mismo oficio que quiere dañarlo o quitarle sus medios de trabajo. Ganará aunque parezca arriesgado, pero debe ofrendar. Desea buena pareja: el marido no debe maltratar a la esposa ni ella faltarle a él."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se siente amenazado por compañeros de trabajo (relato de los adivinos que planean envenenar a Ọ̀rúnmìlà).", "No sabe en quién confiar dentro de su oficio.", "Una invitación o un encuentro pide prudencia.", "Un grupo está preocupado por el bienestar de quien lo dirige."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Escapar de una trampa preparada por colegas.", "Salir sin culpa de lo que hace.", "Buena esposa e hijos.", "Una casa junto al río."]}, {"titulo": "Ibi y advertencias", "puntos": ["Envenenamiento o traición en un banquete.", "Competencia desleal en el trabajo.", "Maltrato en la pareja."]}, {"titulo": "Enseñanza principal", "texto": "No todo lo que se sirve se bebe: el que mira la copa con calma ve lo que hierve dentro. Quien está demasiado ocupado con su cosecha pierde lo que descuida."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà y el veneno en casa de Ọlọ́fin. Los adivinos se reunieron en casa de Ọlọ́fin y, de acuerdo con él, prepararon veneno para matar a Ọ̀rúnmìlà cuando llegara. A Ọ̀rúnmìlà le pidieron que ayunara ese día y ofreciera dinero y aceite de palma. Lo invitaron al banquete y le sirvieron vino de palma; él miró la copa largo rato y dijo: ¿qué hierve en este recipiente? Veneno es lo que hierve; Ìrẹtẹ̀ Ọ̀kànràn me dijo que hoy no bebiera. Le trajeron vino de bambú y dijo lo mismo. Después Ọlọ́fin consultó por su hijo mayor, que estaba enfermo; todos dijeron que no moriría, pero Ọ̀rúnmìlà dijo que moriría si Ọlọ́fin no entregaba su vestidura real y la estera de su trono para hacer una medicina. Ọlọ́fin creyó tener la oportunidad y mandó poner veneno en la ropa y la estera. Mientras las dejaban afuera, un pájaro empezó a cantar con insistencia: Ọ̀rúnmìlà, no te sientes hoy en la estera, no te pongas esa ropa, siéntate sobre ìfin. Cuando trajeron la ropa y la estera, Ọ̀rúnmìlà pidió que ellos se vistieran y se sentaran; lo hicieron y quedaron envenenados. Ọ̀rúnmìlà salió de allí sin daño.", "Ọ̀rúnmìlà y la esposa del campesino. Ọ̀rúnmìlà preguntó si tendría esposa, y le dijeron que sí, que ofrendara. Vio a la prometida de un campesino y se acercó. El campesino sembraba quimbombó: un día tocaba cosechar el quimbombó, al otro vender las hojas, al otro las berenjenas, y antes tenía que sacar el ñame y hacer harina. Nunca tenía tiempo para atender a su novia, y al final dijo: que se vaya. Ọ̀rúnmìlà se la llevó sin culpa. Keere kéèré keere, el campesino no tuvo tiempo para su esposa.", "Àgbọngbọ̀n y Lánrète. Àgbọngbọ̀n consultó, ofreció completo y se casó con Lánrète. Ella empezó a tener hijos y los dos vivieron contentos. Ifá dice que construirán su casa cerca de un río, en tierra arcillosa, y que se buscan uno al otro: viajamos lejos, pero volvemos a la casa de Lánrète.", "La tortuga y el tambor del leopardo. Brote de hoja, el adivino de la punta de la berenjena, adivinó para los ciento sesenta y cinco animales el día en que la tortuga iba a robar el tambor del leopardo, y les pidió a todos una brocheta de ratas y dinero para no toparse ese año con un buscapleitos. Todos ofrecieron. Poco después el Rey del Cielo los invitó a una fiesta con sus tambores. Todos les pusieron cuero nuevo; la tortuga no encontró cuero, y en el camino halló el tambor del leopardo, que lo había dejado mientras iba a lavarse al río. Se lo robó y lo tocó ante el Rey del Cielo; sonaba mejor que todos y los demás se preguntaban de dónde lo había sacado. El leopardo, después de buscarlo mucho, esperó a los animales en el camino de regreso y cantó: el rey fijó el día de la fiesta; fui al río a lavarme, volví rápido y se llevaron mi tambor; toca el tuyo para que lo reconozca. Pasó el elefante, tocó, y el leopardo le dijo: ese no es mi tambor, sigue. Así pasaron todos, hasta que llegó la tortuga con el tambor colgado del cuello. El leopardo la agarró, la golpeó y la arañó con sus garras; cuando iba a estrellarla contra el suelo, la tortuga se le resbaló y escapó al monte. Las marcas de las garras del leopardo se le ven en el caparazón hasta hoy. Ifá advierte que un muchacho bajito y rojizo puede traer a casa algo malo que obligue a jurar; él y la gente que lo rodea deben ofrendar para no toparse con un buscapleitos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra el veneno: ayunar ese día; dinero y aceite de palma.", "Para la pareja: la ofrenda que marque Ifá, completa.", "Contra el buscapleitos: una brocheta de ratas y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ọlọ́fin y los adivinos conspiradores. Un pájaro avisa a Ọ̀rúnmìlà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Aceite de palma, ìfin (estera de palma), quimbombó, berenjenas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 219.1 (yorùbá): Ìrẹtẹ̀-Ọ̀kànràn: / li a da fún Ọ̀rúnmìlà / nijo ti gbogbo awo pejo sile Ọlpfin / nṣ'oro silẹ dee; / wọ̀n niki o gbaawe sulẹ loni / ki aṣubi orolelẹtan fún un loni. / Wọ̀n niki o rúbọ. / Egberindilógún owó ati epo. / Ô gbọ̀ ó rú.", "REZO: IRETE KANA BERIN GBAGBBOGUN GBAGBISAN IRUN GBOGBO LAODO LUERE AKUERE LORUGBO.", "REZO: IRETE KANA IBILOBAN AKUTANLA MORA OMORU KOKO TIMILA SHAWOKI ADIFAFUN LABUDO TINSHOMA ENÑI OBA IMI KI LOKU DODU LEBO; ABOADI AGUNDI ADIFAFUN AMILETE AKUKO LEBO. OWO, AKUKO, EYELE LEBO.", "REZO: IRETE KANA KANLU OMOPONE NIBATI IRETE KANLU OMO OLOFIN ARA ALA OMO PENCIBILE IRETE KANLU ESHIRIN OLOFIN ARA ALA OMPEN NIBATI IRETE KANLU ARA OLOFIN ILE AKUKO LEBO AIKORDIE HILO NEGRO OWO LA MEYO.", "REZO: IRETE KANA OBIRE KOLOBO MOLUBA AGUARA YANIYA OBARIKUPO OMOLUBO MATA LABA PASI META BABA MASI ASHISHE OLARA OTOSHI NIYEKAN ERANI BIBE ONI YANIYA LODAFUN BAÑARSE.", "SUYERE: OLOBOSHE BIRELE OLOBOSHE BIRELE IRUN LAFIKAYO WALE IRUN.", "REZO: IRETE KANA KANLU OMOPEN NIBATI IRETE KANLU OMO OLOFIN ARA ALA OMO PENSIBELE IRETE KANLU ESHIRIN OLOFIN ILE AKUKO LEBO.", "REZO: KANLU OMEPEN NIBATI IRETE KALU OMO OLOFIN ARA ALA OYO PENSIBELE IRETE KANLU EKAIBIE OLOFIN.", "REZO: IBELEBAN AGUTANLA MESA OMO OMI COCO TIMELAS CHQUE QUE ADIFAFUN LABUDU TIMBONA ORUNMILA EMI EBA BECA ERI JUILECU, ADIFAFUN OMILETE."]}]$q$::jsonb),
(220,'a372778daf9588b20c51be9e46ac6cbd',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Ògúndá habla de la necesidad de que el consultante se inicie: el desarrollo espiritual es necesario para su paz y prosperidad. Si vive lejos de su tierra, debe quedarse donde está: en tres años llevará fortuna a casa. Advierte no esconder a las deidades y a las àjẹ́ la parte que les corresponde."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Busca crecer espiritualmente (relato de Pèrègún).", "Un problema que lleva mucho tiempo exige disciplina.", "El trabajo no da frutos y espera una mejora (relato de Ọ̀rúnmìlà).", "Piensa buscar fortuna fuera de su lugar de origen."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Alivio y comodidad por la iniciación.", "Un año de buena fortuna.", "Riqueza fácil al quedarse con sus cosas lejos de casa."]}, {"titulo": "Ibi y advertencias", "puntos": ["Comerse solo lo que se gana sin dar su parte a los poderes.", "Asustar a quienes se reúnen de noche.", "Ir y venir a casa sin cuidar sus cosas."]}, {"titulo": "Enseñanza principal", "texto": "La colina de aquí no deja ver la de allá. El que va a casa todos los días no junta riqueza: el que se queda con sus cosas termina recogiendo dinero como maíz."}, {"titulo": "Relatos reunidos", "puntos": ["Pèrègún y el tẹ̀tẹ̀. El tẹ̀tẹ̀ dobla el cuerpo para sentir alivio: así adivinaron para Pèrègún, y le pidieron plátanos maduros, manteca de cacao y dinero para hallar alivio iniciándose en Ifá. Ofreció, se inició, y el adivino dijo: Pèrègún estará cómodo para siempre.", "La gente de Ìrẹtẹ̀ a pé lóko. La gente de Ìrẹtẹ̀ a pé lóko lloraba por riqueza. El sacerdote se sorprendió: ¿por qué van a casa todos los días? Quien ha de tener riqueza no viaja a casa cada día, se queda con sus cosas. Les pidieron palomas y maíz, y que sembraran maíz. Al final del tercer año volvieron a casa con mucho dinero, y la gente decía: miren a los de Ìrẹtẹ̀ a pé lóko, recogen dinero como si recogieran maíz.", "Gbálẹ̀ y sus tres hijos cazadores. Gbálẹ̀, la Tierra, tuvo tres hijos: Kútánlé con Ògún, Òléngbà con Ìja y Tẹ̀tẹ̀rẹ̀gún con Ọ̀rúnmìlà. Los tres decidieron cazar juntos y Ọ̀rúnmìlà les pidió ofrendar, porque matarían a Àgbọ̀nrín Gàgàlà, el gran antílope. En el monte lo mataron y lo envolvieron con la tela de la esposa de uno de ellos. Esa noche Èṣù, Ọ̀rúnmìlà y las Ìyàmi se reunían en la encrucijada, y los cazadores, para no tener que darles parte de la carne, gritaron: ¡viene Òrò, el que ni las deidades pueden ver! Todos huyeron, pero Èṣù se escondió a mirar y vio que por un agujero de la tela salía la pata del antílope. Dijeron: si los tres se comen esa carne sin darnos nada, morirán. Kútánlé comió su parte sin dar a nadie y murió antes del anochecer; Òléngbà murió al amanecer. Gbálẹ̀ corrió a ver a Ọ̀rúnmìlà, que explicó que habían ofendido a las Ìyàmi. Sin esperar más, Gbálẹ̀ tomó la carne que le quedaba a Tẹ̀tẹ̀rẹ̀gún, le echó aceite de palma y la puso en la encrucijada. Las Ìyàmi la encontraron y dijeron: si lo hubieran hecho antes, no habrían muerto. Ògún acusó a Ọ̀rúnmìlà de haber revelado el secreto; Ọ̀rúnmìlà dijo que preguntaran a la madre, y Gbálẹ̀ respondió: ¿iba a quedarme de brazos cruzados mientras mataban a todos mis hijos? Entonces decidieron que no volvería a hablar y le cortaron la cabeza. Por eso la Tierra, que antes contaba todo lo que oía, ya no habla, y en su vientre entramos todos. Solo Tẹ̀tẹ̀rẹ̀gún, que ofreció, quedó vivo.", "Alade en la pobreza. La buena fortuna viene a mis manos: así adivinaron para Ọ̀rúnmìlà Aládé cuando estaba en la pobreza, y le dijeron que se acercaba un año de buena fortuna. Le pidieron una paloma, una gallina, camarones y dinero. Ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la iniciación: plátanos maduros, manteca de cacao y dinero.", "Para la riqueza: palomas y maíz; regar maíz para los animales y las aves.", "Para no ofender a las Ìyàmi: carne con aceite de palma en la encrucijada; si la esposa tiene una tela rota, ofrecerla.", "Para el año de fortuna: una paloma, una gallina, camarones y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Las Ìyàmi, Èṣù y Ọ̀rúnmìlà se reúnen en la encrucijada. Gbálẹ̀, la Tierra, madre de todos. Ògún e Ìja."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tẹ̀tẹ̀ (Amaranthus hybridus), plátanos maduros, manteca de cacao, maíz, camarones, aceite de palma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 220.1 (yorùbá): tẹ̀tẹ̀ wa tẹ k'ara o rọ wọn: / a difá fún Pèrègún, / Wọn niki Pèrègún wa rúbo / ki ara le rọọ kiowa tẹ Ifá. / Ebọ: Ọgèdè weerẹ tiopọ̀n, òri, / egbejilélógún owó. / Ó gbọ̀ ó rú. / O tẹ Ifa. / Wọ̀n ni: / \"Ara yoo rọ Pèrègún titi-aiyé: / ara rọ Pèrègún\"", "Verso 220.2 (yorùbá): Ire-tẹ̀-mi-lọwọ̀: / a daa fún Ọ̀rúnmìlà / Alade nbe laarin ipónjú, / wọn niki o rúbọ, / odún orọ de. / Ebọ: Ẹyẹlé, Adiyẹ, ede / ati egbẹwá owó. / Ó gbọ̀ ó rú.", "REZO: IRETE KUTAN ORI MIRI OTA KUTAN IYANA KIYANA ADIFAFUN ELERIPIN OUMBO EYELE FUN FUN, ASHO FUN FUN, EKU, AKUKO, EWE, OSHE AWO ITA KUTU IY KIY ORUNMILA ADIFAFUN ELERIPIN.", "REZO: IRETE KUTAN, KUTAN OBA AIYE, ORISHA BI KOLE ORUN OFE LEITOSHO ORISHAYE ILE ASHUP AWO UMBO BOGBO ORISHA IS LAIYE, KOLE AIYE OBA BOGBO TENUNYEN ELEBO MERINDILOGIN.", "REZO: IRETE GUEDA ISHU ABASABILE UN FETETELE PEKUE AWADO OBO SABILE UN FALETELE PEKUE OKU ABASA LORI NI UMBATE TELEAPERI OKUN ADA YOKO KUTANTE ADAFUN AYAMI COBIERU TICHO OMO EKO, EÑI BOGBO ELLE LORUGBO ISHU MEYI OBI MOTIWAO E OKAN EKU EYA EPO OWO MENI OWO.", "REZO: KITA KITA Y YAMA KI YANA ADIFAFUN ORUNMILA TINSHE ELERIKUIN ORUGBO ABEBOARDIE MEYI AKORDIE ELEDARE NIMBAO OWO EKU OBI MEYI EKU EWE ETU.", "REZO: HOUN BANIKU NISHE CAYO OFO LO HOUN IRENIFA NI MOFA ADIFAFUN EBASI ESI LEBO EYELE AKUKO EBEFA OWO.", "REZO: ITA KUTA IYAKI EYA ADIFAFUN ORUNMILA BATINSHE ALERIO KIN ABEBOARDIE LEBO ELEDA EKOLA ORI ORIE.", "REZO: IRETE KUTAN MAFEREFUN YALORDE TAKUTA YANIKI OGGUN OSHOSI LORDAFUN ORUNMILA KINSHE ELERIPIN.", "REZO: IRETE GUEDA IFA FUKUNDA NUFERO DIYENI IKU NUKOYE AYORO TINYENI OR DIFAYOKO CON KUNTALE OLUOFUN HAYA MI KOBERU ORDAFUN TETE TOGUN TISHOMO IKOÑI WO AIKORDIE ABEBOARDIE ISHEGUN OPOLOPO OWO ABOLEBO.", "REZO: KITA KITA AYANA LORDAFUN ORUNMILA UMBATI SHAWO ILE OLOFIN EURE ADIE AIKORDIE OWO MEYI.", "REZO: IRETE KUTAN IFA ONI ELEGDA SE EYELE MEYI LEGBO OTI EKRU ORUGBO TAN OFILE LAWO EKRU ORUGBO TAN OFILE LAWO EKRU OTI EYELE KOFIBORI.", "SUYERE: TANI DILOGUN SORO OLORUN AWA FUMI OBI SOROWA MERINDILOGUN IGE IKU.", "SUYERE: KOLE ODU MOWA LEMO DILOGUN SORO. OKO BI AYE ORISHAOKO AFEFE IKU OKO BI AYE OMOLARA.", "REZO: IRETE KUTAN IYA ADIFAFUN ARAINA ADIFAFUN EWA INLE KOLEPO OMO ODDUN OMO ODUA OMO ORUN. ADIFAFUN OLOFIN MAFEREFUN YALORDE, LORDAFUN ORUNMILA, OSHOSI.", "REZO: IRETE KUTAN AYABOMI NISHE KAYO OFO LO IRENIFA IRE NIFA NIMOFA OBATALA ADIFAFUN ABODA OBATALA OMOBINI AYA TUFO BADO AYA KOYO ERUBISI OSI BI ADERE NIFA EMI SHEKE OYO TOBA TOBI ATOYU AYA BI ONI OPOGUN BE OLEKE KOHIYE ORI, LODAFUN ELEGBA KAFEREFUN ORUNMILA.", "REZO: IRETE KERDA IFA FAKUA DANFORO DIYENI IKU OSHA OFIN ORUKORE AYARO TINYENI ADI FAYOKO KUTAMBE OLOFIN IBAYEN BAYEN TONU OPOLOPO ELERI EGUN LORDAFUN ORUNMILA ILE OLOFIN UMBO WASIYE ORISHA EGUN IRETE KUTAN IFA AWO ITA OKUTA LOBI", "ORISHA AYANA KIYONA ADIFAFUN ORUNMILA OBATO INSHE ELERI PIBIN IFA OMI BOGBO ELEDA.", "REZO: ISTA KUTAN AYANA KUYASA ADIFAFUN OLOFIN ADIFAFUN ORUNMILA UN BOTOSHE ELERIN KUIN EBO OLORUN IRETE KUTAN ADIFAFUN IYA BANSHE AGBA LOBIN TETEREGUN NOGUN IRETE KUTAN ADIFAFUN OLOFIN ADIFAFUN ILE DUN DUN INGUI IGUI.", "REZO: IRETE KUTANIE BURUKU NISHEYE OMO IYANZAN OYA LADEO AYO OTA FAFEYE BURUKU ELEGBA OTA BURUKUSI OLUO ONIRE OBATALA ONIFA MIMORA OFALOPO KUTAN NISHE ESE IGUI AWO LASHEYE EGGUN INLE YEWA OKOTO LAYENA INSHE INLE BURUKU YALE ASHEGUN OTA ESE OBATALA ELEGBARA KUBORO ESHISHI WABURUYELE ELEGBA BABAWOYE ISAMINOYE OSHEIBOYE EGUN OSHA OBATALA LA SOLODO ESHUBAO FUANIYE ELEGBA AKIBEYO IKAN KIKIAYE LODAFUN ORUNMILA."]}]$q$::jsonb),
(221,'218b65c8b98911a84e0329ac2f7509bc',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Ọ̀sá dice que prevenir es mejor que curar. El consultante puede tener competencia en el amor. Una o dos bendiciones vienen en camino, pero el exceso de alegría puede hacerlas pasar de largo. Ifá lo salva del castigo si es devoto de Òòṣà, y pide ofrendas a la madre en apuros."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Hay competencia en el amor o en la comunidad.", "Un pleito puede crecer si no planea cómo responder (relato de Adurojà-Abayako).", "Teme parecer cobarde por tomar precauciones.", "Se siente atrapado y busca una salida (relato de las ranas en la zanja).", "Desea hijos (relato de Osúnláyà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Dos bendiciones que se acercan.", "Vencer a los enemigos.", "Hijos para la mujer que los pide.", "Ser rescatado de un pozo sin salida."]}, {"titulo": "Ibi y advertencias", "puntos": ["Demasiada alegría que hace perder lo que viene.", "Prometer lo que no se puede cumplir.", "Endeudarse y perder a la madre.", "Beber lo que el enemigo deja en el camino."]}, {"titulo": "Enseñanza principal", "texto": "Demasiada alegría le rompió las piernas a la rana. Quien protege contra los motines no es cobarde. Lo que se promete a Òòṣà en apuros se cumple."}, {"titulo": "Relatos reunidos", "puntos": ["Las ranas y Òòṣà. Las ranas cayeron en una zanja muy profunda que el hombre había cavado para juntar agua, y no encontraban salida. Òòṣà iba de Ìrànjé ilé a Ìrànjé oko a buscar un elefante, con pasos tan largos que uno solo equivale a ochocientos años de camino para un hombre. Pasó por encima del pozo y las ranas le gritaron que las salvara. Él dijo que no podía detenerse porque buscaba un elefante. Las ranas respondieron: ¿un elefante nada más? Te traemos los que quieras en un momento, pero sácanos de aquí. Òòṣà sacó su calabaza de medicina y apuntó al cielo; las nubes se cargaron, llovió tanto que el pozo se llenó y las ranas salieron. Cuando Òòṣà les reclamó el elefante, se encogieron de hombros: ¿crees que podemos atrapar un elefante? No somos tan fuertes, pero te cantaremos cada año. Por eso las ranas cantan cuando llueve, en la época de sembrar el melón. Ifá dice que salvará a esta persona del castigo si es devota de Òòṣà, aunque le prometa más de lo que pueda cumplir.", "La rana que iba a ser rey. La rana, hija del rey de Ọ̀yọ́, iba a ser coronada al día siguiente. Le pidieron cuatro palomas, dinero y una tela roja con rayas claras para que el exceso de alegría no la matara, y se negó. Al saber la noticia, mandó a su esposa a comprar todo el vino de palma que hubiera y a llamar a su tamborero. Se ató medicina para viajar al instante y le dijo al tamborero que, antes de ser rey, quería visitar a todos los reyes. Tocaban el tambor y aparecían en Ìbàdàn, en Ọ̀yọ́, en Iléṣà, sin esperar siquiera la kola de bienvenida. Al volver de Iléṣà la medicina se gastó y la dejó caer en la copa de una ceiba, de donde no podía bajar. Su familia vino a buscarla y cortó el árbol con hachas; al caer, la rana se rompió las dos piernas y los dos brazos. Al amanecer, como no llegaba, coronaron a otro. Desde entonces se dice: demasiada alegría le rompió las piernas a la rana. Ifá pide ofrendar para que la bendición no pase de largo por exceso de alegría.", "La rana en la palmera. A la rana, hija del rey de Ọ̀yọ́, le dijeron que dos bendiciones venían hacia ella y le pidieron un chivo, una tela roja con rayas claras y dinero para que las dos le llegaran. Dijo que ofrendaría cuando las viera, y no atendió a Èṣù. Su esposa, que no había podido concebir, quedó embarazada y la rana se puso muy contenta. El día del parto, la rana estaba en su finca y le avisaron del nacimiento; feliz, quiso sacar vino de palma antes de volver. Estando en lo alto de la palmera llegó otro mensajero: el rey había muerto y querían coronarla. De la alegría olvidó dónde estaba, cayó y se rompió las piernas y los brazos. No pudieron curarla y dieron el título a otro. Desde entonces se dice: demasiada alegría le rompió las piernas a la rana. Ifá pide ofrendar para no estar enfermo cuando llegue la buena noticia.", "La rana que llamó la lluvia. A la rana le pidieron cuatro palomas, dinero y cuatro nueces de kola para que su madre no muriera ese año y para no endeudarse. No ofreció, y su madre murió. Yendo a visitar a sus parientes por el funeral, se encontró con los dieciséis jefes de Ifẹ̀ frente al palacio del Ọọ̀ni y presumió que, si querían lluvia, ella podía hacerla caer. El rey le mandó esclavos, cuentas, dinero y telas para que hiciera llover. La rana se asustó, corrió con los adivinos, hizo la ofrenda que antes había negado, y le dieron dos kolas para ofrecer a su madre. Ante la tumba de Àṣọ̀ró, su madre, rogó: madre, ayúdame, sácame de este apuro. Y la lluvia empezó a caer con fuerza. Ifá dice que la madre en el cielo ayuda a esta persona; si aún vive, se ofrece a su cabeza para que no muera ese año.", "La guerra entre el cielo y la tierra. Las abejas se fueron pero dejaron su panal; las hormigas se fueron y dejaron sus restos. La gente del cielo y la de la tierra estaban en guerra, y a ambas les pidieron una calabaza de miel y una de harina de maíz. Solo la gente del cielo ofreció. Cuando los de la tierra llegaron a la puerta del cielo, encontraron una calabaza de harina de maíz mezclada con miel y, sin saber que tenía veneno, bebieron, y todos los que bebieron murieron. La gente del cielo tocó a siete de los muertos con un palo y los mandó a cargar a sus compañeros lejos de la puerta, y cantaban burlándose: bebemos miel y no podemos pelear con la gente del cielo. Por eso hasta hoy la gente de la tierra carga a sus muertos de un lado a otro.", "Adúrójà Abáyàkọ́. A Adúrójà Abáyàkọ́ le pidieron un carnero, un gallo y dinero para vencer a sus enemigos. Ofreció y los venció.", "Ọ̀ṣúnláyà y sus hijos. Ọ̀ṣúnláyà, esposa de Àgbọ̀nnìrègún, lloraba por hijos. Le pidieron tela, dos gallinas, ratas y pescado, ofreció, y tuvo hijos: Dòṣùnmú, Jẹ́áyinfá, Amọ́ṣùn. El brote tierno de la palma, si la muerte no lo mata, llega a ser fruto maduro."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para ser rescatado: la ofrenda que marque Ifá y devoción a Òòṣà.", "Para que la bendición no pase de largo: cuatro palomas, dinero y una tela roja con rayas claras; o un chivo y la misma tela.", "Para la madre: cuatro palomas, dinero y cuatro nueces de kola; dos kolas se ofrecen a la madre.", "Contra la guerra: una calabaza de miel y una de harina de maíz.", "Contra los enemigos: un carnero, un gallo y dinero.", "Para hijos: tela, dos gallinas, ratas y pescado para Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Òòṣà rescata a las ranas. La madre difunta ayuda desde el cielo. Àgbọ̀nnìrègún y su esposa Ọ̀ṣúnláyà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Miel, harina de maíz, obì (kola), tela roja, ratas, pescado, melón."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 221.1 (yorùbá): Ar'otẹsakoṣ'ojo. / Oyin-ṣitan-f'afade'le, / Eerun ṣi tan f'agan de'le: / a difá fún Aráyé / a bu fún ará orun / nigba wọn ngbogun si ará wọn. / A niki kaluku wọn rú: / Akoto-oyin kookan / tounti akoto ẹko-fifo3za kookan. / Ará örun nikan li o rúbo, / Ará-ayé gbọ̀ wọn ko rú.", "Verso 221.2 (yorùbá): Ìrẹtẹ̀-Ọ̀sá: / a difa fún Aduroja-Abayako. / Wọ̀n ni kiowa rúbọ / kiobaa le ṣẹ'tẹ àwọn òtá rè. / Ebọ: Agbo kan, akukọ̀ adiyẹ kan ati egbaá mọ̀kàlá owó. / Ó gbọ̀ ó rú. / Wọ̀n ni: / Adurojà-Abayako, / a sẹ tẹ àwọn ọ̀tá rẹ̀.", "REZO: IRETE TOMUSA KERE AWO MOWAYE OMO SHANGO, OMO OYA AYENI IFA ONI BABALAWO OMO OBANYOKO BANYOKO IFA BANYOKO ORISHA BANYOKO YENYOKO YENI IFA YORO YERENI, MAFEREFUN SHANGO, MAFEREFUN ORUNMILA.", "REZO: IRETE TOMUSA KERE AWO MOWAYE OMO SHANGO, OMO OYA AYENI IFA ONI BABALAWO OMO OBANYOKO BANYOKO IFA BANYOKO ORISHA BANYOKO YENYOKO YENI IFA YORO YERENI, MAFEREFUN SHANGO, MAFEREFUN ORUNMILA.", "SUYERE: EMI ALAMO LOMI SHANGO BOGBO ARAYE OMO KELEKE EWE AYO, EWE AYO, EWE AYO.", "REZO: IRE NIFA KI IFA FORE AYE ADIFAFUN OSA NIFA NI KAFEREFUN OBANLA.", "REZO: IRETE ANSA IRE NIFA IFA FORE AYE ADIFAFUN YOKO OSHA. MAFEREFUN SHANGO LODAFUN IFA ABARABA NIREGUN.", "REZO: BALSA TIROPO TOLA ERU IFA PORI OLOFIN COMANSHE EBBO.", "REZO: OBIBE RORA FOKIO MARA FI ASHO KO IGI ADIFAFUN AKERE TIYODE ONISHINKO LEJIN OLA AYO ONILA NIKO IYAWO IRE KOLASHO FUN NIGBATI AYARE TO BABA NI ENU INODE NIKI ORADE KOSI LOPE LONILU ONDE ONDELU BAYE NO BERE SI SOGUN EGBE MO ARA ARETI MU OGGUN AKERE ,OILE ARAILE AWON YURETI AKERE FUTANSHE EPO LODAFUN ESHU.", "SUYERE: “LOLA LOLA LOLA AKERE AYE”.", "REZO: IRETE ANSA OSABEYIBE IFA SAWEYE IFA ADIFAFUN OMO LA OYA OYO YEWA YA KOLEKUN TERIBOON TENTONIKU ORUN AGADEBE FAYERE IKU ORUN AGADEBE FAYERE IKU OBANI SHANGO AWAYENIFA OLOFIN SHANGOMOWALONI NI OLOFIN ANO YOKA."]}]$q$::jsonb),
(222,'a164f74d74ffbcf68e32f0d17acc4ce2',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Ìká habla de lograr reputación y distinción por el propio trabajo y las propias habilidades. El consultante triunfará en una disputa o competencia por un puesto. Pide ofrendar por los hijos y contra los enemigos de la tierra, y ofrecer a Ògún contra el ladrón, que es alguien bajito."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Compite por un cargo o un ascenso.", "Su buena fama le está trayendo más trabajo (relato de Ọ̀rúnmìlà y las consultas de muchos lugares).", "Necesita mandar con habilidad y moderación (relato del rey de Benín).", "Alguien puede aprovecharse de lo que él cosechó (relato de la tortuga)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Mucho trabajo y reconocimiento.", "Capacidad de gobernar.", "Hijos protegidos.", "Atrapar al ladrón."]}, {"titulo": "Ibi y advertencias", "puntos": ["Tener hijos y no protegerlos de quienes los quieren comer.", "Un ladrón que roba y además asusta con su canto.", "Maldecir sin resolver."]}, {"titulo": "Enseñanza principal", "texto": "Tener hijos no basta: también hay que ofrendar para protegerlos de los enemigos. Ninguna maldición mata a la tortuga; el disparo, sí la hace hablar."}, {"titulo": "Relatos reunidos", "puntos": ["El quimbombó, la berenjena y la oruga. Àtèká, el sacerdote, adivinó para el quimbombó, para la berenjena y para la oruga peluda, que lloraban porque no tenían hijos. A los tres les pidieron ofrendar por los hijos y, además, contra los enemigos de la tierra. El quimbombó dijo: cuando tenga hijos, lo demás no importa; ofreció por los hijos pero no contra los enemigos. Tuvo hijos, y cuando crecen el hombre les corta la cabeza con cuchillo y los cocina en sopa. La berenjena hizo lo mismo: tuvo hijos, y cuando maduran los parten en dos y los cocinan con semillas de melón. Solo la oruga ofreció las dos cosas, incluidas ochocientas agujas, y Èṣù se las acomodó en el cuerpo: quien intenta tocarla a ella o a sus hijos se pica las manos. Hasta hoy nadie se atreve a cocinarla.", "La tortuga y el granjero Oníkàánjàngbọ̀n. Oníkàánjàngbọ̀n abrió un campo nuevo y sembró berenjenas, quimbombó y ñame. Un día antes de cada cosecha, la tortuga llegaba y se lo llevaba todo. El granjero empezaba a maldecir al ladrón, y la tortuga, escondida, cantaba: granjero, tú cosechas lo tuyo y yo lo mío; ¿por qué lo mío ha de volverse maldición? Ninguna maldición mata a la tortuga. El granjero, asustado, huyó a casa y fue con Ọ̀rúnmìlà, que le dijo que ofreciera a Ògún y pidiera a un cazador disparar tres tiros en el límite de la finca. Volvió, encontró todo cosechado otra vez, maldijo, y la tortuga volvió a cantar. Entonces el cazador disparó: al primer tiro dejó de cantar, y al tercero salió una voz pidiendo misericordia y prometiendo no hacerlo más. Salió con las manos en la cabeza, y así la atraparon.", "Ọ̀rúnmìlà, siempre llamado. A Ọ̀rúnmìlà le dijeron que siempre tendría mucho trabajo de adivinación y que lo llamarían de todas partes. Ofreció cuatro palomas y dinero.", "El rey de Benín. Al rey de Benín le dijeron que sería capaz y hábil para gobernar su país, y le pidieron una soga trenzada de trepar palmas y dinero. Ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para los hijos y contra los enemigos de la tierra: la ofrenda que marque Ifá, incluidas ochocientas agujas.", "Contra el ladrón: ofrenda a Ògún y tres disparos al aire en el límite de la propiedad.", "Para el trabajo: cuatro palomas y dinero.", "Para gobernar: una soga trenzada de trepar palmas y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù protege a la oruga con agujas. Ògún y el cazador atrapan al ladrón. El rey de Benín."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Quimbombó, berenjena, ñame, semillas de melón, agujas, soga de palmero."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 222.1 (yorùbá): Ìrẹtẹ̀-Ká: / a difá fún Ọ̀rúnmìlà. / Wọ̀n ni: \"Ọ̀rúnmìlà a maa r'awo ṣe, / kaakiri ni wọn yoo maa pee\". / Wọ̀n niki o wa rubọ: / Eyẹlé mẹrin, ẹgbàá mérin owó. / Ó gbọ̀ ó rú.", "Verso 222.2 (yorùbá): Ìrẹtẹ̀-Ká: / a dífá fún Olú-Ibini, / Agbà Ilẹṣi Adakẹtẹ-pempe pari akun. / Wọ̀n ni: \"Qwọ̀ Olú-Ibini a ka ilú rè\" / Wọ̀n niki o rúbọ: / 1gbà (tiafi ngun Ọpè), egbàá méjila owo. / Ó gbọ̀ ó rú. / Igbà: soga trenzada que se usa para trepar palmas y para amarrarse en su copa / quienes suben a cortar sus frutos.", "REZO: IRETE KA IFA MAFO GUOBO OMUNO ATEKA ADIFAFUN IL LODAFUN I MIRE IL KORUGBO.", "REZO: IRETE KA OM NI ATEKA ADIFAFUN INURE ADIFAFUN IL ATEKA LEBO EYELE, AKUKO LEBO.", "REZO: IFA MAFO WUOBO OMANI ATEKA ADIFAFUN ILA ATEKA ODAFUN OMIRE IFA NORUGBO. MAFEREFUN YALORDE, OBATALA, ATI ESHU.", "REZO: IRETE IKA IFA MAFO WUORO OMA NI TEKA ADIFAFUN ILA ATEKA LODAFUN UN OMIRE IFA LORUGBO. MAFEREFUN YALORDE OBATALA ATI ESHU."]}]$q$::jsonb),
(223,'71aed5aa5d1a2b3736a86537ef9671ad',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Òtúrúpọ̀n habla de obedecer a la autoridad y de ofrendar para tener muchos hijos. Las ideas del consultante deben tomarse en serio. Promete disfrutar de sus cosas si ofrece una tela brillante contra los enemigos de la tierra."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere que tomen en serio sus ideas.", "Pregunta por hijos (relato de Adán y Oode).", "Necesita un trato justo con una autoridad (relato de Ọbàtálá).", "Quiere dejar su propia huella (relato del grillo)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Muchos hijos.", "Disfrutar sus cosas sin que se dañen.", "Que sus órdenes sean obedecidas."]}, {"titulo": "Ibi y advertencias", "puntos": ["Enemigos que acechan lo que uno muestra.", "Desobediencia de quienes deben servir.", "No entender la ofrenda y burlarse del sacerdote."]}, {"titulo": "Enseñanza principal", "texto": "Lo que no se entiende se pregunta antes de burlarse: la carne de agìrìsasa es la rata, y el animal sin manos ni pies que camina sobre las piedras del río es el pez."}, {"titulo": "Relatos reunidos", "puntos": ["Ọmọlàgàn y la carne de agìrìsasa. Ọmọlàgàn, hija de la ciudad de Ṣàbẹ Òòpáárá, lloraba por hijos. Le dijeron que los tendría si ofrecía carne de agìrìsasa y la carne de un animal sin manos ni pies que camina fácil sobre los guijarros del agua. Ella se burló: ¿dónde se ha oído de cosas así para ofrendar? Nunca he oído de la carne de agìrìsasa ni de un animal sin manos ni pies que camine. El sacerdote le explicó: la rata gigante y la rata èmó son la carne de agìrìsasa, y el pez es el que no tiene manos ni pies y camina sobre las piedras del río. Que los comprara en el mercado y los ofreciera. Ọmọlàgàn ofreció, se olvidó de su angustia y tuvo tantos hijos que la casa se llenó.", "El grillo en el río. El grillo iba a hacer sus marcas frías sobre el agua del río. Ofreció y tuvo ropa y pudo hacer maravillas, pero no ofreció contra los enemigos de la tierra ni contra los detractores. Por eso, cuando su sombra se ve dentro del agua, los peces vienen a atraparlo. Aun así, sigue bailando sobre la superficie del agua.", "El murciélago y Òodè. Tendré un bebé para cargar a la espalda, tendré un bebé para jugar: así adivinaron para el murciélago y para Òodè, que querían muchos hijos. Les pidieron dos gallinas, dos cabras y dinero. Ofrecieron.", "Ọbàtálá y los cuatrocientos Irúnmọlẹ̀. La pitón vive en casa de sus padres con su veneno en la boca; la boa vive en casa de sus padres con su venganza. Así adivinaron para Ọbàtálá Ọṣẹ̀ẹ̀rẹ̀ Igbó, que iba a sentarse en un lugar para ser alimentado por los cuatrocientos Irúnmọlẹ̀. Le dijeron que si daba una orden a cualquiera de ellos y no era obedecida, los demás podrían quejarse juntos contra él. Le pidieron un gallo, dinero y medicina de Ifá. Ofreció."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para hijos: rata gigante, rata èmó y pescado.", "Contra los enemigos: una tela brillante propia.", "Para hijos: dos gallinas, dos cabras y dinero.", "Para ser obedecido: un gallo, dinero y medicina de Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Ọbàtálá Ọṣẹ̀ẹ̀rẹ̀ Igbó y los cuatrocientos Irúnmọlẹ̀. Èṣù."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ratas, pescado, tela brillante, màrìwò (hojas tiernas de palma)."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 223.1 (yorùbá): Emi a r'omogbepon, / Emi a r'omogbeṣere: / a dífá fún Àdán, / a bu fún Oode, / Wọ̀n niki wọ̀n wa rúbo, / kiwọn le bimo pupo sinu ayé. / Ẹbọ: Agbebo-adiyẹ Méjì, ewúrẹ Méjì, / egbàá mẹrindilógún owó. / Wọ̀n gbọ̀ wọ̀n rú.", "Verso 223.2 (yorùbá): Qka gbe ilé baba rẹ̀ ni oro tirẹ̀ lẹnu, / Ere gbe ilé baba rẹ̀ ni owun, / Ọlá ti a fifún Erin tikofiga ni owọ ijà rẹ̀ / fi gún gbọgbọrọgbọ. / Eyọ ma niti mariwo-ọ̀pe!: / a daa fún Ọbàtálá Qṣeerẹ̀-igbó / tiyoo joko sibikan / ti gbogbo Irúnmalẹ yoo / maa wa inkan sii l'ẹnu. / Ó ni: / Bi òun ba paṣẹ fún okan ti ko gbọ, / gbogbo àwọn egbẹ rẹ̀ / iyokun a dawojẹ baa wijo. / Wọ̀n niki o rú: / Akuko-adiyẹ, egbàáwa owó ati ewé Ifá. / Ó gbọ̀ ó rú.", "REZO: IRETE TRUPON GUELE AWO OBADE ADITA OUN OSHA OGUIRIN TIO LO GUIYATINLO BINI OM GUEGUERE EYELE LEBO, OWO LA MEFA TONTIEFA, EYELE, AKUKO LEBO.", "REZO: OYO EPO GUARE IRAYE AGUDERU ADIFAFUN AFIEMEKAN TELOLLOPA IBOUNOMADARA EURE TOBINA LEBO ATARE, 20 ALMENDRAS, PALOMAS, 20 EGUE EILU OSHOBITA OLLUORO EYELE AKUKO LEBO.", "REZO: ISHU ORASABILE UN FATE TELE PEGUE ORAGUAO, OBASILE UN FATETE PEGUE OKUABASA LORI NI UN FATELETE APENI OKUN ARDA FEYOKO KUTANLE ORDAFUN AYAMI KOBERU ORDAFUN TETEREKAN TINSHOMO OHIKORU.", "REZO: IRETE TRUPON OYU OPO GUESE GUSE ISALE ORDE GUERE ADIFAFUN AFIRMIKANTE LOLOLA IBOKUN OMADARA TINSHOMA AFI KURE TOBINA EBBO EYELE EGUE ASHIBATA OYOURO TETE GUELE.", "REZO: IFA NIRE AYE KAFEREFUN ORUNMILA, OBATALA ATI SHANGO.", "REZO: ALBA NI BIKU IKU SORU ERAN OMO Y ENKO OBA WA EKUN OZAIN OMO NI JORO JORO OBA YERI ODUDUWA OMO ERAN OSHISHE AWA NI ORUNMILA IKU ÑAÑARIKU Y EN BABA IKU OMO IKU OBARI BO OZAIN OMO IKU OM O IKU BABARI BO OZAIN OMO IKU OMO IKU JORO JORO OBA NIBISHI ESHISHI ERAN GUNGUN OMO IKU BASHE OZAIN IBASHE ODUDUWA."]}]$q$::jsonb),
(224,'655c0c0e6aef39d9e9be5862aed01462',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Òtúrá ofrece un encantamiento para apartar la muerte cercana y la enfermedad repentina. Promete hijos a quien insiste en buscarlos y pide a la esposa mayor perdonar los errores del marido. Advierte que quien hace daño al hijo ajeno pierde su casa."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le preocupa un problema de salud repentino; conviene atención médica.", "Una pérdida reciente le da miedo (canto de Ọlamba y Eji-Ogogo).", "Quiere entender una dificultad sin negarla.", "Hay un asunto familiar que pide perdón, sin aguantar maltratos."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que la muerte y la enfermedad se aparten.", "Hijos después de mucho buscar.", "La esclava que llega a reina."]}, {"titulo": "Ibi y advertencias", "puntos": ["Desmayo o enfermedad repentina.", "Celos que llevan al crimen.", "Una hija en un tercer matrimonio que necesita protección."]}, {"titulo": "Enseñanza principal", "texto": "La muerte no conoce al sacerdote ni el cielo conoce al médico: por eso se reza. Lo que se esconde en el monte, un segador lo ve desde la palmera."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà hace Ifá a la muerte. La muerte no conoce al sacerdote, el cielo no conoce al médico. La muerte mató a Ọlámbà y afligió al rey de Èjìò. El viento de la derecha sacude la hoja de coco, el viento de la izquierda la sacude: así adivinaron para Ọ̀rúnmìlà Àgbọ̀nnìrègún, que iba a hacerle Ifá a la muerte y escogió a Àgò, el que aparta, como guardián. La muerte que podía haber matado al sacerdote hoy, que se aparte; el sacerdote avanza, que se aparte. La enfermedad que podía haberlo matado hoy, que se aparte. Este rezo se usa para quien se desmaya de pronto o está muy grave, diciendo su nombre en lugar de sacerdote; ante un desmayo o un malestar repentino hay que buscar atención médica de inmediato.", "Ọ̀rúnmìlà y el cuello de la palma. Ọ̀rúnmìlà intentó tener hijos en el árbol de apá y no lo logró; lo intentó en el árbol de oóro y tampoco. Entonces fue al cuello de la palma (òpè). Le pidieron una calabaza con tapa (àdému) y algodón estirado en una tira larga enrollado en ella. Al llegar al cuello de la palma empezó a tener hijos. ¿Quién tiene muchos hijos? La palma. Èdú nunca es estéril.", "Ilẹ̀ gìrìgìrì y Àróòjọ. Ilẹ̀ gìrìgìrì, esposa principal del rey y cervecera de vino, no tenía hijos. Compró a Àróòjọ, una muchacha, para que le ayudara a traer agua. Con los años la muchacha creció y el rey se acercó a ella, y quedó embarazada. El rey le rogó a Ilẹ̀ gìrìgìrì que no se molestara, prometiéndole parte de sus bienes; ella dijo que estaba bien, pero por dentro ardía. Un día que el rey estaba de viaje, Àróòjọ dio a luz un varón; Ilẹ̀ gìrìgìrì recibió al niño, dijo que había nacido muerto, lo metió en una calabaza tapada con tela blanca y lo dejó en un hormiguero del monte para que lo picaran. Un segador de palma la vio desde lo alto de un árbol, sacó al niño, que lloraba, y fue en secreto a contárselo al rey. El rey vio al niño, lo dio a una nodriza, y Àróòjọ iba a escondidas a amamantarlo. A los tres años el rey reunió a todos, puso al niño en el centro y le preguntó a Ilẹ̀ gìrìgìrì si lo conocía; ella dijo que no. El niño corrió hacia la madre que lo amamantaba. El rey dijo: este es el niño que dijiste que había muerto. La casa de Ilẹ̀ gìrìgìrì pasó a Àróòjọ, y la esclava se volvió esposa del rey. Ifá pide a la esposa mayor perdonar los errores del marido: su propia fortuna también llegará."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra la muerte repentina: marcar Ìrẹtẹ̀ Òtúrá en la tierra donde está el enfermo, decir su nombre y el rezo; la tierra se lleva luego a un árbol grande del monte de las ofrendas.", "Para hijos: una calabaza con tapa (àdému) y algodón estirado enrollado en ella.", "Para la hija en su tercer matrimonio: la ofrenda que marque Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà Àgbọ̀nnìrègún aparta a la muerte. La palma (òpè), madre de muchos. El rey y su casa."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Algodón, calabaza con tapa (àdému), palma de aceite, apá, oóro, tierra del lugar."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 224.1 (yorùbá): Ikú komo Awo, / Ọrun komọ Iṣègùn. / Ikú pa Ọlamba o ṣe / Ọba Ejio kanrinkanrin. / O pa Orogidi omọ Oriṣà. / O pa Eji-Ogogo-Agbẹbikopon'wọla. / Afẹfẹ owọ̀ ọ̀tún nṣe / ewé agbon'gbaorogbaoro. / Afẹfẹ owọ̀ osin nṣe / ewe agbon gbaorogbaoro: / a difá fún Ọ̀rúnmìlà Àgbọnnìrègún / tioni ounlọ tẹ Ikú ni Ifá. / O fi Ago ṣe Ojùmpnà. / Ikú tiibapa Awo loni ago, ago, / Awo niọ, ago, ago, / Awo nlọ, ago, ago. / Àrùn tiibapa Awo loni ago, ago, / Awo nlọ, ago, ago.", "REZO: IRETE SUKA APEKANKOLA ADIFAFUN AKUPERU OGUERE ODE OBINI KUAYE OBINI AWA NIFA OBARABANIREGUN MOYORE AYEBE IFA ORUNMILA LORUGBO. KUKUTE KUKU ADIFAFUN NAYIDA LILE TINSOMA ORUNMILA FATINDAEBO FUN AKUKO KAFEREFUN OSHOSI Y YALORDE. IFA IRETE OTUA ESEKAN OPENKAKOLA ADIFAFA AKOPELA EBBO NO KOBINE OBUKO AGUEGUE OTA EBEFA OWO. ESHU MAFEREFUN OBATALA MAFEREFUN.", "REZO: IRETE SUKA APEKANKOLA ADIFAFUN AKUPERU OGUERE ODE OBINI KUAYE OBINI AWA NIFA OBARABANIREGUN MOYORE AYEBE IFA ORUNMILA LORUGBO.KUKUTE KUKU ADIFAFUN NAYIDA LILE TINSOMA ORUNMILA FATINDAEBO FUN AKUKO KAFEREFUN OSHOSI Y YALORDE. IFA IRETE OTUA ESEKAN OPENKAKOLA ADIFAFA AKOPELA EBBO NO KOBINE OBUKO AGUEGUE OTA EBEFA OWO. ESHU MAFEREFUN OBATALA MAFEREFUN.", "SUYERE: EYU REO EWA EYUREO EWA. EYU REO EWA EYUREO EWA. EYU REO EWA EYUREO EWA.", "REZO: KAFEREFUN OSHOSI, OBATALA, YALORDE ATI ORUNMILA. IFA PERIPE KAFEREFUN OSHANLA. ATI OSHOSI.", "REZO: KEDA WERE DA KRIMONA, ABERE NI EKUN, NI ABERE NI EYO IÑA, OMO DA WERE DE KRIMONA. KILONSHE IÑA MO DA WERE, OLODUMARE EYU IÑA MEDA WERE", "REZO: OMO OLUWO ONI OMOTI ORISHA AWO NI IFE OBANIFA UNLO OYE ILU, LODAFUN ORUNMILA, KAFEREFUN OBATALA.", "REZO: EGUN APARENIJA IRETE PEKANKOLA AWO OJU ILE LASHEDA TASHERUBI EBO BAMASHE KILE JERI OPONLOJU SHAJU OWA LOJURU LATENI AWO LODAFUN ORUNMILA.", "SUYERE: ERON TESO YEWE EON TESO YEWE ABRAYAGASI AZOWANO GRONTESO YEWE.", "REZO: IRETE SUKA ADALU IYA LOKUEYE DIDA MAYERE MAYEKUN TIBAYEKUN AYOYONI ELEGBA MOBO BALE ASHA IYA FOYEKUN DAURE KUELE AFEFERIN AIYA TIBOSHE NI LORUN WAWE WOGGUN IYA TIBI LORUN MAWEYENI IYA ELEGBA YOFUN MODE WOFA OUDEDE MODE NI ELEGBA LOYA UREO IYA OSHANLA ODDUPUE LONA OBATALA BI ISHA OYANLA UREFUELE LAYEBI OBATALA I BI ASHE OROLUN KOKODE IFA OBATALA LORUBO OMO SHALI ORUBA IYA.", "REZO: IRETE UN SUKA AWO NERI AWO AWO BORDA OLOFIN IRETE NISUKE NERI AWO ODUDUWA BEBELI AYE IYA BEBELI AYE BAYE OYA YANZA YAYEKAN WAWA NIRE AYE BAWA IKU ORUNMILA ARENIDA OYA SHANIYEKUN OLODUMARE, OLODUMARE NI BAYE AWONIDI AYE SHANGO ABEBETUN ABEBE OSI AWONERI IFA ADIFAFUN ORI."]}]$q$::jsonb))
update estera_sintesis e set secciones=v.sec from nuevas v where e.numero=v.numero and md5(e.secciones::text)=v.viejo returning e.numero;
